NAME = 'sml_BL_2008: Kitab Awal-Jaman maka Kitab Injil'
BOOK = 'I Samuel'

CHAPTERS = {
    1: {
        1: "Na, aniya' dakayu' l'lla niōnan si Elkana maglahat ma kauman Rama ma kabūd-būran Epra'im. Panubu' Epra'im si Elkana itu, min tumpuk si Sūp. Mma'na si Jeroham anak si Elihu, mpu si Tohu ya anak si Sūp.",
        2: "Aniya' duwa h'nda si Elkana, ya si Hanna maka si Pennina. In si Pennina taga-anak bo' si Hanna halam.",
        3: "Kahaba' tahun atulak si Elkana min kaumanna patukad ni Silo supaya pasumba maka anukbal lalabotan ni si Yawe ya Tuhan Sangat Kawasa. Ya magimam ma Silo inān si Opni maka si Pinehas, karuwangan anak imam Eli.",
        4: "Sakahaba' waktu magkulban si Elkana, binahagi'an e'na si Pennina maka saga ka'anakanna.",
        5: "Sagō' labi ahāp bahagi' ya pamuwanna ma si Hanna sabab kaheya lasana ma iya, minsan iya halam kabuwanan anak min kahandak PANGHŪ' -Yawe.",
        6: "Na pagka halam kabuwanan anak si Hanna, sidda iya nijingki maka pinareyo'-deyo' e' kalu'ana si Pennina.",
        7: "Tahun ni tahun buwattina'an na pa'in in kahālan. Sakahaba' waktu katukad sigām ni luma' pagtata'atan ni si Yawe, nijural na pa'in si Hanna e' kalu'ana sampay iya magtangis maka mbal na amangan.",
        8: "Angkan ah'lling h'llana ni iya, yuk-i, “Oy rāng, angay ka anangis na pa'in ilu? Angay ka mbal minsan amangan? Ai karukka'annu? Kulang gi' bahā' halga'ku ma ka'a min sangpū' anak?”",
        9: "Na dakayu' waktu ma Silo, pagubus sigām amangan maka anginum, pabuhat si Hanna. Ina'an asal imam Eli aningkō' ma bangku' ma atag bowa' lawang luma' PANGHŪ'.",
        10: "Na, landu' aheya kasukkalan si Hanna angkan iya anangis to'ongan maka e'na angamu'-ngamu' ni si Yawe.",
        11: "Anganajal iya, yukna, “O Yawe Sangat Kawasa, ummatnu aku. Bang pa'in nda'nu kasukkalanku bo' aku palulinu pahāp. Bang aku dūlannu ati buwanannu anak l'lla, tukbalanku iya ni ka'a pabalik bo' maghinang ni ka'a sat'ggolna allum. Anganajal isab aku in kōkna mbal binagongan.”",
        12: "Ma pangamu'-ngamu' si Hanna ni PANGHŪ' -Yawe, ta'nda' bowa'na e' si Eli.",
        13: "Magkimut-kimut sadja bowa'na, halam magsuwala. Pangannal si Eli in iya nilango,",
        14: 'angkan yukna ma iya, “Arung, angay ka maglango sadja ilu? Timanin binunu!”',
        15: "“Halam aku nilango, tuwan,” yuk sambung si Hanna. “Tu'ud aheya karukka'anku. Halam aku maginum binu atawa ai-ai makalango, paluwasku sadja kasukkalanku ni si Yawe.",
        16: "Da'a aku bistahun d'nda ala'at. Angamu'-ngamu' sadja aku sabab mbal kasandalan karukka'anku itu.”",
        17: "Ah'lling si Eli ni iya, “Pehē' na ka amole',” yukna, “bang pa'in ka mura-murahan asalamat maka kinale pangamu'-ngamu'nu e' Tuhan bangsatam Isra'il.”",
        18: "Ya panambung si Hanna, “Magsukul. Bang pa'in ka kasulutan ma aku, dakayu' sosoho'annu itu.” Jari ala'an na si Hanna minnē'. Aniya' isab takakanna ati ahāp na pamaihu'anna.",
        19: "Pag'llaw dakayu' pa'in, subu-subu lagi', pabangun disi Elkana maka saga anak-h'ndana bo' anumba ni PANGHŪ' -Yawe. Pagubus, amole' na sigām pabīng ni Rama ya lahat sigām. Pahulid si Elkana ni h'ndana si Hanna ati nirūlan e' si Yawe bay pangamu'na.",
        20: "Jari ab'ttong iya ati ta'abut pa'in bulananna anganak iya l'lla. Niōnan e'na Samwel, sabab, yukna, “bay iya amu'ku min si Yawe.”",
        21: "Na, pagga ta'abut na bulanan Paghinang Taubat, patukad disi Elkana magtai'anak ni lahat Silo maghinang ni PANGHŪ' -Yawe, ati tatuman isab e' si Elkana bay najalna ma iya.",
        22: "Sagō' halam ameya' patukad si Hanna. Yukna ni h'llana, “Subay na alutas onde' itu bo' bowaku pehē', ati pamasuku'ku iya ni PANGHŪ'. Jari mahē' iya pat'nna' sat'ggolna allum.”",
        23: "“Hinangun bang ai ya makasulut ka'a,” yuk si Elkana. “Maitu sadja ka sampay talutasnu onde' ilu, bang pa'in tatuman bay janji' PANGHŪ' ma ka'a.” Jari pa'bba si Hanna ma luma' amaruru' onde' inān sampay talutas e'na.",
        24: "Manjari talutas pa'in onde' inān, bo' ariki'-diki' lagi', binowa na iya e' ina'na ni luma' si Yawe ma Silo. Bay isab bowana dakayu' sapi' t'lluntahun umulna maka dakarut tirigu maka dapangisihan binu-anggul.",
        25: "Tasumbali' pa'in sapi' he', ni'nde'an na si Samwel ni si Eli e' matto'ana.",
        26: "Manjari anibahat si Hanna ma si Eli, yukna, “Sapahanku, tuwan, aku na d'nda ya bay an'ngge maitu ma bihingnu angamu'-ngamu' ni PANGHŪ'.",
        27: "Bay aku angamu' anak ati nirūlan e'na pangamu'-ngamu'ku.",
        28: "Angkan na buwattina'an, pamasuku'ku na ni iya onde' itu sat'ggolna allum.” Puwas pa'in he'-i, sinumba na si Yawe ma atag ina'an.",
    },
    2: {
        1: "Manjari anambahayang si Hanna, yukna, “Akōg-koyag pangatayanku ma pasal si Yawe, Pinajatu kosogku ma sabab si Yawe, angkan pagtittowahanku saga bantaku, magkalasigan aku ma sabab da'ugan ya pamuwannu ma aku, O Tuhan.",
        2: "Halam aniya' manusiya' asussi buwat kasussi si Yawe. Sapantun iya Batu Lakit pasindungan, halam aniya' makasibu'an iya.",
        3: "Sasuku kam magmalangkahi subay pahali. Sasuku kam magabbu-abbu subay pabba, sabab si Yawe ya makata'u kamemon. Iya ya angahukum kamemon kahinangan manusiya'.",
        4: "Tara'ug saga sundalu magpapana' ya tamakaesog, saguwā' sasuku bay lumukbu' binuwanan kosog labi-labihan.",
        5: "Sasuku bay asso tagna' magpatiata na bo' aniya' balanja' sigām, sagō' saga a'a bay patay otas mbal na lingantu. Sasuku bay mbal maka'anak, maka'anak na pitu' hekana, sagō' in bay aheka anakna asiya-siya du.",
        6: "Taga-kapatut si Yawe amakallum maka amapatay, amowa saga manusiya' ni ahirat maka amangun sigām.",
        7: "Makaparaya iya ba'anan a'a miskin ati makapamiskin ba'anan a'a dayahan, makapamareyo' iya maka makapamalanga.",
        8: "Tahaun e'na saga miskin min kasigpitan sigām, tapaluwas sigām min kaiya'an. Pinatingkō' sigām magbeya' maka ba'anan kasultanan bo' supaya sigām pinagmahaldika'. Si Yawe asal tag-suku'an alam maka po'onanna, ya pamapanjarihanna dunya maka kapanyapanna.",
        9: "Jagahanna sasuku sigām am'nnal ma iya, sagō' in a'a jahulaka' amatay ma deyom kalendoman. Halam aniya' makapanganda'ug bang hal min kosogna.",
        10: "Magmula isab sai-sai anagga' si Yawe. Pinal'ggonan sigām e'na min langit. Si Yawe ya angahukum katilingkal dunya. Aheya kosog pamuwanna ma a'a ya tahinangna sultan, aheya da'ugan ya pamuwanna ma a'a bay tapene'na.”",
        11: "Manjari, amole' na pabalik si Elkana maka si Hanna ni Rama. Sagō' ya si Samwel ta'bba ma Silo maghinang ni PANGHŪ' -Yawe ma deyo'an si Imam Eli.",
        12: "Na saga anak si Eli itu ala'at kahinangan sigām, mbal magaddatan PANGHŪ'.",
        13: "Mbal isab sigām ameya' ma kauntulan ya bineya' e' saga kaimaman bang aniya' susumbali'an binowa panukbal ni Tuhan. Ma pam'llahan pa'in isi susumbali'an inān, pinapehē' dakayu' sosoho'an imam amowa tugsukna aheya.",
        14: "Jari ai-ai tatugsuk e' sosoho'an inān, ai na ka ma kaha' atawa ma kaldero, ya na suku' imam. Buwattē' na pa'in addat kaimaman ma saga bangsa Isra'il waktu kapehē' sigām ni Silo.",
        15: "Sagō' buwattina'an, ma halam lagi' tatunu' lanab sumbali'an, aniya' sosoho'an imam pinapehē' ah'lling ni a'a magtukbal. Yukna, “Pamuwanun ma imam susumbali'an amata' ilu bo' tinapa e'na. Mbal tinaima' e'na bang talaga' na, luwal subay amata'.”",
        16: "Bang anambung a'a magtukbal inān, yukna, “Subay atunu' lanabna bo' ka angā' ya ingga kabilahiannu,” na, pinah'llingan iya e' sosoho'an imam e'. Yukna, “Hē! Mbal makajari! Sōngin na magtūy sabab bang ka mbal bilahi, agawku sadja min ka'a.”",
        17: "Na, landu' asammal ma pang'nda' PANGHŪ' bay kahinangan saga anak si Eli itu sabab talumu' he' sigām lalabotan ya tinukbal ma iya.",
        18: "Malaingkan, ina'an si Samwel maghinang na ni si Yawe minsan iya abata' gi'. Magbinadju' iya epod pangalampik jubana.",
        19: "Tahun ni tahun, nihinangan si Samwel juba he' ina'na, binowahan iya ma waktu katukad si Hanna maka h'llana pehē' bo' maghinang Pagtaubat.",
        20: "Jari, niamu'an barakat disi Elkana maglakibini e' si Eli. Yukna, “Mura-murahan bang pa'in kam kabuwanan anak e' PANGHŪ' min h'ndanu itu paganti' min onde' bay amu'na ma iya ati bay du tukbalanna pabalik ni iya.” Pagubus, amole' na sigā.",
        21: "Manjari, pinagka'inagonan si Hanna e' PANGHŪ' -Yawe ati kabuwanan gi' iya t'llu anak l'lla maka duwa anak d'nda. Jari pasulig na pa'in si Samwel hinabuna maghinang ni si Yawe.",
        22: "Na, minsan ato'a na si Eli, takale e'na pasal kamemon kalumu'an ya nihinang e' saga anakna l'lla ma saga bangsa Isra'il. Maka takale du isab e'na pasal paghulid sigām maka saga kar'ndahan ya maghinang ma Luma' Tolda Pagsasabuhan inān.",
        23: "Angkan ah'lling si Eli ni saga anakna, yukna, “Takaleku min saga a'a in kahinanganbi asammal! Angay kam magkahinangan buwattilu?",
        24: "Saga anak, halli'inbi na saga kahinanganbi ilu sabab ala'at kinale suli-suli ya pasaplag inān ma ba'anan jama'a PANGHŪ'.”",
        25: "Ah'lling gi' si Eli, yukna, “Bang a'a makarusa ma pagkahina manusiya', makapati'llot Tuhan ma sigām. Sagō' bang a'a makarusa ma PANGHŪ', na sai na gi' magpati'llot ma iya?” Saguwā' mbal ameya' saga anak si Eli ma pami'atna, sabab asal kahandak PANGHŪ' pinapatay sigām.",
        26: "Na, pasōng na pa'in paheya si Samwel maka pasōng ta'una. Pasōng isab iya makasulut atay PANGHŪ' sampay manusiya'.",
        27: "Dakayu' llaw, aniya' a'a sosoho'an Tuhan pinapehē' ni si Eli amasampayan iya lling, yukna, “Buwattitu ya pangallam si Yawe ma ka'a, ‘Bay aku magpanyata' ma ka'mbo'-mbo'annu si Harun waktu sigām ma lahat Misil ma deyo'an pagparinta Pira'un.",
        28: "Bay tapene'ku si Harun min kamemon kapanubu'an bangsa Isra'il bo' supaya iya pinat'nna' imam maghinang ma lugal pagtutukbalan ni aku, maka anunu' kamanyan, maka amowa epod ma waktu kasōdna ni matahanku. Bay isab buwananku bahagi' ma saga imam min ba'anan lalabotan ya tinunu'an aku he' bangsa Isra'il.",
        29: "Jari angay halipulubi saga kukulbanan maka lalabotan ya bay soho'ku tinukbalan ma Luma'ku? Angay paheyanu saga anaknu labi gi' min aku? Sabab ilu pagnapsuhanbi isi sumbali'an ahāp to'ongan ya ngā'bi min saga kukulbanan kamemon bay panukbal ma aku e' saga a'aku bangsa Isra'il!’”",
        30: "Amissala gi' sosoho'an Tuhan inān, yukna, “Angkan buwattitu pangallam si Yawe ya Tuhanbi bangsa Isra'il, yuk-i, ‘Tagna', aniya' bay panganjanji'ku ma ka'am panubu' si Libi, luba'na ka'am ma tumpukan mma'nu, subay magimam ni aku ni kasaumulan. Sagō' mbal na. Palangaku na pa'in sasuku magmahaltabatan aku, sagō' pareyo'ku sasuku mbal magaddatan aku.",
        31: "Kalehun pahāp, at'kka du waktu papu'utku umulnu maka umul saga anak-mpunu, jari halam aniya' ma panubu'nu magkato'a.",
        32: "Angkan magkarukka'an kam ati mbal na takinambi kahāpan ya pamuwanku ma bangsa Isra'il. Halam na aniya' min panubu'nu maka'abut kato'a sigām.",
        33: "B'nnal aniya' tubu'nu pasagaranku magimam ma matahanku, sagō' binuta iya sampay makananam karukka'an landu' bisana. Jari in kaheka'an panubu'nu pinatay bono' ma sinosōng.",
        34: "“‘Ya paltanda'an, magdora' amatay karuwangan anaknu, si Hopni maka si Pinehas, ma dang'llaw.",
        35: "Ati paniya'ku imam dakayu', a'a kapangandolanku, lilla' angahinang kamemon maksudku maka kabaya'anku. Patumanku saga panubu'na bo' aniya' min sigām maghinang ma matahan sultan ya pene'ku sampay ni kasaumulan.",
        36: "Manjari, in kamemon takapin ma panubu'nu magpatireyo' ma iya angamu' takakan maka pilak. Angamu' sigām junjung bang pa'in sigām binuwanan hinang minsan ai na ma saga imam, supaya aniya' takakan sigām.’”",
    },
    3: {
        1: "Anubul-nubul pa'in si Samwel, maghinang iya ni PANGHŪ' -Yawe ma deyo'an si imam Eli. Ma waktu ina'an, alahang si Yawe amissala ni manusiya' maka alahang aniya' manusiya' pinakalehan suwalana.",
        2: "Dakayu' sangom, ina'an si Eli atuli ma bilikna. Ahawhaw na pang'nda'na, mbal na agon makapatong pahāp.",
        3: "Si Samwel isab ina'an abahak ma luwasan bilik pagpat'nna'an Ba'ul Tuhan ya ma deyom Luma' Pagtata'atan ni PANGHŪ' -Yawe. Ma halam lagi' ap'dda palita'an,",
        4: "nilinganan si Samwel e' si Yawe. Anambung iya, yukna, “Owa', itiya'!”",
        5: "Magtūy iya parai'-dai' pehē' ni si Eli. “Itiya' aku,” yukna. “Bay aku linganannu.” Sagō' anambung si Eli, yukna, “Halam ka bay lingananku, pehē' ka atuli pabalik.” Angkan pabalik si Samwel ni pabahakanna.",
        6: "Manjari, angalingan pabalik si Yawe, yukna, “Samwel!” Magtūy pabungkal si Samwel bo' pehē' ni si Eli, “Itiya' aku,” yukna. “Bay aku linganannu.” Ah'lling si Eli ni iya, “Oto',” yukna, “halam aku bay angalingan. Pehē' na ka pabalik ni patulihannu.”",
        7: "Ma waktu ina'an, akulang gi' pana'u si Samwel pasal PANGHŪ' -Yawe, maka halam gi' aniya' palman PANGHŪ' bay pamukis ma iya.",
        8: "Jari, angalingan na isab si Yawe ma si Samwel, kat'lluna na. Magtūy iya magdai'-dai' pehē' ni si Eli maka he'na ah'lling, “Itiya' aku,” yukna. “Bay du aku linganannu.” Na tasayu e' si Eli, si Yawe ya angalinganan onde' inān.",
        9: "Angkan iya ah'lling ma si Samwel, yukna, “Oto', pabahak ka pehē'. Bang ka nilinganan pabīng, anambung ka buwattitu yuknu, ‘Ya PANGHŪ', amissala na ka sabab akale du sosoho'annu itu.’” Manjari, pabīng na si Samwel ni pabahakanna.",
        10: "Na, magpanyata' na si Yawe ma si Samwel maka e'na angalingan buwat bay dahū. Yukna, “Samwel! O Samwel!” Anambung si Samwel, yukna, “Amissala ka kono', sabab akale du sosoho'annu itu.”",
        11: "Ah'lling si Yawe ma si Samwel, “Kalehun lapal itu!” yukna. “Aniya' hinang makatāw-tāw song hinangku ma deyom bangsa Isra'il, ati tak'bbal atay sasuku makakale.",
        12: "Ma waktu ina'an, hinangku du kamemon bay pangallamku ma pasal saga panubu' si Eli.",
        13: "Bay na iya asal haka'anku pasalan hukuman ya pamat'kkaku ma panubu'na. Sabab halam nilāng e'na kalumu'an ya bay nihinang e' saga anakna, minsan du bay kata'uwanna.",
        14: "Angkan aku bay anapa pasal saga panubu' si Eli, yukku, ‘Mbal ta'ampun paldusahan sigām minsan ai tataubatan atawa lalabotan.’”",
        15: "Manjari, tatuli na pabalik si Samwel sampay subu. Pagbati'na pa'in, niukab he'na lawang Luma' Pagtata'atan ni PANGHŪ' -Yawe he'. Tināw iya amissalahan si Eli pasal bay takalena min Tuhan,",
        16: "sagō' nilinganan iya e' si Eli. “Samwel! Otō'!” yukna. Jari anambung si Samwel yukna, “Oy itiya' aku.”",
        17: "Atilaw si Eli yukna,“Ai bay pamissala Tuhan ma ka'a? Da'a limbungin min aku. Patut ka pinat'kkahan mulka' kaginisan e' Tuhan bang ka ganta' maglimbung ai-ai bay llingna ma ka'a.”",
        18: "Angkan nihaka kamemon e' si Samwel, halam iya maglimbung. Jari ah'lling si Eli, “In iya Tuhan-asal-Tuhan taga-kapatut angahinang bang ai kabaya'anna.”",
        19: "Manjari, pataptap PANGHŪ' -Yawe ma si Samwel sampay iya paheya, angkan atuman kamemon pah'llingna.",
        20: "Takilā iya e' kamemon bangsa Isra'il min lahat Dān sampay ni Be'erseba, in iya nabi si Yawe.",
        21: "Tinagna'an minnē', magpa'nda' na pa'in PANGHŪ' ma si Samwel ma Silo ati maina'an iya amakilā di-na labay min lapalna.",
    },
    4: {
        1: "Manjari itu, pasaplag na lapal si Samwel ma kaluha'an bangsa Isra'il. Na paluwas saga sundalu Isra'il min pustu sigām bo' magbono' maka bangsa Pilistin. Ina'an bangsa Isra'il magpustu ma atag Ebeneser ati ma Apek ya pagpustuhan bangsa Pilistin.",
        2: "Manjari magsakap saga sundalu Pilistin angandugpak bangsa Isra'il. Aheya landu' bono' ma llaw inān, jari tara'ug bangsa Isra'il, aniya' saga mpat ngibu heka sigām amatay maina'an ma pagbono'an.",
        3: "Makapole' pa'in ni pustu saga sundalu Isra'il ya takapin allum, tinilaw sigām he' pagmatto'ahan bangsa Isra'il, yuk-i, “Angay angkan kitam pinasagaran e' PANGHŪ' -Yawe bo' tara'ug e' ba'anan bangsa Pilistin? Ahāp lagi' kitam pehē' ni Silo angā' Ba'ul Paljanji'an si Yawe bo' pagapi' ma kitam amuwasan kitam min ga'osan saga bantatam.”",
        4: "Manjari, magpanoho'an sigām saga a'a pehē' ni Silo angā' Ba'ul Paljanji'an si Yawe Sangat Kawasa, ya aningkō' asal min llot duwa mala'ikat pikpikan, ya ma sa'ob ba'ul inān. Ina'an isab karuwangan anak si Eli, ya si Opni maka si Pinehas, bay ameya' ma Ba'ul Paljanji'an e'.",
        5: "Pagt'kka pa'in Ba'ul Paljanji'an si Yawe ni pustu bangsa Isra'il, magtūy sigām magolang pakosog to'ongan angkan ajogjog sampay tana'.",
        6: "Pagkale saga bangsa Pilistin ma pagolang bangsa Isra'il itu, magtilawan sigām di-sigām, yuk-i, “Ai bahā' kahiyulan saga Hibrani he'?” Makata'u pa'in saga bangsa Pilistin, ina'an Ba'ul si Yawe bay binowa ni pustu bangsa Isra'il,",
        7: "magtūy sigām sinōd tāw. “Arōy!” yuk sigām. “Aniya' tuhan maina'an ma pustu. Mamarahi na kitam itu! Yampa aniya' buwattitu!",
        8: "Magmula na kitam! Halam aniya' angalappas kitam min kawasa saga tuhan ga'osan itu! Ya na ko' ina'an saga tuhan bay amat'kka bala' kaginisan ma bangsa Misil ma lahat paslangan he'.",
        9: "Oy! Ka'am saga bangsa Pilistin, pakuyas kam amono'. Paesog kam angatu, sabab bang mbal, tabanyaga' kitam e' saga Hibrani itu, buwat bay pamanyaga'tam ma sigām!”",
        10: "Angkan amono' pakosog to'ongan saga a'a Pilistin ati tara'ug e' sigām bangsa Isra'il. Makalandu' aheka abugtang, t'llumpū' ngibu heka sundalu Isra'il amatay. Jari sasuku bay takapin wa'i maglahian amole' ni pustu sigām.",
        11: "Ta'agaw e' bangsa Pilistin Ba'ul Tuhan min saga bangsa Isra'il maka amatay isab si Hopni maka si Pinehas, karuwangan anak si Eli.",
        12: "Na, ma llaw du ina'an, aniya' dakayu' l'lla min panubu' Benjamin bay makalahi min pagbono'an tudju ni Silo. Gineret e'na badju'na maka kapē'an bagunbun kōkna, tanda' pagdukkana.",
        13: "Pagt'kkana na ni Silo, ina'an asal si Eli ma tingkō'anna ma bihing lān amantaw, sabab asusa pangatayanna ma pasalan Ba'ul Tuhan. Manjari paghaka l'lla inān ma bay paniya' ma pagbono'an, magtūy maglemongan kamemon a'a ma kauman inān.",
        14: "Ma waktu inān, siyampū' na maka waluntahun umul si Eli, mbal na maka'nda', hal amantaw sadja. Jari takale pa'in e' si Eli pagalud inān, atilaw iya, “Angay angkan magpangalud saga a'a itu?” Sinekot iya magtūy e' a'a bay makalahi inān.",
        15: "Ma waktu inān, siyampū' na maka waluntahun umul si Eli, mbal na maka'nda', hal amantaw sadja. Jari takale pa'in e' si Eli pagalud inān, atilaw iya, “Angay angkan magpangalud saga a'a itu?” Sinekot iya magtūy e' a'a bay makalahi inān.",
        16: "“Tuwan,” yukna, “yampa aku alahi pi'itu min pagbono'an.” Atilaw pabalik si Eli, “Oto',” yukna, “ai bay tum'kka ni ka'am?”",
        17: "Ya sambung a'a inān, “Tuwan,” yukna, “maglahian saga sundalu Isra'il sabab tara'ug e' bangsa Pilistin. Kamatayan aheka a'atam ati talapay anaknu si Hopni maka si Pinehas. Ta'agaw isab Ba'ul Tuhan.”",
        18: "Pagkale si Eli ma pasalan ba'ul e', magtūy iya pahantak min paningkō'an maina'an ma atag pagsosōran ni kauman. Pahantak iya ni buli'an ati apōng buli'-k'llongna. Jari amatay na iya sabab ato'a na iya maka landu' al'mmok. Mpatpū' tahun bay kapagmakōkna ma bangsa Isra'il.",
        19: "Na, ma waktu inān, bulanan na ayuwan si Eli, ya h'nda si Pinehas. Pagkale d'nda itu ma habal pasal Ba'ul Tuhan bay ta'agaw e' bangsa Pilistin, maka wa'i amatay h'llana maka mato'ana, kap'ddi'an iya sampay anganak. Sagō' kahunitan sidda iya ma paganakna.",
        20: "Magkamamatay pa'in iya, amūng saga panday, yuk-i, “Ndū' nneng, da'a ka tināw. Nda'un ba, l'lla ko' anaknu itu.” Sagō' halam iya makasambung minsan ai.",
        21: "Ma halam lagi' iya amatay, Ikabod ya pangōnna ma onde' inān. “Sabab,” yukna, “wa'i paokat in sahaya Tuhan min bangsa Isra'il.” Angkan iya makapah'lling buwattē' sabab wa'i na bay ta'agaw Ba'ul Tuhan e' bangsa Pilistin, maka in h'llana maka mato'ana wa'i na amatay.",
        22: "Ma halam lagi' iya amatay, Ikabod ya pangōnna ma onde' inān. “Sabab,” yukna, “wa'i paokat in sahaya Tuhan min bangsa Isra'il.” Angkan iya makapah'lling buwattē' sabab wa'i na bay ta'agaw Ba'ul Tuhan e' bangsa Pilistin, maka in h'llana maka mato'ana wa'i na amatay.",
    },
    5: {
        1: "Na, pagga ta'agaw Ba'ul Tuhan e' bangsa Pilistin, binowa na e' sigām min Ebeneser tudju ni Asdod ya da'ira sigām.",
        2: "Manjari, ma Asdod pa'in, binowa Ba'ul itu ni deyom langgal pagsusumbahan si Dagon ya pagtuhanan sigām bo' pinapagbihing maka ta'u-ta'una.",
        3: "Pag'llaw dakayu' pa'in, subu-subu lagi', pasōd saga a'a Asdod ni langgal si Dagon inān. Pagsōd itu, ta'nda' ta'u-ta'una pakutung ma lantay, sali' hantang pasujud ma dahuwan Ba'ul si Yawe! Jari pinat'ngge ta'u-ta'u inān e' sigām ni asal bay pamat'nna'an iya.",
        4: "Saguwā', pag'llaw dakayu' na isab, wa'i na isab ta'u-ta'u si Dagon pakutung pabalik. Ya du, sali' pasujud ma dahuwan Ba'ul si Yawe! Magkapōng-pōng kōkna maka tanganna ina'an ma bowa' lawang. Hal du baranna ya takapin tibu'uk.",
        5: "Ya itu sababanna angkan sampay ni buwattina'an saga imam Pilistin atawa sai-na ma Asdod mbal pagi'ik ma bowa' lawang bang pasōd ni langgal si Dagon inān.",
        6: "Na, pinat'kkahan e' PANGHŪ' -Yawe bala' mamarahi bisana ma katilibut Asdod maka saga kauman ma jadjahan ina'an. Kapē'an sigām saga butig a'aslag ma baran sigām.",
        7: "Pag'nda' saga a'a Asdod ma bay tumaluwa' ni sigām inān, ah'lling sigām ni dangan-parangan, yuk-i, “Halam dapat! Mbal manjari pat'nna' maitu in Ba'ul Tuhan bangsa Isra'il, sabab itiya' kitam binantahan e'na. Tantu kitam magmula sampay tuhantam si Dagon.”",
        8: "Manjari pinalinganan kamemon pagnakura'an bangsa Pilistin ati tinilaw sigām, yuk-i, “Ai na hinangtam ma Ba'ul ya suku' pagtuhanan bangsa Isra'il itu?” Ya sambung sigām, “In ba'ul suku' tuhan bangsa Isra'il ilu subay pinapinda ni da'ira Gāt.” Angkan pinapinda Ba'ul inān.",
        9: "Saguwā', bay pa'in itu pinapinda ni Gāt, pinat'kkahan bala' da'ira inān e' PANGHŪ' -Yawe. Ahiluhala' katilibut paglahat maina'an sabab bay du isab pinat'kkahan butig kamemon saga manusiya', min onde'-onde' ni matto'ana.",
        10: "Angkan bay pinalanjal Ba'ul Tuhan inān min Gāt ni da'ira Ekron. Hinabu binowa pasōd Ba'ul inān ni da'ira Ekron, magpangolang saga a'a maina'an, yuk sigām, “Arōy! Itiya' na ba'ul sin tuhan bangsa Isra'il binowahan kitam supaya kitam alaglag!”",
        11: "Manjari, pinatimuk kamemon pagnakura'an ma bangsa Pilistin ati ah'lling saga a'a Ekron ma sigām, yuk-i, “Pala'anunbi m'nnitu in Ba'ul Tuhan Isra'il ilu ati pabalikunbi pehē' ni bay asal pat'nna'anna. Mamarahi na to'ongan kitam itu, magkamatay kamemon!” Angkan buwattē' pah'lling saga a'a inān sabab sinōd tāw makapatay. Tu'ud landu' abisa in bala' pinat'kkahan sigām e' Tuhan.",
        12: "Na, sasuku sigām halam amatay e' bala', bay kat'kkahan butig aheka. Jari in pagaruhuy saga a'a ma da'ira inān pa'abut sampay ni langit.",
    },
    6: {
        1: "Ta'abut pa'in pitumbulan t'ggol Ba'ul si Yawe ma lahat Pilistin,",
        2: "pinalinganan pina'an saga kaimaman maka saga magpuputika' e' saga a'a Pilistin bo' supaya pangaruhan e' sigām. Yuk panilaw sigām, “Ai subay hinang kami ma Ba'ul si Yawe itu? Haka'inbi kami bang buwattingga e' kami amabalik iya ni bay pat'nna'anna tagna'?”",
        3: "Anambung saga a'a pangaruhan itu, yuk-i, “Ebot-ebot, bang kam anganggara' amabalik ba'ul ya suku' tuhan bangsa Isra'il, da'a pabalikunbi ma halam aniya' ai-aina pinabeya'. Pabeya'unbi isab tutukbalan pagtaubatan dusabi bo' kam kauli'an, ati minnē' kata'uwanbi bang angay kam pinat'kkahan bala' e' Tuhan.”",
        4: "Sakali anilaw saga a'a Pilistin, yuk sigām, “Tutukbalan taubat ai ya patut pamuwan kami ma tuhan itu?” Anambung saga imam maka saga magpuputika' inān, yuk-i, “Angahinang kam bulawan pinakaluwa butig maka ambaw. Subay lima-lima hekana buwat du isab heka saga pagnakura'an bangsa Pilistin. Sabab magsali' du bala' ya makataluwa' ni ka'am maka ni saga pagnakura'anbi.",
        5: "Angahinang kam bulawan pina'anggil ni butig maka ni ambaw ya angamula kaluha'an paglahattam itu, ati tukbalinbi ni Tuhan bangsa Isra'il tanda' sin pamaheyabi ma iya. Kalu iya mura-murahan ma'ase' ma ka'am ati la'ananna bala' ya pamat'kkana ni ka'am maka ni saga tuhanbi sampay lahatbi.",
        6: "Da'a kam magmatuwas. Da'a kam pasali' ni bay kahinangan Pira'un maka saga bangsa Misil ma waktu tagna' he'. Subay sadja bay makalandu' kabinsana'an pinat'kkahan sigām e' Tuhan bo' yampa sigām anugutan saga bangsa Isra'il ala'an minnē'.”",
        7: "Na, magpanoho'an saga imam bangsa Pilistin maka saga magpuputika' inān. Yuk sigām, “Pasakapunbi karitun baha'u, maka angā' kam duwa sapi' duru'an halam gi' bay kapangangguyuran karitun. Pahengkotunbi sapi' ilu ni karitun, sagō' pasaddīhun saga anak-anakna ma deyom kamalig.",
        8: "Jari duwa'unbi Ba'ul si Yawe pehē' ni karitun. Ati pat'nna'unbi isab ma bihing ba'ul ilu dakayu' tu'ung pangisihan saga tataubatan bulawan ya tukbalanbi ni iya. Taruwa' pa'in, pal'ngnganunbi saga sapi' angangguyud karitun ilu pi'ingga-pi'ingga patudjuhanna.",
        9: "Sagō' nda'unbi na pa'in. Bang patudjuhanna ilu Bet-Semes ya ma lahat bangsa Isra'il, minnē' kata'uwantam si Yawe ya bay amat'kkahan kitam bala' itu. Sagō' bang saddī patudjuhan, na ngga'i ka iya ya bay angamulahan kitam. Tu'ud magsalta' sadja.”",
        10: "Jari bineya' e' saga a'a Pilistin panoho'an inān. Ningā' e' sigām duwa sapi' d'nda bo' pinaengkot ma karitun. Saga anak-anakna bay pinagal ma kamalig.",
        11: "Sakali, pinaruwa' na Ba'ul si Yawe inān ni karitun pinapagbeya' maka tu'ung ya pangisihan saga bulawan bay pina'anggil ni ambaw maka butig e'.",
        12: "Manjari itu, lum'ngngan na saga sapi' inān magin'ngngong. Amontolan sigām tudju ni Bet-Semes ma halam pagbeklo'-beklo'na, ai na ka ni kowan atawa ni gibang. Ina'an paurul ma buli'an saga pagnakura'an bangsa Pilistin sampay ni bihing kauman Bet-Semes.",
        13: "Ina'an isab saga a'a Bet-Semes magani pai-tirigu ma kapantayan. Jari pagtongas sigām, ta'nda' e' sigām Ba'ul Tuhan angkan landu' sigām kinōgan.",
        14: "Makat'kka pa'in karitun inān ni huma si Yussa' a'a Bet-Semes, pahogga' na ma bihing dakayu' batu aheya. Paghogga' pa'in itu, ningā' e' saga a'a maina'an kayu bay pangahinang karitun e' bo' tin'tta' pangayu. Sinumbali' isab saga sapi' he' bo' tinunu' tutukbalan pagtaubat ni PANGHŪ' -Yawe.",
        15: "Nihawas ba'ul e' saga kal'llahan panubu' si Libi, beya' isab maka tu'ung ya isihan pamulawan bay pina'anggil ni butig maka ambaw. Tahawas pa'in, bay pinabangkat e' sigām ni diyata' batu aheya. Jari ma llaw ina'an du, saga a'a kamemon ya pat'nna' ma Bet-Semes bay anukbal ni PANGHŪ' -Yawe saga susumbali'an pinagtunu' maka lalabotan pagtaubat.",
        16: "Ta'nda' pa'in kahinangan itu e' saga lima pagnakura'an bangsa Pilistin ya bay paurul e', magtūy sigām amole' pabalik ni Ekron, ma llaw ina'an du.",
        17: "Na, in butig bulawan ya pinabeya' e' bangsa Pilistin pagtaubat ni si Yawe, bay lima hekana bo' pinapagkaniya-kaniya ma saga pagnakura'an sigām lima hekana isab. Hatina dakayu' ma Asdod, dakayu' ma Gasa, dakayu' ma Askelon, dakayu' ma Gāt maka dakayu' isab ma Ekron.",
        18: "Damikiyanna isab saga ambaw bulawan, pinapagkaniya-kaniya ma saga kuta' maka kauman ya suku' pagnakura'an bangsa Pilistin lima hekana he'. Ya batu aheya isab bay pamat'nna'an Ba'ul si Yawe, ina'an masi ma huma si Yussa' a'a Bet-Semes, pamandogahan ma bay paniya' mahē'.",
        19: "Sagō' aniya' a'a pitumpū' hekana bay pinapatay e' Tuhan ma sabab kapang'nda' sigām ni deyom Ba'ul e'. Sakali magdukka saga lūng-kampung sigām ma pasalan hukuman bay pamat'nna' PANGHŪ' ma sigām.",
        20: "Angkan sigām magpangaruhuy, yuk-i, “Sai bahā' taga-kapatut pa'alop ni si Yawe, ya Tuhan sussi itu? Sai pamabeya'antam Ba'ul itu bo' supaya makala'an min deyomantam?”",
        21: "Angkan sigām bay amapehē' saga sosoho'an patukad ni Kiriyat-Jarim angahaka'an saga a'a maina'an pasal palkala' itu, yuk-i, “Itiya' pinabalik e' saga bangsa Pilistin in Ba'ul si Yawe. Bang pa'in kam pi'itu bo' bowahunbi pi'ilu ni lahatbi.”",
    },
    7: {
        1: "Manjari, in Ba'ul si Yawe bay ningā' pehē' ni Bet-Semes e' saga a'a min Kiriyat-Jarim, ati binowa ni luma' si Aminadab maina'an ma būd-būd. Si Eleyasar anak si Aminadab ya bay pinat'nna' anganjagahan Ba'ul si Yawe.",
        2: "At'ggol kamaina'an Ba'ul Paljanji'an ma Kiriyat-Jarim, aniya' saga duwampū' tahun t'ggolna. Ma waktu inān, magdohon sidda kamemon saga bangsa Isra'il maka angamu'-ngamu' na pa'in ni PANGHŪ' -Yawe.",
        3: "Manjari ah'lling si Samwel ma mahadjana' Isra'il kamemon, yukna, “Bang sab'nnal-b'nnal kam magtaubat min deyom ataybi bo' kam pabalik to'ongan ni si Yawe, timaninbi na saga tuhan-tuhan maka ta'u-ta'u si Astoret ya pagtuhanan bangsa liyu. Pabontolunbi itikadbi ni si Yawe ya Tuhanbi. Ammalunbi iya sadja, ati tantu kam lappasanna min komkoman saga Pilistin itu.”",
        4: "Angkan tinaikutan e' bangsa Isra'il kamemon saga Ba'al maka Astoret ya bay pagtuhan-tuhanan sigām bo' angisbat ni si Yawe ma halam aniya' tuhan saddī.",
        5: "Sakali ah'lling si Samwel ni saga a'a Isra'il, yukna, “Patimuk kam kamemon ma kauman Mispa bo' kam amu'-amu'anku ni PANGHŪ' -Yawe.”",
        6: "Ma Mispa pa'in, bay sigām angā' bohe' bo' binu'usan ma matahan si Yawe pangahulmat sigām ma iya. Ma llaw du isab inān magpuwasa sigām kamemon, maka maina'an isab sigām bay magsab'nnal ma PANGHŪ' -Yawe, yuk-i, “B'nnal taga-dusa kami ma PANGHŪ'.” Manjari maina'an ma Mispa si Samwel ya magmakōk ma bangsa Isra'il.",
        7: "Pagta'u pa'in bangsa Pilistin ina'an saga a'a Isra'il magtipun ma Mispa, magtūy magsakap saga nakura' sigām bo' palanjal pina'an bahasa angandugpak. Na, takale pa'in habal itu e' saga a'a Isra'il, magtūy sigām magtāwan ma saga a'a Pilistin.",
        8: "Sakali anganjunjung sigām ni si Samwel, yuk-i, “Palanjalun pangamu'-ngamu'nu ni si Yawe ya Tuhantam bo' supaya kitam lappasanna min saga Pilistin itu.”",
        9: "Sakali, aniya' bili-bili halam gi' talutas bay ningā' e' si Samwel. Sinumbali' e'na bo' tinunu' pagtukbalna pagtaubatan ni si Yawe. Angamu'-ngamu' na pa'in si Samwel ni PANGHŪ' ma pasalan saga ummat Isra'il, jari kinale pangamu'-ngamu'na.",
        10: "Na, hinabu si Samwel magtukbal tataubatan ni Tuhan, ina'an na pasekot ba'anan a'a Pilistin amowa magbono' ma saga a'a Isra'il. Saguwā' ma llaw du isab inān, aniya' l'ggon makalandu' kosogna pinaniya' e' si Yawe ma saga sundalu Pilistin angkan landu' asasaw pikilan sigām. Tabowa sigām sikalahian ati tara'ug sigām e' bangsa Isra'il.",
        11: "Magluwasan magtūy saga magbobono' Isra'il anurul saga Pilistin e'. Jari pinagpapatay sigām e' saga a'a Isra'il ma palabayan sampay makaliyu min kauman Bet-Kār.",
        12: "Manjari itu, angā' batu aheya si Samwel bo' pinat'nna' e'na ma llot Mispa maka Sēn. Ebeneser ya pangōnna ma batu inān sabab, yukna, “Si Yawe ya bay anabangan kami sampay pi'itu.”",
        13: "Jari tara'ug saga bangsa Pilistin ati halam na magbalik-balik parugpak ni kalahatan bangsa Isra'il. Sat'ggol si Samwel allum gi', niatuhan na pa'in e' si Yawe saga bangsa Pilistin.",
        14: "Ta'ā' pabalik e' bangsa Isra'il saga kaluma'an min Ekron sampay ni Gāt, kalahatan bay kalongkopan e' bangsa Pilistin ma waktu palabay. Talappas isab min komkoman bangsa Pilistin saga paglahat kasehe' ya ma jadjahan ina'an-i, maka magsulut isab bangsa Isra'il maka bangsa Amor, mbal na magbono'.",
        15: "Pasangdan na pa'in si Samwel magmakōk ma bangsa Isra'il sat'ggolna allum.",
        16: "Tahun ni tahun, maglibutan iya saga paglahat min jadjahan Betel sampay ni Gilgal maka ni Mispa supaya auntul kapagmakōkna ma saga jama'a Isra'il.",
        17: "Saguwā' amole' na pa'in iya ni kauman Rama, ya lahatna porol. Maina'an isab iya amal'ngngan kapagmakōkna ma saga a'a Isra'il. Aniya' isab pagtutukbalan bay nihinang e' si Samwel ma Rama inān pangahulmat ma si Yawe.",
    },
    8: {
        1: "Ato'a pa'in si Samwel, pinat'nna' e'na saga anakna l'lla maghuhukum ma bangsa Isra'il.",
        2: "Si Jowel ya ōn anakna kasiyakahan, jari si Abija ya pasunu'. Lahat Be'erseba ya paghuhukuman sigā.",
        3: "Sagō' karuwangan anak si Samwel itu halam an'ppu iya ma addat-tabi'at, sabab napsuhan sigā ma pilak. Pagkatambahan sigā, mbal isab abontol pangahukum sigā.",
        4: "Angkan magtimuk kamemon pagmatto'ahan bangsa Isra'il bo' pehē' ni si Samwel ma Rama.",
        5: "Ah'lling sigām ni iya, yuk-i, “Ato'a na ka, tuwan, maka saga anaknu itu mbal ameya' ma kal'ngnganannu. Na,” yuk sigām, “ahāp lagi' pat'nna'in kami sultan magnakura'an kami buwat bangsa kasehe'.”",
        6: "Sagō' ab'nsi si Samwel ma pangamu' sigām, ya mikipat'nna' sultan pagnakura'an sigām, angkan iya angaru ni PANGHŪ' -Yawe.",
        7: "Anambung PANGHŪ' ma si Samwel, yukna, “Dūlin bang ai ya pinahinang e' saga ummat ilu ma ka'a. Asal du ngga'i ka ka'a ya sinulak e' sigām sagō' aku maka kapagsultanku.",
        8: "Min waktu gi' bay kapamowaku sigām paluwas min lahat Misil sampay ni kabuwattituhan, sinulak na pa'in aku e' sigām pagka sigām pasumba ni saga tuhan-tuhan saddī. Jari ya du isab ilu ya nihinang e' sigām ma ka'a.",
        9: "Na beya'un bang ai kabilahian sigām, sagō' banda'in sigām to'ongan. Pahati'un sigām pahāp bang buwattingga palantara sultan ya song magnakura'an sigām.”",
        10: "Manjari, binissala e' si Samwel kamemon bay pangallam ma iya e' PANGHŪ'. Yukna ni saga a'a ya angamu' pinat'nna'an sultan,",
        11: "“Buwattitu kahinangan sultan ya song magsultanan ka'am. Ningā' e'na saga ka'anakanbi l'lla nihinang sundalu magbeya' maka saga kalesana pagbobono' maka saga a'ana magpangura'. Kasehe'an anakbi nihinang e'na magpaparagan min dahuan saga kalesana.",
        12: "Kasehe'an nihinang e'na pagnakura'an ma saga tumpukan sundalu, ai na ka ma dangibu, ai na ka ma limampū'. In kasehe'an isab nihinang e'na maga'araru maka maga'ani ma humana, maka kasehe'an sinō' maghinang saga pakokos pagbobono' maka saga kapanyapan kalesa.",
        13: "Ningā' e'na saga ka'anakanbi d'nda bo' maghinang saga ns'llan pahamut, maka magbab'lla, maka maga'addun saga tinapay.",
        14: "Ningā' e'na saga pagtatanomanbi pai maka tirigu, maka pagtatanomanbi anggul maka jaitun, ingga-ingga ya landu' ahāp, ati pamuwanna ma saga tendogna.",
        15: "Ningā' e'na bahagi' sangpū' min saga tirigu maka buwa' anggulbi bo' pamuwanna ma saga tendogna maka ma saga a'a kawakilanna.",
        16: "Saga ipatanbi d'nda-l'lla ningā' e'na tahinang sosoho'anna. Saga sapi'bi isab maka kura'bi ya katapusan asambu tapagguna he'na.",
        17: "Ningā' isab e'na bahagi' sangpū' min saga kahayopanbi, maka sampay ka'am baranbi binanyaga' e'na.",
        18: "At'kka pa'in waktu inān, parahing du kam ni PANGHŪ' -Yawe ma sabab kabinsana'an ya pinaniya'an ka'am e' sultan bay pene'bi inān, sagō' mbal kam kinale e' PANGHŪ' ma waktu ina'an.”",
        19: "Sagō' halam kinale si Samwel e' saga a'a inān. “Ē! Mbal!” yuk sigām. “Ya kabilahian kami subay aniya' sultan pagmakōkan kami.",
        20: "Bilahi kami pasali' ni saga bangsa kasehe'an bo' aniya' sultan magnakura'an kami maka magmunda'an kami bang ni pagbono'an.”",
        21: "Pagkale pa'in si Samwel ma kamemon bay pinah'lling e' saga a'a inān, parahing iya pabalik ni PANGHŪ' -Yawe.",
        22: "Angallam PANGHŪ' pabīng ma si Samwel, yukna, “Beya'un bang ai kabilahian sigām. Pat'nna'in sigām a'a magsultanan sigām.” Manjari, ah'lling si Samwel ma bangsa Isra'il, “Pehē' na kam,” yukna, “magpole'an pabalik ni kaluma'anbi.”",
    },
    9: {
        1: "Na, aniya' a'a min panubu' Benjamin ga'osan asal maka taga-kaniya'. Ōnna si Kīs ya bay anak si Abiya anak si Seror. Si Seror ya bay anak si Bekorat anak si Apiya, min panubu' si Benjamin du isab.",
        2: "Si Kīs itu taga-anak l'lla pinagōnan si Sa'ul. Ahāp l'lla iya, arorog maka labi alanjang min kamemon pagkahina. Halam aniya' sibu'na ma bangsa Isra'il.",
        3: "Manjari dakayu' llaw, alungay saga kura' ya suku' si Kīs, angkan iya ah'lling ni anakna si Sa'ul, yukna, “Oto', wa'i alungay saga kura'ta. Amowa ka dakayu' sosoho'anta panehe' ma ka'a bo' piha'unbi pehē'.”",
        4: "Sakali, patulak na si Sa'ul maka sosoho'an e' labay min kabūd-būran Epra'im maka min lahat Salisa sagō' halam tabāk e' sigā saga kura' e'. Palanjal na pa'in sigā ni jadjahan Sa'alim sagō' halam du mahē'. Palabay isab sigā min lahat Benjamin, sagō' halam du isab mahē'.",
        5: "Ta'abut pa'in jadjahan Sūp, ah'lling na si Sa'ul ma sosoho'an e', yukna, “Sūng na kita amole', ya aniya' ngga'i ka na saga kura' bay alungay ya pinagsusahan e' si mma', sagō' kita na.”",
        6: "Saguwā' ya sambung sosoho'an inān ma si Sa'ul, “Tuwan,” yukna, “aniya' ma kaluma'an maitu-itu dakayu' a'a sosoho'an Tuhan. Pinagmahaltabatan iya e' saga a'a kamemon maka atuman lullun pangallamna. Ahāp gi' kita pehē' ni iya, kalu-kalu kita katuli'anna lān pamiha'anta saga kura' he'.”",
        7: "Ah'lling si Sa'ul yukna, “Bang kita pehē' ni sosoho'an Tuhan inān, ai tapamuwanta ma iya? Aubus na saga pagkakan bay palutu'ta. Halam na aniya' kabowahanta iya.”",
        8: "Anambung pabalik sosoho'an inān, “Tuwan,” yukna, “aniya' gi' maitu dakayu' pisita. Ya itu pamuwanta ma iya bo' kita katuli'an e'na bang ya ingga subay palabayanta.”",
        9: "(Ma waktu he'-i, ‘a'a talus’ ya pangōn nabi e' bangsa Isra'il. Sai-na bilahi angaru ni Tuhan, ah'lling iya ma sehe'na yukna, “Sūng, pehē' kita ni a'a talus.”)",
        10: "Yuk si Sa'ul ni sehe'na inān, “Na aho'. Sūng na kita.” Jari palanjal na sigā ni kaluma'an ya pa'atagan sosoho'an Tuhan inān.",
        11: "Hinabu sigām patukad ni būd tudju ni kaluma'an e', talanggal e' sigā saga kabudjangan song anauk bohe', jari tinilaw e' sigā yuk-i, “Saga arūng, itiya' bahā' maitu in a'a talus?”",
        12: "“Aho', tuwan,” yuk sambung saga kabudjangan inān. “Wa'i na iya makarahū min ka'am. Pasa'ut kam. Buwattina'an sadja iya makapi'itu ni kaluma'an kami, sabab aniya' pagkulban tinukbalan e' kampung kami mahē' ma tampat.",
        13: "Pagsōdbi ni kaluma'an, tabākbi iya maina'an ma mbal gi' makatukad ni tampat. Mbal magkakanan saga a'a maina'an sat'ggol iya mbal at'kka. Subay ka'amu'anna barakat saga tutukbalan he' bo' magpamangan saga a'a bay tina'abbit. Na, pehē' na kam bo' iya ta'abutbi.”",
        14: "Manjari, hinabu si Sa'ul maka sosoho'an inān pasōd ni kaluma'an e', ilu na si Samwel paluwas song patukad ni tampat.",
        15: "Aniya' asal bay pamukis e' si Yawe ma si Samwel, dang'llaw dahū lagi' min bay kapina'an si Sa'ul. Yuk pamukis e',",
        16: "“Salung ma waktu buwattitu du, papi'iluku ni ka'a dakayu' a'a min panubu' Benjamin. Busugin iya ns'llan paltanda'an in iya bay tapene'ku magnakura' ma saga a'aku bangsa Isra'il. Niliyusan e'na saga a'a suku'ku min komkoman bangsa Pilistin. Ta'nda'ku asal katiksa'an sigām, maka takaleku pangandahing sigām.”",
        17: "Pag'nda' si Samwel ma si Sa'ul, magtūy angallam PANGHŪ' ma iya, yukna, “Ya na itu a'a bay pangahakaku ma ka'a. Iya ya magparinta ma saga a'a suku'ku.”",
        18: "Jari pasekot si Sa'ul ni si Samwel ma atag lawang ya pagsōd-luwasan ma kaluma'an inān. Atilaw iya ma si Samwel, yukna, “Tuwan, da'a busung. Makajari bahā' aku pata'unu bang maingga maitu luma' a'a talus e'?”",
        19: "Anambung si Samwel, yukna, “Aku na ko' ya patilawannu. Pehē' na kam parahū min aku ni tampat sabab magbeya' kam maka aku amangan llaw itu. Palanjalku kam salung ati hakaku ni ka'a kamemon ya ma deyom pamikilnu ilu.",
        20: "Ma pasalan isab saga kura' ya bay alungay saga t'llung'llaw palabay, da'a na kasusahun sabab wa'i na tabāk. Sai lagi' niholatan e' bangsa Isra'il, bang ngga'i ka ka'a maka saga a'a kamemon ya pagtai'anak mma'nu?”",
        21: "Ya sambung si Sa'ul, “Tuwan,” yukna, “aku itu tubu' min panubu' Benjamin ko', ya tubu' ariki' asal ma bangsa Isra'il, maka pangkat kami itu areyo' min kamemon kapanubu'an Benjamin. Angay angkan ka makapah'lling buwattilu?”",
        22: "Manjari binowa patukad e' si Samwel si Sa'ul maka sosoho'an e' ni luma' pagkakanan bo' pinatingkō' min kōkan saga a'a bay tina'abbit he'. Kulang-labi t'llumpū' heka sigām.",
        23: "Jari, ah'lling si Samwel ni magb'b'lla, yukna, “Bowahun pi'itu ya isi sumbali'an bay soho'ku pinasaddī ma ka'a.”",
        24: "Na, binowa pina'an e' magb'b'lla ya pa'a susumbali'an bay pinasaddī bo' pinat'nna' ma munda'an si Sa'ul. Yuk si Samwel ma si Sa'ul, “Ya ilu bay tinau'an ka'a. Amangan ka sabab bay ko' itu asal pinasaddīhan ka'a ma palkala' itu, dahū gi' min waktu bay kapana'abbitku saga a'a kasehe'an itu.” Sakali magbeya' amangan si Sa'ul maka si Samwel ma llaw inān.",
        25: "Paglūd sigām ni kaluma'an min tampat e', aniya' patulihan sinakapan si Sa'ul ma atop karatagan ya pangatop luma' si Samwel.",
        26: "Pagdai' llaw pa'in, hinabu si Sa'ul masi ma diyata' atop e', nilinganan iya e' si Samwel, yukna, “Pabangun ka. Patuntulta ka ni pal'ngnganannu.” Jari asakap pa'in si Sa'ul, magbeya' sigā paluwas min luma'.",
        27: "Makat'kka pa'in sigā ni tōng kaluma'an inān, ah'lling si Samwel ni si Sa'ul yukna, “Soho'un na parahū sosoho'annu ilu.” Makarahū pa'in, ah'lling si Samwel ni si Sa'ul yukna, “Maitu gi' ka bo' ka pata'uku pasal lapal bay min Tuhan.”",
    },
    10: {
        1: "Puwas pa'in he'-i, bay angā' si Samwel poga-poga isihan ns'llan jaitun bo' binusugan e'na kōk si Sa'ul. Siniyum isab iya bo' yuk si Samwel, “Ka'a ya tapene' e' si Yawe magnakura' ma saga a'a palsuku'anna, ya na bangsa Isra'il. (Ka'a ya magmakōkan sigām maka angaliyusan sigām min komkoman saga banta sigām. Aniya' isab paltanda'an pamab'nnal in ka'a tapene' na e' si Yawe magsultanan bangsa palsuku'anna.)",
        2: "Pagla'annu minnitu, makalanggal ka duwa a'a ma tongod bay pangubulan si Rakiya, ina'an ma lahat Selsa ma tobtoban tana' Benjamin. Buwattitu pamissala saga a'a inān ma ka'a, ‘Wa'i na tabāk saga kura' ya bay pihanu. Ma buwattina'an, ngga'i ka na saga kura' ya pinagsusahan e' mma'nu saguwā' ka'a na. Ya panilawna na pa'in, “Buwattingga e'ku amiha anakku?”’”",
        3: "Ah'lling lagi' si Samwel ma si Sa'ul, yukna, “Paglanjalnu min saga a'a he', at'kka ka ni kayu paruwa'ahan ma Tabor. Sinampang ka e' t'llungan l'lla arai' na patukad ni Betel amudji ni Tuhan. Dangan inān amowa t'llu anak kambing, dangan isab amowa t'llu tinapay maka dangan amowa dapangisihan binu-anggul.",
        4: "Sinagina ka pahāp e' sigām, maka binuwanan ka tinapay duwa hekana. Da'a taikutin, taima'un sadja.",
        5: "“Pagubus ilu-i, pehē' ka palanjal ni Gibeya ya pinagbahasa Būd Tuhan, ina'an maina'an magpustu saga sundalu Pilistin. Pagsekotnu ni kaluma'an, magbāk ka maka tumpukan nabi lūd bay min tampat. Magbissala sigām kaligawan pagka kahōpan e' Rū Yawe. Aniya' isab min dahuan sigām saga magbibiyula maka magsusuling maka a'a magtaroro'an tambul-tambul.",
        6: "Ya du ka'a, kahōpan to'ongan ka e' Rū Yawe ati tabowa ka magbeya' maka saga nabi inān magbissala kaligawan. Tahinang ka sali' a'a saddī na.",
        7: "Jari bang paniya' saga paltanda'an itu, hinangun bang ai ya maka'amu ma ka'a, sabab ilu Tuhan taptap pagapi' ma ka'a.",
        8: "“Na, palūd ka parahū min aku ni lahat Gilgal. Paturul du aku ni ka'a bo' anukbal susumbali'an tinunu' maka magduwa'a salamat. Saguwā' ka'a ya subay angagad pitu' llaw sampay aku makapi'ilu, bo' ka katō'anku bang ai subay hinangnu.”",
        9: "Manjari, song pa'in paokat si Sa'ul min si Samwel, pinindahan e' Tuhan pangatayan si Sa'ul e'. Atuman isab ma llaw ina'an kamemon saga paltanda'an bay binissala e' si Samwel.",
        10: "Pagt'kka disi Sa'ul ni Gibeya, bināk sigām e' tumpukan saga nabi he'. Pahōp isab Rū Tuhan ma si Sa'ul ati tabowa iya palamud ma sigām magbissala kaligawan.",
        11: "Ta'nda' pa'in iya he' saga a'a bay magkilahi maka iya, in iya ina'an magbeya' kahōpan e' Rū Tuhan, magtilaw-tilawan sigām dansehe'an yuk-i, “Ai bahā' makani-si Sa'ul ya anak si Kīs inān? Angay, nabi bahā' iya?”",
        12: "Jari anambung dakayu' a'a maglahat maina'an, yukna, “Hē, daka sai mma' saga a'a ilu.” Angkan pinagsambatan maina'an, yuk-i, “Nabi hati' si Sa'ul?”",
        13: "Na, makahondong pa'in si Sa'ul magbissala, patukad iya ni tampat.",
        14: "Sakali tinilaw si Sa'ul maka tendogna e' dakayu' si'itna, yuk-i, “Bay kam maingga?” Ya sambung si Sa'ul, “Bay kami amiha saga kura' si Mma', Bapa'. Saguwā' pagka halam tabāk kami minsan pi'ingga pamiha'an, bay kami pehē' ni si Samwel.”",
        15: "Ah'lling si'itna inān, “Oto'”, yukna, “haka'in aku bang ai bay pamissala ma ka'a e' si Samwel.”",
        16: "Anambung si Sa'ul yukna, “Ya pamissalana ma kami in kura' si Mma' bay kono' tabāk.” Saguwā' halam nihaka e' si Sa'ul ma si'itna pasalan kapagsultanna ma sinosōng.",
        17: "Manjari, pinalinganan e' si Samwel kamemon a'a Isra'il sinoho' pehē' ni lahat Mispa bo' magtimuk ma matahan PANGHŪ' -Yawe.",
        18: "Maina'an pa'in sigām, yukna ma sigām, “Buwattitu in pagkallam si Yawe ya Tuhantam bangsa Isra'il, yukna, ‘Aku ya bay amowa ka'am paluwas min lahat Misil maka min pang'ntanan saga a'a tag-lahat e' maka min saga bangsa kasehe' ya bay amissoko' ka'am.’",
        19: "Sagō' minsan na, tinaikutan e'bi Tuhanbi ya bay angalappas ka'am min kabinsana'an maka kasiksa'an. Angangut kam gom pa'in mikipat'nna' sultan. Na buwattina'an, pabaihu' kam ma matahan PANGHŪ' -Yawe, kamemon kam ma ba'anan kapanubu'anbi magtumpuk-manumpuk.”",
        20: "Tapatipun pa'in he' si Samwel kamemon bangsa Isra'il magsunu'-sunu', bangsa Benjamin ya tapene'.",
        21: "Jari in panubu' si Benjamin magtumpuk-tumpuk binowa e' si Samwel ni matahan Tuhan, ati tumpukan si Matri ya tapene'. Ma kahinapusanna, si Sa'ul anak si Kīs ya tapene'. Sagō' pagpiha sigām, halam iya tabāk.",
        22: "Jari angaru sigām pabīng ni PANGHŪ', yuk-i, “Makapi'itu na bahā' ya a'a tapene' inān?” Anambung PANGHŪ', yukna, “Aho', ina'an iya patapuk ma saga duwa'an.”",
        23: "Sakali, magdai'-dai' sigām pehē' angā' si Sa'ul bo' yampa binowa paluwas ni pagtipunan a'a inān. Na alanjang asal iya min kamemon.",
        24: "Manjari, ah'lling si Samwel ni saga a'a, yukna, “Nda'unbi na a'a ya bay tapene' e' si Yawe. Halam aniya' sibu'na min kitam itu kamemon.” Magtūy magdakayu' kamemon saga a'a inān angolang, yuk-i, “Mura-murahan pinataha' umul sultan ilu!”",
        25: "Pinahati e' si Samwel saga a'a mahadjana' inān pasal hatulan pagsultan. Tasulat e'na kamemon itu ma deyom kitab bo' pinat'nna' ma matahan si Yawe. Pagubus, pinapole' e' si Samwel saga a'a inān pakaniya-pakaniya ni luma' sigām.",
        26: "Ya du si Sa'ul, bay du isab amole' ni luma'na ma Gibeya, magbeya' maka saga a'a esogan magbono' ya kabuwanan baya' e' Tuhan.",
        27: "Sagō' aniya' maina'an saga a'a asabul magpah'lling, yuk-i, “Buwattingga he' a'a itu angalappas kitam min saga bantatam?” Ati pinareyo'-deyo' e' sigām si Sa'ul. Halam aniya' huhulmatan binowa e' sigām pagmahaltabat ma iya. Sagō' halam du ah'lling minsan ai si Sa'ul.",
    },
    11: {
        1: "Na, palabay pa'in saga dambulan, tat'kka da'ira Jabes Giliyad e' si Nahas, ya sultan bangsa Ammon, ati kinumbis e'na bo' mbal makaluwas saga a'a ya maglahat maina'an. Manjari ah'lling sigām ni si Nahas yuk-i, “Magsulut kitam. Magpara'ug kami ma ka'a bang pa'in kami mbal papataynu.”",
        2: "Anambung si Nahas, yukna, “Aho', magsulut kitam bang pa'in talugitku dambila' matatam tampal ni kowan bo' supaya aheya kaiya'anbi ma bangsabi Isra'il.”",
        3: "Angkan ah'lling saga pagmatto'ahan maina'an, yuk sigām, “Patangguhun kami ma deyom pitu' llaw bo' pinasaplag kahālan itu ma katilingkal Isra'il. Bang halam sai-na anabang kami, lilla' na kami magpalongkop ma ka'a.”",
        4: "Manjari, pehē' saga magbobowa lapal ni Gibeya ya kauman palahatan si Sa'ul. Kahaka'an pa'in saga a'a maina'an ma pasalan palkala' he', magtūy sigām maglemong kamemon.",
        5: "Salta' ma waktu ina'an, at'kka si Sa'ul maka saga sapi'na bay min huma. Jari atilaw iya, yukna, “Ai kasusahan saga a'a itu? Angay sigām maglemongan?” Ati nihaka'an iya pasal bay pamissala saga a'a Jabes he'.",
        6: "Pagkale si Sa'ul ma bissala itu, magtūy pahōp ni iya Rū Tuhan, jari akagit atayna, mbal agon kasandalanna.",
        7: "Ningā' e'na duwa sapi' bo' pinagkehet-kehet, ati pinabowa kehetanna ni katilibut Isra'il pamowahan banda'na ma saga a'a kamemon. Yukna, “Buwattitu tumaluwa' ni saga kahayopan sasuku tag-dapuna mbal maguyun ameya' ma si Sa'ul maka si Samwel.” Sakali, kasōran tāw kamemon bangsa Isra'il min kahandak PANGHŪ' -Yawe, angkan sigām magda'atay ameya' ma si Sa'ul.",
        8: "Manjari, pinatipun e' si Sa'ul ma kauman Besek saga kal'llahan, aniya' t'llu hatus ngibu heka sigām min Isra'il maka t'llumpū' ngibu min Yuda.",
        9: "Ah'lling disi Sa'ul ma saga magbobowa lapal bay min Jabes e', yuk-i, “Pata'uhunbi saga a'a Jabes Giliyad, yukbi, ‘Salung, song pa'in ugtu llaw, alappas na kam.’” Kahaka'an pa'in saga a'a Jabes inān, landu' aheya kakōgan sigām,",
        10: "ati yuk sigām ni saga a'a bangsa Ammon, “Pagsalung, lilla' na kami magpalongkop ma ka'am. Tahinangbi na ma kami bang ai kabaya'anbi.”",
        11: "Sagō' ma sangom ina'an du, bay binahagi' t'llu e' si Sa'ul saga sundaluna. Ma halam lagi' pak'llat mata llaw, tasōd e' sigām pustu saga bangsa Ammon bo' binono' e' sigām sampay ta'abut alanga llaw. Sasuku halam tapapatay bay makalahi pakaniya-kaniya.",
        12: "Na pagka buwattē', ah'lling saga a'a Isra'il ma si Samwel, yuk sigām, “Sai sa saga a'a bay mbal bilahi pinagsultanan e' si Sa'ul? Pabowahun sigām pi'itu bo' papatay kami.”",
        13: "Saguwā' amissala si Sa'ul yukna, “Mbal aniya' minsan sai-na pinapatay ma llaw itu. Sabab ya itu llaw kapamuwan da'ugan e' PANGHŪ' -Yawe ma bangsa Isra'il.”",
        14: "Manjari ah'lling si Samwel ma saga a'a Isra'il yukna, “Sūng kitam ni Gilgal ati mahē' kitam amatuman pagsultan si Sa'ul.”",
        15: "Sakali, pehē' ni Gilgal kamemon saga ummat Isra'il bo' pinatuman e' sigām pagsultan si Sa'ul maina'an ma matahan si Yawe. Maina'an isab sigām bay magduwa'a salamat ni si Yawe. Pagubus, aheya paglami-lami disi Sa'ul maka kamemon saga bangsa Isra'il.",
    },
    12: {
        1: "Sakali ah'lling si Samwel ni saga bangsa Isra'il, yukna, “Bay na beya'ku kamemon pangamu'bi ya mikipat'nna' kam sultan.",
        2: "Na buwattina'an, ilu na aniya' sultan magnakura'an ka'am. In aku itu ato'a na, sagō' ilu du saga anakku l'lla ma deyomanbi ganti'ku. Min kabata'ku sampay ni buwattina'an bay aku magnakura'an ka'am.",
        3: "Itiya' aku pa'alop ma ka'am. Bang aniya' panuna'bi ma aku, saksi'inbi ma baihu'an PANGHŪ' -Yawe maka ma baihu'an sultan ya tapene'na itu. Sai bahā' ma ka'am bay katangkawanku sapi'na atawa kura'na? Sai ma ka'am bay ka'akkalanku? Sai ma ka'am bay pissoko'ku? Bay bahā' aku katambahan he' sai-na ma ka'am bo' supaya abengkok hukumanku? Bang bay tahinangku saga kahinangan itu minsan la'a hal dakayu', pabontolku na buwattina'an.”",
        4: "Manjari anambung saga bangsa Isra'il inān, yuk sigām, “Halam kami bay akkalannu atawa pissoko'nu. Halam ka bay anangkawan sai-na ma kami.”",
        5: "Yuk si Samwel ni sigām, “Llaw itu, saksi'tam PANGHŪ' maka sultan ya tapene'na itu, in aku mbal katōnganbi dusa.” “Aho',” yuk sambung sigām, “PANGHŪ' -Yawe ya saksi'tam.”",
        6: "Manjari ah'lling si Samwel, “Si Yawe ya bay amene' si Musa maka si Harun, maka Tuhan ya bay amowa saga ka'mbo'-mbo'anbi paluwas min lahat Misil.",
        7: "Na, da'a kam ala'an m'nnilu sabab bontolanta kam maitu ma baihu'an PANGHŪ' -Yawe pasal saga kahāpan bay tahinang he'na ma ka'am maka saga ka'mbo'anbi.",
        8: "“Ma Misil pa'in disi Yakub, bay sigām parahing ni si Yawe angamu' tabang, ati pinabeya'an sigām si Musa maka si Harun. Sigā ya bay amowa saga ka'mbo'anbi paluwas min Misil tudju pi'itu ni lahat ītu.",
        9: "Saguwā' takalipat e' sigām si Yawe ya Tuhan sigām, angkan sigām bay pinasagaran he'na bo' tara'ug he' si Sisera ya pagnakura'an saga sundalu si Hasor. Bay isab sigām ni'nde'an ni komkoman saga bangsa Pilistin sampay sultan bangsa Mowab ya bay anguntarahan sigām.",
        10: "Pagka buwattē', bay angandahing isab saga a'a Isra'il ni PANGHŪ', yuk-i, ‘Ya Tuhan, aheya landu' dusa kami ma ka'a. Sabab bay ka taikutan kami pasumba ma saga ta'u-ta'u Ba'al maka Astoret. Lappasun kami min saga banta kami itu ati pabalik kami angisbat ka'a sadja.’",
        11: "Sakali bay pinabeya' he' PANGHŪ' si Jerub-Ba'al (ya niōnan isab si Gidiyun) bo' si Barak, ati bo' si Jepta, maka aku ya katapusan. Angkan kam bay kalappasan e'na min pang'ntanan saga kabantahanbi paruruwambila' bo' halam aniya' makarugpak ni lahatbi.",
        12: "“Saguwā',” yuk si Samwel, “pag'nda'bi pa'in song parugpak ni ka'am si Nahas ya sultan bangsa Ammon, subay kam angangut mikipat'nna' sultan magnakura'an ka'am. Buwattē' pangamu'bi ma aku minsan du Tuhan Yawe ya sultanbi.",
        13: "Na”, yuk si Samwel, “itiya' na in sultan bay pene'bi, ya bay amu'bi. Nda'unbi pahāp, aniya' na sultan pinat'nna'an ka'am he' PANGHŪ'.",
        14: "Jari ahāp kahālanbi bang pa'in kam magmatāw ma PANGHŪ', bang kam angisbat iya, bang mbal sagga'bi saga panoho'anna, bang ka'am maka sultan ya magnakura'an ka'am atukid ameya' ma si Yawe ya Tuhanbi.",
        15: "Saguwā', bang kam mbal ameya' ma si Yawe ati sagga'bi gom pa'in saga panoho'anna, taptap kam pinat'kkahan bala', buwat bay pamat'kkana ma saga ka'mbo'anbi.",
        16: "“Na, da'a kam ala'an min pan'nggehanbi ilu bo' kam maka'nda' in hinang makainu-inu ya song nihinang e' PANGHŪ' -Yawe ma matahanbi.",
        17: "Ta'abut na musim pagani tirigu, musim mbal pangulan. Sagō' angamu'-ngamu' aku ni PANGHŪ' bang pa'in pinal'ggon maka pinaulan. Ati minnē' tasayubi bang buwattingga heya kala'atan bay tahinangbi ma matahan PANGHŪ' pagka kam angangut subay mikipat'nna' sultan.”",
        18: "Manjari angamu'-ngamu' si Samwel ati aniya' l'ggon maka ulan pinaniya' e' PANGHŪ' ma llaw ina'an du. Angkan kamemon saga a'a maina'an sinōd tāw ma PANGHŪ' maka ma si Samwel.",
        19: "Ah'lling sigām ni si Samwel, yuk-i, “Amu'-amu'in kami ni si Yawe ya Tuhannu bo' supaya kami mbal pinapatay. Bay ganapan kami saga dusa kami ma sabab kapangangut kami subay mikipat'nna' sultan.”",
        20: "Anambung si Samwel yukna, “Da'a kam tināw. B'nnal aheka paldusahan bay tahinangbi, sagō' minsan na, da'a taikutinbi si Yawe. Wajib iya subay ni'isbat min deyom ataybi.",
        21: "Da'a kam pasiha' min iya bo' maghinang ni saga tuhan-tuhan halam kapūsanna, sabab halam du aniya' kahāpan tahinang sigām ma ka'am. Mbal sigām makalappasan ka'am.",
        22: "Kasulutan si Yawe angahinang ka'am bangsa palsuku'anna, angkan kam mbal siniya-siya he'na supaya mbal tasalla' ōnna babantugun.",
        23: "In aku isab,” yuk si Samwel, “mbal bilahi amakay dusa ni PANGHŪ' -Yawe, angkan aku mbal pahali angamu'-ngamu'an ka'am tabang. Pandu'anta kam isab addat-tabi'at ahāp maka abontol.",
        24: "Amay-amay, pagmatāwinbi si Yawe maka isbatunbi iya min deyom ataybi. Entomunbi to'ongan saga kahāpan makainu-inu ya bay tahinang e'na ma ka'am.",
        25: "Sagō' bang kam pasangdan na pa'in angahinang kala'atan, tantu ka'am maka sultanbi ilu aligis.”",
    },
    13: {
        1: "T'llumpū' tahun umul si Sa'ul waktu iya tahinang sultan ati mpatpū' maka duwantahun ya t'ggol kapagsultanna ma bangsa Isra'il.",
        2: "Na, si Sa'ul itu bay amene' sundalu t'llungibu hekana min bangsa Isra'il. Duwangibu sigām bay ma si Sa'ul ma kauman Mikmas maka ma kabūd-būran Betel, dangibu takapin bay ma si Jonatan ma Gibeya, ya ma paglahat bangsa Benjamin. Maka sasuku halam tapene' e' si Sa'ul bay pinapole' ni kaluma'an sigām.",
        3: "Na, tarugpak e' si Jonatan pustu bangsa Pilistin ma lahat Geba angkan tasayu e' saga Pilistin in bangsa Hibrani angatu na. Manjari amah'lling si Sa'ul tiyup-tiyup ma katilingkal bangsa Isra'il supaya sigām magsakap amono'.",
        4: "Minnē' takale e' kamemon bangsa Isra'il in habal itu, ya yukna, “Tarugpak pustu Pilistin e' si Sa'ul, ati aheya na kab'nsi sigām ma kitam bangsa Isra'il.” Angkan magpanoho'an si Sa'ul ma saga a'a Isra'il, sinō' patipun ma lahat Gilgal.",
        5: "Manjari, magtimukan na saga bangsa Pilistin bo' magsakap amono' bangsa Isra'il. Landu' aheka saga Pilistin e', t'llungibu heka kalesa sigām pagbobono', nnom ngibu saga sundalu magkakalesa. Ya sundalu sigām magtinape' sali' heka solagan gusung ma tampe. Patukad sigām magpustu ma Mikmas, tampal ni sobangan min Bet-Aben.",
        6: "Pag'nda' saga sundalu bangsa Isra'il in sigām kapilahan ma sabab kapaslod pagdugpak bangsa Pilistin, magtūy sigām sikatapukan ma saga songab batu, ma deyom kasagmotan, ma lugal kabatuhan, maka ma saga lowang bay kinalian.",
        7: "Aniya' isab saga Hibrani kasehe'an bay pauntas ni dambila' sapa' Jordan tudju ni lahat Gād maka Giliyad. Saguwā' si Sa'ul bay magpa'bba ma Gilgal ati magpamidpid kamemon saga kasundaluhan bay ameya' ma iya kabowa tāw sigām.",
        8: "Dapitu' ya pangagad si Sa'ul maina'an buwat bay panugun e' si Samwel ma iya. Na, halam pa'in at'kka si Samwel, magkanat-kanat na saga sundalu bay maina'an ma si Sa'ul.",
        9: "Angkan ah'lling si Sa'ul, yukna, “Bowahinbi aku hayop pagtaubat maka tutukbalan pagduwa'aku salamat.” Manjari bay tinukbalan e' si Sa'ul hayop tinunu'.",
        10: "Pagubus, at'kka si Samwel ati paluwas si Sa'ul min kaluma'an anampang iya maka anagina.",
        11: "Yuk si Samwel ma iya, “Ai bay hinangnu itu?” Anambung si Sa'ul, yukna, “Ta'nda'ku magkaukanat saga a'aku maka halam ka makat'kka ma waktu bay panugunnu. Ina'an isab saga sundalu Pilistin magtimuk ma Mikmas.",
        12: "Tapikilku in bangsa Pilistin arai' parugpak pi'itu ni Gilgal ma halam aku minsan makapangaru ni PANGHŪ' -Yawe. Angkan aku bay magniyat magtukbal saga tutukbalan tinunu' itu.”",
        13: "Ya sambung si Samwel ma si Sa'ul, yukna, “Dupang pahāp ka magkahinangan buwattilu! Halam bay bogbogannu panoho'an PANGHŪ' ma ka'a. Bang ka bay magkahagad, tuman ka'a maka saga panubu'nu pinapagsultan ma bangsa Isra'il ni kasaumulan.",
        14: "Saguwā', pagka ka halam bay ameya' ma panoho'an PANGHŪ' ma ka'a, mbal anatas kapagsultannu. Aniya' tapihana a'a makasulut pangatayanna, ati tapat'nna' na e'na magmakōk ma saga ummat ya palsuku'anna.”",
        15: "Pabuhat magtūy si Samwel bo' palanjal min Gilgal ni Gibeya ya ma paglahat Benjamin. Malaingkan si Sa'ul bay angitung saga sundalu ya beya' ma iya, nnom hatus heka sigām.",
        16: "Na, ina'an disi Sa'ul maka anakna si Jonatan pahanti' ma Gibeya, beya' isab saga sundalu sigām, samantala' wa'i masi ma Mikmas magpustu saga sundalu Pilistin.",
        17: "Magbahagi' t'llu saga sundalu Pilistin itu bo' angandugpak bangsa Isra'il. Datumpuk inān bay patudju ni kauman Opra ya ma jadjahan lahat Suwal,",
        18: "datumpuk bay pehē' tudju ni Bet-Horon, jari in tumpuk kat'lluna bay pehē' ni kareyahan min diyata'an karatagan Seboyim, ya paharap ni paslangan.",
        19: "Ma waktu ina'an-i, halam aniya' minsan dakayu' magsasasal ma katilingkal Isra'il sabab mbal nirūlan e' bangsa Pilistin. Tināw asal sigām in saga bangsa Isra'il angahinang pakokos di-sigām.",
        20: "Angkan saga bangsa Isra'il subay pehē' ni saga bangsa Pilistin magpa'asa' kapanyapan sigām taga-solab, buwat saga paga'araru, saga sangkul, saga kapa maka sanggot.",
        21: "Duwa sīn tibu'uk ya halga' pagpa'asa' solab paga'araru maka sangkul, dakayu' sīn tibu'uk ya halga' isab pagpa'asa' tugsuk a'aslag maka kapa maka tōng tungkud.",
        22: "Jari halam aniya' minsan dakayu' min sundalu Isra'il magtakos kalis atawa budjak ma llaw pagbono' inān, luwal si Sa'ul maka anakna si Jonatan.",
        23: "Na, aniya' tumpukan sundalu Pilistin bay sinō' anunggu'an lān ya palabayan ma kapampangan Mikmas.",
    },
    14: {
        1: "Dakayu' llaw ah'lling si Jonatan anak si Sa'ul ni onde' baha'u ya magbobowa pakokosna, yukna, “Sūng kita pehē' ni pustu saga sundalu bangsa Pilistin ya ma dambila' inān.” Sagō' halam pinata'u mma'na.",
        2: "Pasalta', ina'an si Sa'ul maka nnom hatus sundaluna magpustu ma deyo'an kayu dalima' ma Meglon, ya ma tobtoban lahat Gibeya.",
        3: "Beya' isab maina'an si imam Ahidja ya tag-bowahan epod. Si Ahidja itu anak si Ahitub ya danakan si Ikabod. Mma' sigā si Pinehas anak si Eli ya bay maghinang ni si Yawe ma Silo. Sagō' halam sai-na makasayuhan kalikut si Jonatan e'.",
        4: "Na, aniya' pampang min karuwambila' lān ya palabayan si Jonatan tudju ni pagpustuhan saga sundalu Pilistin. Boses ya pangōn ma pampang dambila', Sene ya pangōn ma dambila'.",
        5: "Pa'anggop ni Mikmas ya pampang tampal ni uttala', pa'anggop ni Geba ya pampang tampal ni tunggara'.",
        6: "Sakali, ah'lling si Jonatan ni magbobowa pakokosna inān yukna, “Sūng kita pehē' ni pustu bangsa kapil inān. Kalu mura-murahan kita tinabangan e' PANGHŪ' -Yawe. Tuman halam aniya' makapaggat bang iya ya amuwan da'ugan, ai naka aheka kitam atawa akulang.”",
        7: "Anambung magbobowa pakokos inān, yukna, “Pē'un tuwan, palanjalun bang ai maksudnu. Itiya' du aku ameya' ma ka'a minsan ai tumaluwa'.”",
        8: "Ya pah'lling si Jonatan, “Sūng! Pehē' kita magpa'nda' ma sigām.",
        9: "Bang sigām ah'lling ni kita, yuk-i, ‘Angagad gi' kam mailu ati pi'ilu kami,’ na maitu sadja kita, mbal kita palanjal.",
        10: "Sagō' bang yuk sigām, ‘Patukad kam pi'itu’, na patukad kita sabab ya ina'an paltanda'an in da'ugan pamuwan ma kita e' si Yawe.”",
        11: "Sakali, magpa'nda' pa'in sigā karuwangan ni pustu saga Pilistin he', magtūy sigām ah'lling, yuk-i, “Allā! Nda'unbi ba saga Hibrani ilu, ilu na sikaluwasan min saga lowang bay patapukan sigām!”",
        12: "Jari angolang saga a'a ma pustu inān ni si Jonatan maka ni magbobowa pakokosna he', “Pasōng kam pi'itu bo' kam l'ggahan!” Angkan ah'lling si Jonatan ni sehe'na inān yukna, “Paturul ka ma aku. Tuman pamuwan in da'ugan e' si Yawe ma bangsa Isra'il.”",
        13: "Parāg si Jonatan min pampang ati paturul min buli'anna magbobowa pakokosna inān. Tapapatay he' si Jonatan saga sundalu Pilistin, maka ina'an isab sehe'na amapatay min buli'anna.",
        14: "Jari duwampū' heka Pilistin bay tapapatay ma kapangandugpak sigā kamint'dda inān. Akiput asal lugal bay pagbono'an e'.",
        15: "Manjari, ahiluhala' kamemon saga sundalu Pilistin kabowa tāw sigām. Ahiluhala' sigām ma deyom pustu, ahiluhala' sigām ma deya, ahiluhala' isab saga tumpukan magdurugpak. Magbeya' isab ajogjog tana' sabab in tāw inān bay pinaniya' e' Tuhan.",
        16: "Aniya' saga sundalu si Sa'ul ma Gibeya-Benjamin bay amantawan lahat ma sakalibut sigām, ati ta'nda' e' sigām saga sundalu Pilistin magkaukanat pehē'-pi'itu.",
        17: "Magtūy ah'lling si Sa'ul ni saga a'a ya sehe'na, yukna, “Patipununbi saga sundalutam kamemon bo' nda'unbi bang sai halam maitu.” Pag'nda' sigām, luwal si Jonatan maka magbobowa pakokosna ya halam maina'an.",
        18: "Ati ah'lling si Sa'ul ni imam Ahidja, yukna, “Bowahun pi'itu Ba'ul Paljanji'an Tuhan ilu.” (Ma waktu itu-i in Ba'ul Tuhan ina'an asal ma bangsa Isra'il.)",
        19: "Na, hinabu si Sa'ul amissala ni imam e', paruhun na pa'in kalengogan ma pustu saga bangsa Pilistin. Angkan yuk si Sa'ul ma imam e', “Pasagarin na.”",
        20: "Sakali, magsakaum si Sa'ul maka kamemon saga sundaluna bo' pakuyas ni pagbono'an. Anā, landu' aheya in kalengogan ma saga sundalu bangsa Pilistin sabab ina'an sigām magpatay dansehe'an.",
        21: "Aniya' saga Hibrani bay asal palamud ma bangsa Pilistin bo' dambeya'an maka sigām ma deyom pustu, sagō' papinda na sigām ni saga sundalu Isra'il ya bay ma disi Sa'ul maka si Jonatan.",
        22: "Sampay saga bangsa Isra'il ya bay sikatapukan ma kabūd-būran lahat Epra'im ameya' na isab angapas pagkale sigām in saga sundalu Pilistin wa'i na maglahian.",
        23: "Jari talappas bangsa Isra'il e' si PANGHŪ' -Yawe ma llaw ina'an du, ati palanjal na pa'in pagbono' inān sampay ni dambila' Bet-Aben.",
        24: "Na, ma llaw ina'an-i, landu' abinsana' saga sundalu bangsa Isra'il sabab bay makasubali si Sa'ul, yukna, “Bang pa'in pinagmulka'an sai-sai anginam takakan ma mbal gi' s'ddop llaw. Subay aku makabalosan saga bantaku dahū!” Angkan halam sai-na anawakkal amangan sampay ni kakohapan.",
        25: "Sakali itu, makat'kka pa'in kamemon sundalu inān ni dakayu' gulangan, aniya' gula' buwani maina'an ma kuwit tana'.",
        26: "Pagsōd sigām pehē', ta'nda' e' sigām gula' buwani inān magdayas-dayas, saguwā' halam aniya' minsan dakayu' min sigām makatawakkal an'nno'an tōng tanganna pina'an sabab kabowa tāw sigām ma bay panubali sultan Sa'ul e'.",
        27: "Saguwā', pagka halam bay takale e' si Jonatan panubali mma'na, bay pina'abut tōng tungkudna ni gula' inān bo' kininaman e'na. Pagkakanna pa'in, pasawa magtūy pamaihu'anna pagka ahāp na palasahanna.",
        28: "Nihaka'an iya magtūy e' dakayu' sundalu bay maina'an. “Tuwan,” yukna, “kami saga sundalu bay pinagsapahan e' mma'nu, sinō' mbal amangan ai-ai llaw itu. Pinagmulka'an kono' kami. Angkan ko' kami itu pinunung na e' lingantu.”",
        29: "Anambung si Jonatan, yukna, “Allā, aheya kasasawan pamat'kka e' mma'ku ma kitam kamemon! Nda'unbi ba kahāp palasahanku pagkakanku gula' buwani itu minsan la'a hal dangkuri'.”",
        30: "Yukna lagi', “Luba'na na bahā' bang kam bay makakakan ai-ai ya tatabanbi min saga bantatam. Marai' aheka lagi' bangsa Pilistin bay tapapatay.”",
        31: "Ma llaw ina'an, tapapatay e' bangsa Isra'il saga bangsa Pilistin tinagna'an min Mikmas sampay ni jadjahan Ayjalon. Pagubus, landu' apaya saga a'a Isra'il sabab lingantu.",
        32: "Angkan pinagagawan e' sigām saga bili-bili maka hayop bay tataban e' sigām bo' sinumbali' saru'un-du'un. Agsai pinagkakan e' sigām minsan masi laha'an, kabowa lingantu sigām.",
        33: "Ati aniya' makasumbung ma si Sa'ul, yukna, “Tuwan, makapakay dusa ni PANGHŪ' saga a'anu sabab wa'i sigām amangan sumbali'an masi taga-laha'.” Yuk si Sa'ul, “Saga panipu! Pagulungunbi saru'un-du'un pi'itu batu aheya.”",
        34: "Magpanoho'an gi' iya, yukna, “Pehē'unbi saga a'a he' bo' soho'unbi amowa pi'itu saga sapi' maka bili-bili sigām dangan maka dangan. Soho'unbi sigām anumbali' maka amangan maitu. Subay sigām mbal amakay dusa ni PANGHŪ' pagka sigām amangan sumbali'an masi taga-laha'.” Angkan ma sangom ina'an du, amowa sigām pakaniya-pakaniya saga sapi' maka bili-bili sigām bo' sinumbali' maina'an.",
        35: "Anambak isab batu si Sa'ul pagkulbanan ni PANGHŪ' -Yawe. Yampa aniya' pagkulbanan tahinang e'na.",
        36: "Manjari ah'lling si Sa'ul, “Sangom itu,” yukna, “parugpak kitam ni saga bangsa Pilistin. Gora'tam ai-ai sigām kamemon ati papatayta sigām kamemon sampay ni kasubuhan.” Anambung saga sundalu inān, “Hinangun tuwan bang ai taluwa' ma pikilannu.” Sagō' ya panambung imam, “Subay kitam angaru dahū ni Tuhan.”",
        37: "Angkan angaru si Sa'ul ni Tuhan yukna, “Ya Tuhan, parugpak na bahā' kami ni bangsa Pilistin? Pamuwannu bahā' in da'ugan ma bangsa Isra'il?” Saguwā' halam aniya' sambung Tuhan ma llaw ina'an.",
        38: "Pagka buwattē', ah'lling si Sa'ul ni saga nakura' ma tumpukan sundalu. “Pasōng kam pi'itu,” yukna, “bo' tata'u bang ai dusa bay tahinangtam ma llaw itu.",
        39: "Sapahanku ma ōn si Yawe ya Manglalappas ma bangsa Isra'il, sai-sai katōngan dusa itu minsan anakku si Jonatan, subay pinapatay.” Sagō' halam makapamūng saga a'a inān minsan dangan.",
        40: "Ah'lling lagi' si Sa'ul ni kamemon saga a'a Isra'il, yukna, “Mailu kam ma dambila', ati aku maka anakku si Jonatan maitu isab ma dambila' itu.” Jari anambung saga a'a maina'an, “Ka'a ya magkabaya'an, tuwan.”",
        41: "Sakali angamu'-ngamu' si Sa'ul ni si Yawe ya pagtuhanan bangsa Isra'il, yuk-i. “Ya PANGHŪ', pata'uhun ni kami bang sai bay makarusa.” Magko'ot-ko'ot pa'in, tasayu ngga'i ka saga sundalu ya bay tag-dusahan, sabab si Jonatan maka si Sa'ul ya tako'ot.",
        42: "Magtūy ah'lling si Sa'ul, yukna, “Pagko'ot-ko'otinbi bang sai ma kami maka si Jonatan ya bay makarusa.” Jari si Jonatan ya tako'ot.",
        43: "Na, ah'lling si Sa'ul ni si Jonatan, yukna, “Haka'in aku bang ai bay tahinangnu?” Anambung si Jonatan, “Bay t'nno'anku tōng tungkudku ni gula' buwani bo' bay kinamanku dangkuri'. Na, patut bahā' aku subay pinapatay?”",
        44: "“Aho' Jonatan” yuk si Sa'ul. “Bang pa'in aku pinat'kkahan mulka' e' Tuhan bang ka mbal papatayku.”",
        45: "Saguwā' yuk saga sundalu ni si Sa'ul, “Si Jonatan ya bay angaliyusan bangsatam Isra'il min kamulahan! Angay iya subay pinapatay? Mbal patut! Anapa kami ma ōn si Yawe ya Tuhan kakkal, in si Jonatan subay mbal ni'inay, sabab Tuhan ya bay anabangan iya ma bay tahinangna llaw itu.” Angkan kaliyusan si Jonatan e' saga a'a inān ati halam bay pinapatay.",
        46: "Manjari itu, pahondong na si Sa'ul angapas saga bangsa Pilistin angkan sigām magsuhutan na ni kalahatan sigām.",
        47: "Min waktu tagna' kapagsultan si Sa'ul ma Isra'il, niatuhan e'na saga banta sigām min paruruwambila'. Ya na bangsa Mowab, bangsa Ammon, bangsa Edom, saga sultan bangsa Soba, maka bangsa Pilistin. Minsan pi'ingga parugpakan si Sa'ul maka saga sundaluna, anganda'ug sadja sigām.",
        48: "Aesog e'na amono' ati tara'ug bangsa Amalek. Talappas e' si Sa'ul bangsa Isra'il min komkoman saga a'a bay makalangpasan ai-ai sigām.",
        49: "Ya itu saga anak si Sa'ul l'lla: si Jonatan bo' si Isboset maka si Malki-Suwa. Anakna d'nda kasiyakahan ya na si Merab, maka si Mikal ya kasiyalihan.",
        50: "Ōn h'nda si Sa'ul ya na si Ahinowam anak si Ahima'as. Ōn a'a ya nakura' katapusan alanga ma saga sundaluna ya na si Abner. Magkaki si Sa'ul maka si Abner itu pagka",
        51: "magdanakan mma' sigām. Si Kīs ya mma' si Sa'ul, maka si Nēr ya mma' si Abner. Si Abiyel ya bay mma' sigā.",
        52: "Magbono' na pa'in bangsa Pilistin maka bangsa Isra'il sampay ni waktu kamatay si Sa'ul, halam aniya' halianna. Bang aniya' a'a akosog atawa aesog ta'nda' e' si Sa'ul ma bangsa Isra'il, ningā' magtūy e'na magsundalu.",
    },
    15: {
        1: "Ah'lling si Samwel ma si Sa'ul yukna, “Aku ya bay pinabeya' e' PANGHŪ' amusugan ka'a ns'llan bo' ka pinat'nna' magsultan ma bangsa Isra'il, ya bangsa suku'na. Na, kalehun pahāp kallam PANGHŪ' Sangat Kawasa,",
        2: "ya yuk-i, ‘Tungbasanku bangsa Amalek ma sabab bay kapangahapa' sigām bangsa Isra'il waktu kaluwas sigām min lahat Misil.",
        3: "Na, buwattina'an, pehē' na ka, dugpakun bangsa inān. Laglagun sigām kamemon maka paka'atun ai-ai palsuku'an sigām. Da'a kapinin minsan dangan. Papatayun sigām kamemon d'nda-l'lla sampay ni onde'-onde' maka anak-duru'an. Papatayun isab saga kahayopan sigām, ai naka sapi', ai naka bili-bili, ai naka unta' sampay kura'. Papatayun kamemon.’”",
        4: "Sakali pinalinganan e' si Sa'ul saga a'ana magbobono', sinō' patipun ma da'ira Tela'im. Jari duwahatus ngibu sundalu magtinape' ya bay patipun pina'an, maka sangpū' ngibu isab min bangsa Yuda.",
        5: "Na, pehē' disi Sa'ul tudju ni da'ira bangsa Amalek ati patapuk ma kal'bbakan bo' anipihan sigām.",
        6: "Jari magbanda' si Sa'ul ma bangsa Kēn, yukna, “Ala'an kam min deyoman saga bangsa Amalek ilu bo' kam mbal talapay pinapatay, sabab aheya kahāpan bay hinangbi ma bangsa Isra'il waktu kaluwas sigām min lahat Misil.” Angkan paokat minna'an saga bangsa Kēn.",
        7: "Sakali itu, parugpak disi Sa'ul ni bangsa Amalek, tinagna'an min Habila sampay ta'abut Sūr, ya lahat ma bihing Misil tampal ni sobangan.",
        8: "Tapapatay e' sigām kamemon saga sundalu Amalek inān sagō' si Agag ya sultan sigām hal bay sinaggaw.",
        9: "In si Agag maka saga hayop ya katapusan ahāp, maka saga anak hayop ya asambu, halam bay ni'inay e' disi Sa'ul maka saga a'ana. Ahuskaw sigām amaka'at ai-ai ahāp angkan aniya' lagi' allum maka takapin. Sagō' sasuku halam kapūsanna bay nilaglag katūyan e' sigām.",
        10: "Manjari angallam PANGHŪ' ma si Samwel, yukna,",
        11: "“Magsusun aku amene' si Sa'ul magsultan sabab kataikutan aku e'na, maka halam bay beya'na saga panoho'anku.” Pagkale itu-i he' si Samwel, landu' iya asusa angkan iya angamu'-ngamu' ni si Yawe animpus dasangom inān.",
        12: "Pag'llaw dakayu' hinabu subu-subu lagi', pabungkal na si Samwel arak amowa mag'nda' maka si Sa'ul, saguwā' aniya' angahaka'an iya, yukna, “Si Sa'ul bay ma kauman Karmel insini' amat'nggehan ta'u-ta'u pamaheyana ma kabantuganna. Wa'i na iya palūd ni Gilgal.”",
        13: "Makat'kka pa'in si Samwel ni Gilgal, ah'lling si Sa'ul ni iya, yuk-i, “Mura-murahan bang pa'in ka binarakatan e' si Yawe! Bay na beya'ku saga panoho'anna.”",
        14: "Anambung magtūy si Samwel, yukna, “Na bang buwattē', ai bahā' lling bili-bili maka sapi' ya takaleku itu?”",
        15: "Anambung si Sa'ul, yukna, “Ya ilu bay ta'agaw e' saga sundaluku min bangsa Amalek. Bay kinapinan e' sigām saga bili-bili maka saga sapi' ya katapusan ahāp supaya aniya' panukbal ni si Yawe ya Tuhannu. Saddī m'nnilu bay papatay kami kamemon.”",
        16: "“Ē! Sarang na!” yuk si Samwel. “Kalehun gi' bay pangallam PANGHŪ' ma aku dibuhi'.” “Na, haka'in aku,” yuk si Sa'ul.",
        17: "Ah'lling si Samwel yukna, “Areyo' kabantugannu arai' bang ma bistahannu, malaingkan in ka'a pagmakōkan ma saga kapanubu'an bangsa Isra'il. Tapene' ka e' si Yawe magsultan ma sigām.",
        18: "Ya panoho'anna ma ka'a, yuk-i, ‘Laglagun kamemon saga a'a Amalek, ya bangsa patila'atun inān. Bono'un sigām sampay sigām amatay kamemon.’”",
        19: "Atilaw lagi' si Samwel yukna, “Angay halam beya'nu panoho'an PANGHŪ' -Yawe he'? Angay magtūy agawnu saga tatabanan ya ka makahinang kala'atan makasāk atay PANGHŪ'?”",
        20: "Anambung si Sa'ul, “Oy! Bay du aku magkahagad ma kabaya'an PANGHŪ'. Bay hinangku panoho'anna ma aku. Bay papatayku kamemon bangsa Amalek maka bay saggawku si Agag ya sultan sigām.",
        21: "Suku' ma Tuhan asal saga bili-bili maka sapi' ya tataban inān, malaingkan kinapinan e' saga sundaluku saga hayop katapusan ahāp. Itiya' na ma Gilgal bo' aniya' susumbali'an tinukbalan ni si Yawe ya Tuhannu.”",
        22: "Yuk sambung si Samwel ma si Sa'ul, “Kasulutan bahā' si Yawe ma saga susumbali'an tinunu' maka tutukbalan pagtaubat labi lagi' min pameya'ta ma saga panoho'anna? Ahāp lagi' magkahagad ma panoho'an Tuhan min amowa tutukbalan. Ahāp lagi' ameya' ma kabaya'anna min anukbal lanab min saga bili-bili l'lla.",
        23: "Pinasali' ni dusa magpuputika' ya dusa a'a anagga' ma PANGHŪ', maka bang a'a magmalangkahi, pasali' la'atna ni pagsumba ni saga ta'u-ta'u. Ma pasalan kataikutnu min panoho'an PANGHŪ' -Yawe, tinaikutan isab he'na kapagsultannu.”",
        24: "Manjari ah'lling si Sa'ul ma si Samwel, yukna, “B'nnal, bay aku makalanggal panoho'an PANGHŪ' maka panoho'annu. Tu'ud aku tināw ma saga a'aku, angkan bay beya'ku pamogos sigām.",
        25: "Ndū' tuwan,” yukna, “amu'ku junjung ni ka'a, ampunun aku. Sehe'in aku bo' kita pabalik pehē' anumba ni PANGHŪ' -Yawe.”",
        26: "Saguwā' anambung si Samwel, yukna, “Hē! Mbal aku ameya' ma ka'a sabab bay taikutannu panoho'an PANGHŪ', maka ilu na ka tinaikutan he'na. Mbal na ka makapagsultan ma bangsa Isra'il!”",
        27: "Jari itu, song pa'in ala'an si Samwel, niragtu' tōng jubana e' si Sa'ul ati magtūy agese'.",
        28: "Yuk si Samwel ma iya, “Nda'un na, in kapagsultannu sapantun juba itu. Taragtu' e' PANGHŪ' min ka'a llaw itu, ati pamuwanna ma dakayu' pagkahinu, a'a labi ahāp min ka'a.",
        29: "In Tuhan Kasahaya'an bangsa Isra'il, mbal magputing atawa amindahan pikilanna sabab ngga'i ka iya manusiya' magpinda-pinda pikilan.”",
        30: "Anganjunjung pabalik si Sa'ul. “Aho', bay aku makarusa,” yukna, “sagō' amu'ku ma ka'a, pagaddatin aku ma baihu'an saga pagmatto'ahan ma bangsaku Isra'il sampay ma bangsa Isra'il kamemon. Sehe'in aku bo' kita pabalik amudji ni si Yawe ya pagtuhanannu.”",
        31: "Sakali pabunyug na si Samwel ma si Sa'ul ati makapudji iya ni PANGHŪ'.",
        32: "Pagubus, ah'lling si Samwel, yukna, “Bowahunbi pi'itu si Agag ya sultan bangsa Amalek.” Na, pasekot si Agag pina'an ni si Samwel ma halam aniya' kahanggawanna, sabab ma pikilanna, “Tantu palabay kapiligduhan, mbal na ko' aku itu pinapatay.”",
        33: "Saguwā' yuk si Samwel, “Ma pasalan aheka ina' kalungayan anak sabab bay papataynu, damikiyanna amatay du ka isab ati kalungayan anak ina'nu.” Jari pinaglagut-lagut si Agag e' si Samwel ma matahan si Yawe, maina'an ma Gilgal.",
        34: "Puwas pa'in e'-i, amole' na sigā karuwangan, si Samwel ni Rama bo' si Sa'ul ni Gibeya.",
        35: "Min waktu inān sampay ni llaw kamatay si Samwel halam na iya amowa mag'nda' ma si Sa'ul. Sagō' magdukka na pa'in si Samwel ma kahālan si Sa'ul. Magsusun isab si Yawe sabab kapamene'na ma si Sa'ul magsultan ma bangsa Isra'il.",
    },
    16: {
        1: "Manjari dakayu' llaw, magkallam si Yawe ma si Samwel, yukna, “Sarang na pagdukkanu ma si Sa'ul pagka kataikutan e'ku pagsultanna ma bangsa Isra'il. Isihun ns'llan jaitun ni tanduk ya bowanu ilu bo' ka pehē' ni Betlehem ni a'a pinagōnan si Jesse. Sabab aniya' anakna l'lla tapene'ku magsultan.”",
        2: "Sagō' atilaw si Samwel, yukna, “Buwattingga kapehē'ku? Bang tasayu e' si Sa'ul, tantu aku pinapatay e'na.” Ya sambung PANGHŪ' -Yawe, “Amowa ka dakayu' anak sapi' d'nda bo' haka'in saga a'a mahē' in ka'a pehē' amowa tutukbalan pagkulbannu ni Tuhan.",
        3: "Ta'abbitun si Jesse ni pagkulbanan ati pata'uku ni ka'a bang ai subay hinangnu. Busugin ns'llan ya a'a tō'ku ma ka'a.”",
        4: "Bineya' e' si Samwel panoho'an PANGHŪ' ati pehē' iya ni Betlehem. Pagt'kkana, bināk iya e' saga pagmatto'ahan maina'an maka he' sigām amidpid. Atilaw sigām ma iya, yuk-i, “Tuwan, kahāpan bahā' ya pagpi'itunu ilu?”",
        5: "“Aho',” yuk sambung si Samwel. “Pi'itu aku anukbal tutukbalan kulban ni si Yawe. Sussihunbi pamarananbi bo' kam pi'itu ameya' ma aku.” Sinussi isab e' si Samwel si Jesse maka saga anakna l'lla bo' ta'abbitna sigām ni pagkulban.",
        6: "Pagt'kka sigām, ta'nda' e' si Samwel si Eliyab ya anak si Jesse kasiyakahan, angkan pangannalna, “Tantu ya na itu bay tapene' e' PANGHŪ' -Yawe.”",
        7: "Saguwā' angallam PANGHŪ' ma si Samwel, yukna, “Da'a nda'un luwana atawa lanjangna sabab ngga'i ka iya bay tapene'ku. Magbidda' asal e'ku ang'nda' min pang'nda' manusiya'. Sabab in manusiya' mag'nda' sadja ma pangluwahan saguwā' aku si Yawe ang'nda' ma pangatayan.”",
        8: "Sakali pinalinganan e' si Jesse si Abinadab ya anakna pasunu' bo' binowa palabay min matahan si Samwel. Saguwā' yuk si Samwel, “Ngga'i ka iya bay tapene' e' PANGHŪ'.”",
        9: "Jari si Samma, ya anak si Jesse kat'llu na, pinalabay min si Samwel, sagō' yuk si Samwel, “Ngga'i ka du isab iya bay tapene' e' PANGHŪ'.”",
        10: "Tapalabay e' si Jesse kapitu' anakna l'lla min matahan si Samwel sagō' buwattē' na pa'in pah'lling si Samwel, yukna, “Halam sai-na ma sigām bay tapene' e' PANGHŪ'.”",
        11: "Angkan atilaw si Samwel ma si Jesse yukna, “Halam na aniya' saddī anaknu min sigām itu?” “Aniya' gi' kasiyalihan,” yuk sambung si Jesse, “saguwā' wa'i magipat saga bili-bili.” Ah'lling si Samwel, “Soho'un iya pinabowa pi'itu. Mbal kitam makatagna' sat'ggolna mbal at'kka.”",
        12: "Angkan pina'ā' e' si Jesse anakna kasiyalihan. Onde' arorog iya, amanis, maka ahāp isab ninda' matana. Jari yuk PANGHŪ' ma si Samwel, “Ya na ilu tapene'ku. Pē'un na, busugin iya ns'llan tanda' kapagsultanna.”",
        13: "Manjari ningā' e' si Samwel tanduk isihan ns'llan e' bo' busuganna si Da'ud ma matahan saga danakanna. Tinagna'an min llaw inān pataptap Rū si Yawe ma si Da'ud. Sakali amole' na pabalik si Samwel ni Rama.",
        14: "Sakali ala'an na Rū si Yawe min si Sa'ul ati aniya' saitan pinapehē' e' si Yawe aminsana' iya.",
        15: "Ah'lling saga tendogna, yuk-i, “Tuwan sultan, tantu ka bininsana' e' saitan bay min Tuhan.",
        16: "Angkan tuwan, soho'un kami saga sosoho'annu itu amiha dakayu' a'a ata'u magbiyula. Ati sakahaba' ka tin'kka e' saitan, magbiyula iya supaya pahāp palasahannu.”",
        17: "Angkan magpanoho'an si Sa'ul ma saga tendogna inān, yukna, “Na aho', piha'inbi aku a'a apanday magbiyula bo' bowahunbi pi'itu.”",
        18: "Jari ah'lling dakayu' sosoho'an inān yukna, “Tuwan, aniya' kata'uwanku apanday magbiyula. Anak iya si Jesse a'a min Betlehem. Aesog iya maka bobono'un. Ahantap isab himumūnganna maka arorog pamarananna. Ina'an isab PANGHŪ' -Yawe pat'ttog ma iya.”",
        19: "Manjari amabeya' lapal si Sa'ul ni si Jesse, yuk-i, “Papi'ituhun anaknu si Da'ud ya magi'ipat bili-bili ilu.”",
        20: "Pagkale si Jesse, magtūy iya anganduwa' ni kura' ba'anan tinapay maka dapangisihan binu-anggul maka dakayu' anak kambing. Aubus pa'in niruwa' e'na, pinatulak e'na si Da'ud pehē' ni si Sa'ul.",
        21: "Sakali anagna' na maghinang si Da'ud ma deyoman sultan Sa'ul. Kasulutan sidda si Sa'ul ma iya angkan iya nihinang dakayu' magbobowa pakokosna.",
        22: "Amabeya' lapal isab si Sa'ul pehē' ni si Jesse, yuk-i, “Pamaituhun na si Da'ud ma deyomanku sabab kasulutan aku ma iya.”",
        23: "Na, sakahaba' si Sa'ul bininsana' e' saitan bay min Tuhan, magbiyula magtūy si Da'ud. Bay pa'in iya makabiyula, pahāp palasahan si Sa'ul maka ala'an isab saitan min iya.",
    },
    17: {
        1: "Manjari magtipun saga sundalu bangsa Pilistin bo' pasakap magbono'. Magpūn sigām ma kauman Soko ya ma lahat Yuda, ati magpustu sigām ma Epes-Dammim ma llot Soko maka Aseka.",
        2: "Ina'an isab magtimuk disi Sa'ul maka saga sundalu Isra'il bo' magpustu ma L'bbak Ela. Patanam isab sigām bo' angatu ma bangsa Pilistin.",
        3: "In bangsa Pilistin ina'an ma dakayu' būd, maka ina'an saga bangsa Isra'il ma būd saddī. Aniya' l'bbak-būd isab ma llot sigām.",
        4: "Sakali aniya' paluwas min pustu bangsa Pilistin dakayu' a'a bobono'un maka babantugun. Ōnna si Golayat, a'a min da'ira Gāt. Kulang-labi dand'ppa maka tonga' lanjangna.",
        5: "Magsinaruk tumbaga si Golayat itu, maka magbinadju' badju' sisikan tumbaga, buhatna saga limampū' ka lima kilu.",
        6: "Tinampanan tape'na maka tumbaga, maka aniya' budjak tumbaga pasalay ma bukutna.",
        7: "Aniya' budjakna dakayu' da'aslag batangna maka batang pagt'nnunan kakana'. Ya solabna dī basi', ya buhatna saga pitu' kilu. Aniya' magbobowa tamingna parahū min iya.",
        8: "Na, an'ngge si Golayat itu ma anggopan saga sundalu bangsa Isra'il, maka e'na angamahit, yukna, “Angay kam subay paluwas magbono'? Aku itu dakayu' ko' sundalu Pilistin, bo' ka'am ilu banyaga' sadja si Sa'ul! Pene'unbi,” yukna, “dakayu' a'abi bo' soho'unbi pi'itu angatuhan aku.",
        9: "Bang saupama aku tara'ugna, magpabanyaga' kami ma ka'am. Sagō' bang iya ya tara'ugku, ka'am ya hinang kami banyaga'.”",
        10: "Ah'lling lagi' si Golayat, yukna, “Buwattina'an tukasku kaesogbi bangsa Isra'il! Papi'ituhunbi bang aniya' angatuhan aku.”",
        11: "Ā, pagkale bissala si Golayat itu e' si Sa'ul maka kamemon saga sundalu Isra'il, magtūy sigām angalogmay maka sinōd tāw.",
        12: "Na, ina'an si Da'ud anak si Jesse, ya min tumpuk Eprata. Si Jesse inān bay pat'nna' ma Betlehem ma lahat Yuda. Walu' heka anakna, maka ato'a na iya ma waktu kapagsultan si Sa'ul.",
        13: "T'llungan anak si Jesse kasiyakahan bay ameya' ma sultan Sa'ul ma pagbono'an. Ya siyaka to'ongan si Iliyab, bo' si Abinadab, bo' si Samma,",
        14: "maka si Da'ud ya kasiyalihan. Jari ya t'llungan anak siyaka ameya' na pa'in ma si Sa'ul ma pagbono'an,",
        15: "ati si Da'ud ya magpehē'-pi'itu. Bay pa'in iya maghinang ma si Sa'ul, amole' iya pabalik ni Betlehem angipat saga bili-bili mma' sigām.",
        16: "Manjari magmairan na pa'in si Golayat ma matahan bangsa Isra'il, waktu subu maka waktu kohap ma deyom mpatpū' llaw.",
        17: "Dakayu' llaw, magpanoho'an si Jesse ma si Da'ud, yukna, “Oto', pasa'ut ka pehē' ni pustu saga siyakanu. Bowahin sigām dakarut pai-tirigu bay sinanglag maka sangpū' solag tinapay itu.",
        18: "Bowahin isab nakura' tumpukan sigām sangpū' solag gatas apīt. Maka nda'un isab kahālan saga siyakanu mahē', ati bowahin aku lapal in sigām asalamat du.",
        19: "Wa'i sigām magbeya' maka sultan Sa'ul maka kamemon sundalu Isra'il ma L'bbak Ela, magbono' na pa'in maka bangsa Pilistin.”",
        20: "Dai' llaw pa'in, pabangun na si Da'ud bo' pang'bbana saga bili-bili ma dakayu' magi'ipat bili-bili du isab. Palanjal na iya amowa saga balanja' buwat bay panoho'an mma'na, ati makat'kka iya pehē' hinabu ma pal'ngnganan pa'in saga magbobono' bangsa Isra'il ni atag pagbono'an. Ina'an sigām angolang panukas palbantahan sigām bangsa Pilistin.",
        21: "Sakali, magharap na sundalu Isra'il maka sundalu Pilistin.",
        22: "Pagka buwattē', pang'bba e' si Da'ud ma magjajaga balanja' ai-ai bay bowana bo' magdai'-dai' pehē' angowa' ma saga siyakana.",
        23: "Hinabuna lagi' magbissala maka sigām, ina'an na si Golayat a'a Gāt an'ngge min dahuwan saga pagkahina sundalu Pilistin, maka he'na isab anukas kaesog bangsa Isra'il buwat bay kahaba'. Jari takale itu he' si Da'ud.",
        24: "Pag'nda' saga sundalu bangsa Isra'il ma si Golayat, magtūy sigām magdauragan kabowa tāw sigām.",
        25: "Magupama na pa'in saga sundalu inān, yuk-i, “Nda'unbi ba a'a inān. Llaw-llaw iya paluwas min pustuna anukas bangsatam Isra'il. Yuk suli-suli, sai ya makapapatay ma si Golayat tinungbasan alta' aheka e' sultan Sa'ul. Pamah'nda isab e'na anakna budjang ma a'a makapatay si Golayat, ati saga anak-kampungna mbal na pinabayad buwis parinta.”",
        26: "Atilaw gi' si Da'ud ma saga a'a ya ma atagna, yukna “Ai kono' panungbas ma a'a makapatay a'a bangsa Pilistin itu, maka amuwas kaiya'antam bangsa Isra'il? Sai sa kapil itu ya makatawakkal anukas saga sundalu ya suku' Tuhan kakkal salama-lama?”",
        27: "Binalikan e' saga a'a inān ya bay pagupama sigām, yuk-i, “Buwattē' ya panungbas e' sultan ma sai ya makapatay ma Pilistin ilu.”",
        28: "Na, pagkale si Eliyab ya siyaka si Da'ud ma bay panilawna ma saga sundalu inān, magtūy akagit atayna. Angkan pah'llinganna si Da'ud, yukna, “Magay ka mailu? Sai bay pang'bbahannu saga bili-bili salat-salat ma paslangan he'? Kata'uwanku ka'a maka pagabbunu. Mamarahi to'ongan la'at pikilannu. Hal ko' ka ilu bay pi'itu ang'nda'-ng'nda' pagbono' itu!”",
        29: "Ya sambung si Da'ud, “Angay?” yukna. “Ai bay hinangku? Halam bahā' aniya' kapatutku minsan hal atilaw?”",
        30: "Jari pataikut si Da'ud min siyakana bo' atilaw ma a'a saddī ma pasal ina'an-i. Sakali magsali' du panambung sigām ma iya.",
        31: "Na, takale suli-suli si Da'ud itu ati tahaka ni si Sa'ul, angkan iya pinalinganan sinō' pehē' ni sultan.",
        32: "Pagt'kka si Da'ud, ah'lling iya ni si Sa'ul, “Tuwan sultan,” yukna, “subay kitam mbal niumagad ma a'a Pilistin ilu! Aku ya pehē', tuwan, angatuhan iya!”",
        33: "Ya sambung si Sa'ul ma iya, “Oy! Mbal ka maka'atuhan Pilistin ilu. Onde'-onde' gi' ka, bo' iya inān magbobono' asal min bay lagi' kabata'na.”",
        34: "Sagō' ah'lling si Da'ud ni si Sa'ul, yukna, “Tuwan, aku itu magi'ipat saga bili-bili mma'ku. Sakahaba' aniya' bili-bili tatanga' e' halimaw atawa baruwang,",
        35: "aku iya magbaran anurul ati puwasanku bili-bili min bowa' sattuwa he'. Tabīng pa'in aku e' sattuwa he', magtūy lurayku ma bū-langalna bo' papatayku.",
        36: "Aho', tuwan sultan, aheka saga halimaw maka baruwang bay tapapatayku angkan pasali'ku a'a kapil bangsa Pilistin itu ni dakayu' sattuwa inān, pagka tatukas e'na kasundaluhan suku' Tuhan, ya kakkal salama-lama.”",
        37: "Ah'lling lagi' si Da'ud, yukna, “Ya PANGHŪ' -Yawe bay angalappasan aku min kukku halimaw maka min kukku baruwang, ya du isab Tuhan angalappasan aku min pang'ntan a'a Pilistin itu.” Pagka buwattē' pa'in, ah'lling si Sa'ul ni si Da'ud, yukna, “Na, pehē' ka angatu. Bang pa'in PANGHŪ' pabeya' ma ka'a.”",
        38: "Manjari, pinasulug he' si Sa'ul saga pamakayna pagbono' ma si Da'ud. Pinasulug sarukna tumbaga ni kōk si Da'ud, badju'na basi' ma puhu'na.",
        39: "Pagubus itu, magtinakos si Da'ud kalis si Sa'ul, pinakambotan pehē' ni badju'na pagbobono'. Sagō' agon iya mbal makal'ngngan pagka mbal biyaksa, angkan iya ah'lling ni si Sa'ul. “Tuwan sultan,” yukna, “mbal aku makapamono' bang aku magbinadju' saga pakayan itu sabab halam aku biyaksa.” Minnē' niurusan e' si Da'ud.",
        40: "Jari ningā' e'na tungkudna bo' pehē' ni sapa' amene' lima batu-batu alanu', pinat'nna' e'na ni deyom puyu'-puyu' ya asal pinagbowa e'na ma waktu kapangipatna saga bili-bili. Binowa isab pitikanna bo' pal'ngngan tudju ni si Golayat ya a'a Pilistin e'.",
        41: "Salta', pina'an si Golayat tudju ni si Da'ud, maka ina'an isab magbobowa tamingna min dahuanna.",
        42: "Pag'nda' si Golayat ma si Da'ud in iya onde' baha'u lagi' maka ahāp luwana, magtūy iya niudju' e'na.",
        43: "Yukna ma si Da'ud, “Hōy! Ai pangannalnu ma aku? Ero' bahā', angkan ka pi'itu ni aku maka kayu-kayunu ilu?” Sinabbut isab e'na saga tuhan ya pagtuhanan bangsa sigām Pilistin bang pa'in si Da'ud taluwa' sukna'.",
        44: "Amissala lagi' iya ma si Da'ud, “Pasōng ka pi'itu,” yukna, “bo' pamakanku isinu ilu ma saga manuk-manuk maka saga sattuwa talun!”",
        45: "Anambung si Da'ud ma Pilistin e', yukna, “Ka'a ilu magbowa kalis, budjak aheya maka budjak ariki', sagō' atuhanta ka ma ōn si Yawe, ya Tuhan tatukasnu itu. In iya Tuhan Sangat Kawasa, ya pagtuhanan saga sundalu Isra'il.",
        46: "Ma llaw itu, tinukbal ka ni aku e' PANGHŪ' -Yawe ati papatayta ka maka ponggolanku kōknu. Pakakanku bangkaybi bangsa Pilistin ma saga manuk-manuk maka saga sattuwa talun, ati tasayu e' kamemon manusiya' aniya' Tuhan sab'nnal-b'nnal ma bangsa Isra'il.",
        47: "Kamemon saga a'a sikatimukan itu song makata'u in si Yawe makalappas saga a'a suku'na minsan halam aniya' kalis atawa budjak pakokosna. Ma iya asal in da'ugan ma pagbono' itu, ati tinukbal kam e'na ni komkoman kami.”",
        48: "Na, pagsekot na pa'in si Golayat, arak parugpak, magtūy paragan si Da'ud amāk iya.",
        49: "Kino'ot e'na dakayu' batu-batu min deyom puyu'-puyu'na bo' magtūy pinitik si Golayat. Taluwa' iya ma tuktukna ati paloblob batu he'. Magtūy iya humantak para'ub.",
        50: "Sakali anganda'ug si Da'ud minsan hal pitikan maka batu ma tanganna. Minsan halam kalisna, tabono'na maka tapatayna si Golayat.",
        51: "Paghantak si Golayat itu, paragan magtūy si Da'ud bo' an'ngge ma atagna. Nihublut e'na kalis si Golayat bo' papatayna. Pagubus, pinonggolan e'na kōk. Na, pag'nda' bangsa Pilistin in sundalu sigām babantugun amatay na, magtūy sigām maglahian.",
        52: "Sakali, magolangan saga sundalu bangsa Isra'il maka bangsa Yuda maka e' sigām pasōng ni dahuwan bo' angapas saga Pilistin sampay ni bihing da'ira Gāt maka ni pagsosōran ni Ekron. Sikahantalan bangkay saga sundalu Pilistin ma bihing lān min Sa'araim sampay ni Gāt maka ni Ekron.",
        53: "Pagbalik saga sundalu Isra'il min bay panurulan ma saga sundalu Pilistin, tataban magtūy e' sigām kamemon ai-ai takapin ma pustu saga sundalu Pilistin.",
        54: "Jari binowa e' si Da'ud kōk si Golayat ni Awrusalam, sagō' saga pakokos si Golayat bay bowana ni toldana.",
        55: "Maka'nda' pa'in si Sa'ul ma kapangatu si Da'ud ma si Golayat, atilaw iya ma si Abner ya nakura' saga sundaluna. “Abner,” yukna, “anak sai sa onde' baha'u inān?” “Minsan aku pasapanu tuwan sultan, mbal kata'uwanku,” yuk sambung si Abner.",
        56: "Yuk sultan lagi', “Panilawun bang anak sai iya.”",
        57: "Manjari makabalik pa'in si Da'ud min kapamono'na ma si Golayat, binowa iya e' si Abner paharap ni si Sa'ul, salta' ina'an lagi' kōk si Golayat binenten e'na.",
        58: "Atilaw si Sa'ul ma si Da'ud, “Anak sai ka, oto'?” yukna. Anambung si Da'ud, “Tuwan sultan,” yukna, “aku itu anak dakayu' tendognu si Jesse, a'a min Betlehem.”",
    },
    18: {
        1: "Na, aubus pa'in pagbissala si Da'ud maka si Sa'ul, makapagda'atay iya maka si Jonatan ya anak si Sa'ul. In lasa si Jonatan ma si Da'ud sali' du lasana ma baranna.",
        2: "Tinagna'an min llaw ina'an, halam na pinapole' e' si Sa'ul si Da'ud ni okoman mma'na.",
        3: "Sakali itu, pagka alasa si Jonatan ma si Da'ud buwat e'na alasahan baranna, bay iya magjanji' maka si Da'ud.",
        4: "Nihurusan e' si Jonatan jubana bo' pamuwanna ma si Da'ud, beya' isab s'mmekna pagbobono' maka kalisna sampay pana'na maka kambotna.",
        5: "Pi'ingga-pi'ingga panoho'an si Sa'ul ma si Da'ud, aheya sadja da'uganna angkan iya tahinang nakura' alanga ma saga sundalu. In kapat'nna' ma si Da'ud itu makasulut pangatayan kamemon saga a'a Isra'il sampay saga pagnakura'an sundalu si Sa'ul.",
        6: "Manjari waktu lagi' bay kapamole' saga sundalu Isra'il puwas bay tapatay e' si Da'ud si Golayat, pina'an pabāk ni si Sa'ul saga kar'ndahan min katilingkal kauman Isra'il magpangigal maka magkalangan, magbowa sigām tambul-tambul maka biyula.",
        7: "Hinabu sigām magpangigal, angalang sigām buwattitu, “Ibuhan tapatay e' sultan Sa'ul, maka hatusan ibu isab ma si Da'ud.”",
        8: "Pagkale si Sa'ul ma pagkalang itu, landu' iya angastol angkan yukna ma deyom atayna, “Bang ma saga a'a itu hatusan ibu ya bay tapatay e' si Da'ud bo' aku itu ibuhan sadja. Na, ai lagi' bahā' takapin ya makajari niagaw e'na? Luwal la'a pagsultanku.”",
        9: "Angkan tinagna'an min llaw inān ala'at na pang'nda' si Sa'ul ma si Da'ud kabowa pangimbūna.",
        10: "Manjari pag'llaw dakayu', aniya' saitan bay min Tuhan pasangon ni si Sa'ul. Binelaw iya, maka magligaw e'na amissala ma deyom luma'na, hinabu si Da'ud magbiyula buwat kabiyaksahanna. Na, aniya' budjak ma tangan si Sa'ul,",
        11: "ati yukna ma deyom atayna, “Gom lagbasku si Da'ud itu ni dinding.” Sakali, binudjak si Da'ud e' si Sa'ul, daipara katangkisan e'na min duwa.",
        12: "Aheya tāw si Sa'ul ma si Da'ud sabab tinabang na pa'in iya e' PANGHŪ' -Yawe bo' si Sa'ul tinaikutan na.",
        13: "Pagka buwattē', pinatulak e'na si Da'ud bo' pinagmakōk ma tumpukan sundalu dangibu hekana. Jari magmakōk si Da'ud ma saga sundaluna pi'ingga-pi'ingga ya pagbono'an sigām.",
        14: "Ajatu kamemon kahinanganna sabab ina'an asal PANGHŪ' pat'ttog ma iya.",
        15: "Ya itu sababan angkan pasōng gom pa'in tāw si Sa'ul ma si Da'ud.",
        16: "Malaingkan in kamemon a'a Isra'il maka Yuda palasa ma si Da'ud sabab ahāp e'na magmakōkan sigām ma pagbono'an.",
        17: "Na, aniya' waktu ah'lling si Sa'ul ni si Da'ud, yukna, “Bang aesog e'nu amogbogan aku maka bang t'nggehannu pahāp pagbono' PANGHŪ', pamah'ndaku ma ka'a si Merab, ya anakku siyaka.” Buwattē' pamissala si Sa'ul sabab ma pikilanna ngga'i ka iya ya amapatay si Da'ud, sagō' saga bangsa Pilistin.",
        18: "Saguwā' anambung si Da'ud. “Tuwan,” yukna, “aku maka saga matto'a-danakanku sampay na saga ka'mbo'anku itu a'a areyo' du ko' ma bangsa Isra'il. Angkan mbal aku patut amikit ni sultan.”",
        19: "Malaingkan, ta'abut pa'in waktu bay panugun pamakawin si Merab ma si Da'ud, pinakawin na iya ma l'lla saddī ya pinagōnan si Adare'el, a'a min Mehola.",
        20: "Na, si Mikal, ya anak si Sa'ul budjang kasiyalihan, bilahi sidda ma si Da'ud. Jari pagta'u si Sa'ul ma pasalan itu-i kasulutan iya.",
        21: "Yukna ma deyom atayna, gom pamah'ndaku si Mikal ma si Da'ud supaya iya takatina amono' bo' pinapatay e' saga bangsa Pilistin. Angkan binalikan e' si Sa'ul bay llingna ma si Da'ud, yukna, “Makajari na ka tahinang ayuwanku.”",
        22: "Manjari magpanoho'an si Sa'ul ma saga tendogna sinō' magbissala maka si Da'ud ma halam aniya' makata'u. Sinō' sigām amissalahan iya buwattitu, “Kasulutan sultan ma ka'a, maka kinalasahan ka e' kamemon saga tendogna, angkan ahāp lagi' bang ngā'nu na h'nda anakna he'.”",
        23: "Jari buwattē' pamissala saga tendog inān ma si Da'ud, sagō' anambung iya, yukna, “Angay, taluhay-luhaybi bahā' tahinang dakayu' ayuwan sultan? Aku itu a'a miskin maka ngga'i ka babantugun.”",
        24: "Makata'u pa'in si Sa'ul pasal bay kabtangan si Da'ud he',",
        25: "yuk panambungna, “Haka'inbi si Da'ud buwattitu, ‘Halam aniya' saddī ungsud niamu' min ka'a e' sultan, luwal dahatus kuwit bay pangislaman min bangsa Pilistin. Minnē' makabalos in sultan ma saga bantana.’” Sagō' ya to'ongan mohot si Sa'ul in si Da'ud tapapatay e' bangsa Pilistin.",
        26: "Pagkale si Da'ud ma pamissala saga tendog inān, sulut na iya tahinang ayuwan sultan Sa'ul. Angkan minsan halam lagi' ta'abut waktu bay panugun,",
        27: "parugpak si Da'ud maka saga sundaluna ni bangsa Pilistin, ati tapatay e' sigām saga duwa hatus puhu'. Pagubus, binowa e' si Da'ud duwa hatus kuwit bay pangislaman min saga Pilistin e'. Ni'nde'an e'na ni si Sa'ul supaya iya makajari na ayuwan sultan. Pagka buwattē', bay pamakawin e' si Sa'ul anakna si Mikal ma si Da'ud.",
        28: "Tasayu pa'in e' si Sa'ul in si Da'ud tinabang e' PANGHŪ' maka kinalasahan e' anakna si Mikal,",
        29: "gom pa'in magduruhun tāwna. Jari binantahan si Da'ud e' si Sa'ul sat'ggolna allum.",
        30: "Na, masi na pa'in saga pagnakura'an bangsa Pilistin amowa magbono' maka bangsa Isra'il buwat asal daran nihinang e' sigām. Jari kahaba' sigām parugpak ni saga Pilistin, aheya da'ugan si Da'ud min kasehe'an saga nakura' sundalu si Sa'ul. Minnē' landu' abantug ōn si Da'ud.",
    },
    19: {
        1: "Na, magsuli-suli si Sa'ul ma anakna si Jonatan maka saga tendogna pangandolan pasal si Da'ud subay pinapatay. Sagō' alasa to'ongan si Jonatan ma si Da'ud,",
        2: "angkan iya binanda'an e'na. Yuk si Jonatan, “Angamohot mma'ku si Sa'ul amapatay ka'a, angkan ka subay pahalli' salung subu. Amiha ka lugal patapukannu. Ebot-ebot, da'a ka magluwas-luwas.",
        3: "Pagsalung, magbeya' aku maka mma'ku ni huma ya patapukannu. Bissalahanku iya ma pasalannu, jari haka'anta pa'in ka bang ai ya kaluwasanna.”",
        4: "Sakali pag'llaw dakayu' pa'in, binissalahan si Sa'ul e' si Jonatan pasalan kahāp si Da'ud. Yukna, “Mma', da'a inayun si Da'ud sabab halam iya bay angala'at ka'a. Bang pina'amu, in kamemon bay tahinangna aheya sidda katabanganna ma ka'a.",
        5: "Bay paglilla'na kallumna waktu kapamono'na si Golayat ati aheya da'ugan bay pamuwan PANGHŪ' ma kitam bangsa Isra'il. Kasaksi'annu itu kamemon maka kinōgan ka isab. Na, angay la'atnu a'a halam dusahan buwat si Da'ud angkan iya subay papataynu?”",
        6: "Tabowa si Sa'ul ma pamissala si Jonatan inān angkan iya ah'lling, yukna, “Sapahanku ma ōn si Yawe ya kakkal salama-lama, in si Da'ud mbal na pinapatay.”",
        7: "Sakali pinalinganan si Da'ud e' si Jonatan bo' pangahakana kamemon bay kapagbissalahanna maka mma'na. Manjari binowa si Da'ud ni si Sa'ul, ati maghinang iya ma deyo'an sultan buwat bay ka'ina tagna'.",
        8: "Malaingkan paniya' na isab bono' aheya, jari pehē' si Da'ud angandugpak ni bangsa Pilistin. Apaslod sidda pangandugpakna angkan maglahian sadja saga sundalu Pilistin.",
        9: "Sagō' aniya' na saitan bay min PANGHŪ' pasōd ni si Sa'ul hinabuna aningkō' ma deyom luma'na maka he'na ang'ntanan budjakna. Sakali itu, hinabu si Da'ud magbiyula,",
        10: "binudjak iya magtūy e' si Sa'ul. Daipara makatangkis si Da'ud, bo' budjak inān tumaluwa' sadja ni dinding. Jari ma sangom du inān, alahi si Da'ud minna'an.",
        11: "Sakali, magpanoho'an si Sa'ul ma saga tendogna sinō' anganjagahan luma' si Da'ud, ati sinō' iya pinapatay pagsubu. Daipara binanda'an si Da'ud e' h'ndana si Mikal, yukna, “Tuwanku, bang ka mbal alahi sangom itu, tantu ka binono' salung.”",
        12: "Angkan pinaluwas si Da'ud e' si Mikal labay min tandawan bo' iya magtūy alahi.",
        13: "Manjari aniya' ta'u-ta'u bay ningā' e' si Mikal. Pinabahak e'na ma kantil bo' yampa minantahan e'na, maka pinat'nna'an bū kambing isab ma kōkna.",
        14: "Pagt'kka pina'an saga tendog si Sa'ul bahasa anaggaw si Da'ud, ah'lling si Mikal ni sigām in si Da'ud ina'an asaki.",
        15: "Kahaka'an pa'in si Sa'ul, magtūy iya magpanoho'an ma saga a'a inān, yukna, “Pabalik kam pehē' bo' bowahunbi pi'itu si Da'ud beya' maka pabahakanna. Aku magbaran ya amapatay iya.”",
        16: "Anā, pagsōd pa'in saga sosoho'an inān ni deyom bilik, luwal ta'u-ta'u ya ta'nda' sigām pat'nna' ma pabahakan e', maka bū kambing ma kōkna.",
        17: "Pinah'llingan si Mikal e' si Sa'ul, yukna, “Angay aku akkalannu? Angay dūlannu bantaku alahi?” Yuk sambung si Mikal ni mma'na, “Ya llingna ma aku, in aku papatayna kono' bang iya mbal tugutanku alahi.”",
        18: "Manjari makalahi pa'in si Da'ud, pehē' iya ni Rama bo' angahaka'an si Samwel pasal kamemon bay kahinangan si Sa'ul ma iya. Pagka buwattē' pa'in, magbeya' sigā karuwangan ni lūngan Nayot bo' mahē' pat'nna'.",
        19: "Kahaka'an pa'in si Sa'ul in si Da'ud kono' wa'i ma Nayot, ma kauman Rama,",
        20: "magtūy iya anoho' saga tendogna pehē' anaggaw iya. Saguwā' pagt'kka saga tendog itu, ta'nda' e' sigām dakayu' tumpukan nabi amaluwas bissala mbal tahati, maka ina'an isab si Samwel pagmakōkan sigām. Jari pahōp Rū Tuhan ma saga tendog inān, maka ya du sigām tabowa amaluwas bissala ya mbal tahati.",
        21: "Makata'u pa'in si Sa'ul pasal itu-i, aniya' tendogna saddī bay soho'na pehē'. Ya du sigām tabowa amaluwas bissala buwattē'. Jari aniya' gi' tendog kasehe' pinapehē' e' si Sa'ul, kamint'lluna na, ati ya du sigām isab amaluwas bissala mbal tahati.",
        22: "Katapusanna, magbaran si Sa'ul pehē' ni Rama bo' ni k'ppong aheya ya ma lahat Seku. Maina'an pa'in, atilaw iya, yukna, “Maingga bahā' si Samwel maka si Da'ud?” Ya sambung saga a'a bay panilawan, “Tuwan sultan, wa'i sigā ma Rama, ma lūngan Nayot.”",
        23: "Sakali, palanjal si Sa'ul ni Nayot, sagō' ya du iya kahōpan e' Rū Tuhan ati aniya' bissala mbal tahati pinaluwas e'na sampay tat'kkana lūngan Nayot e'.",
        24: "Maina'an pa'in, nihurusan e' si Sa'ul pan'mmekna maka ya du iya tabowa magbissala kaligawan ma matahan si Samwel. Jari pabahak iya maka panantangna animpus dang'llaw dambahangi. Ya itu sababan angkan pinagsambatan e' a'a, “Nabi bahā' sampay si Sa'ul?”",
    },
    20: {
        1: "Manjari, alahi na isab si Da'ud min lūngan Nayot ya ma Rama inān tudju ni si Jonatan. Ya panilawna ma si Jonatan e', “Ai kasā'an bay tahinangku? Ai dusaku ma mma'nu angkan iya angamohot amapatay aku?”",
        2: "Yuk sambung si Jonatan. “Oy, s'lle' bale puhu'nu! Mbal ko' ka'a ilu pinapatay e' si mma'! Ai-ai kahinanganna aheya-ariki', subay pangaru e'na dahū ni aku.” Yuk lagi' si Jonatan, “Angay angkan limbunganna min aku niyatna amapatay ka'a? Suli-suli sadja ko' ilu, da'a beya'-beya'un.”",
        3: "Sagō' anapa si Da'ud bo' anambung, yukna, “Kinata'uwan e' mma'nu in aku makasulut pangatayannu angkan pangannalna in ka'a subay mbal pinata'u sabab ya aniya' magkarukka'an lagi' ka.” Anubahat lagi' si Da'ud, yukna, “Sapahanku ma ōn si Yawe ya Tuhan kakkal salama-lama, maka ma ōnnu isab, in aku itu marai' na pinapatay.”",
        4: "Na, ah'lling si Jonatan, yukna, “Haka'in aku bang ai kabaya'annu. Tantu hinangku ma ka'a.”",
        5: "Ya panambung si Da'ud, “Salung,” yukna, “Paghinang Bulan Baha'u, maka subay aku pajamu ma sultan. Sagō' dūlin lagi' aku patapuk ma kahuma'an deya sampay ni kasangoman ma llaw sumuddai.",
        6: "Bang saupama tasayuna in aku alikut, ah'lling ka ni iya, yuknu, ‘Bay ama'id si Da'ud min aku bo' pasa'ut amole' ni Betlehem, ya lahatna luggiya'. Subay tasabuna hinang Pagtaubat sigām maglaulahasiya'.’”",
        7: "Amissala lagi' si Da'ud, yukna, “Bang hal angaho' mma'nu, hatina asalamat aku. Sagō' bang iya angastol, tantu aniya' niyatna angala'at aku.",
        8: "Aniya' isab panganjunjungku ni ka'a, tuwan. Atanu asal aku, jari hinangin aku kahāpan ma sabab paljanji'an ya bay pagsapahanta ma matahan PANGHŪ'. Bang b'nnal aniya' kasā'an bay tahinangku, na, ka'a na ya magbaran amapatay aku! Da'a sadja aku tukbalun ni mma'nu.”",
        9: "Ya sambung si Jonatan ma si Da'ud, “Oy! Da'a ka magpikil buwattilu,” yukna. “Bang hati tasayuku b'nnal-b'nnal aniya' niyat mma'ku angamula ka'a, pata'uta ka magtūy.”",
        10: "Atilaw si Da'ud, yukna, “Bang saupama akasla panambung mma'nu ma ka'a, sai amata'u aku?”",
        11: "Anambung si Jonatan yukna, “Sūng kita kaleya.” Jari pehē' na sigām.",
        12: "Ma huma pa'in, yuk si Jonatan ma si Da'ud, “Saksi'ta si Yawe ya pagtuhanan bangsa Isra'il, salung atawa sumuddai ma sali' waktu buwattitu du, bowaku magbissala si mma'. Bang hati ahāp pamikilna ma pasalannu, pabeya'anta pa'in ka lapal.",
        13: "Saguwā' bang iya magmohot angala'at ka'a, bang pa'in aku pinagmulka'an e' PANGHŪ' bang ka mbal magtūy pata'uku bo' supaya ka makalahi. Mura-murahan bang pa'in ka ginapi' e' PANGHŪ' buwat bay panganggapi'na ma mma'ku.",
        14: "Malaingkan pangamu'ku isab ma ka'a bang pa'in aku pa'nda'annu kahāpan sat'ggolku allum, buwat kahāpan PANGHŪ'. Maka bang aku saupama amatay,",
        15: "da'a b'kkatun kahāpannu ma saga panubu'ku, minsan aligis e' PANGHŪ' kamemon palbantahannu min babaw dunya itu.”",
        16: "Sakali aniya' lagi' paljanji'an si Jonatan ma si Da'ud maka panubu'na, yukna, “Bang pa'in tinungbasan e' Tuhan saga palbantahan si Da'ud.”",
        17: "Kinalasahan si Da'ud e' si Jonatan buwat e'na alasahan baranna, angkan soho'na si Da'ud amatuman janji'na, ma sabab lasana isab ma si Jonatan.",
        18: "Pagubus, ah'lling si Jonatan ma si Da'ud, yukna, “Salung na in Paghinang Bulan Baha'u, angkan tantu ko' ka'a ilu piniha he' si mma' pagka halam a'a ma tingkō'annu.",
        19: "Na, ma sumuddai he', saga abay kohap, pehē' ka ni lugal ya bay patapukannu waktu panagna' paniya' palkala' itu. Angagad ka mahē' ma tambak batu ya niōnan Esel,",
        20: "ati amana' aku mint'llu ni kīd batu patapukannu he', buwat hantang to'ongan aniya' pana'ku.",
        21: "Soho'ku dakayu' onde' l'lla angā' pana' he'. Jari bang yukku ma iya, ‘Ina'an saga pana' ma atag batu tampal pi'itu, bowahun pi'itu,’ makajari ka paluwas. Sapahanta ka ma kallum PANGHŪ', halam aniya' la'at tum'kka ni ka'a. Asalamat ka.",
        22: "Sagō' bang yukku ni onde' ya soho'ku inān, ‘Wa'i ma katāhan saga pana',’ hatina subay ka pasa'ut alahi sabab ya na kahandak PANGHŪ' ma ka'a.",
        23: "Maka pasal bay paljanji'anta inān, entomun pahāp, PANGHŪ' ya saksi'ta sampay salama-lama.”",
        24: "Buwattē' pa'in, patapuk na si Da'ud ma lugal bay kapagisunanna maka si Jonatan. Ta'abut pa'in Paghinang Bulan Baha'u, ina'an na sultan Sa'ul aningkō' ma pagjamuhan.",
        25: "Maina'an iya aningkō' ma bihing dinding, buwat kabiyaksahanna. Magalop iya maka si Jonatan, maka ina'an isab si Abner ma bihingna. Sagō' in paningkō'an si Da'ud halam maga'a.",
        26: "Halam ah'lling-h'lling si Sa'ul itu, sabab ma pikilanna, kalu aniya' bay tahinang e' si Da'ud ya makabatal iya.",
        27: "Sagō' pag'llaw dakayu' pa'in, llaw karuwana ma bulan inān, halam na isab maga'a paningkō'an si Da'ud. Angkan atilaw si Sa'ul ma anakna si Jonatan, yukna, “Angay sangay di'ilaw, halam pajamu pi'itu anak si Jesse ilu?”",
        28: "Anambung si Jonatan, yukna, “Bay iya ama'id min aku, mma', amole' kono' iya ni Betlehem.",
        29: "Yukna ma aku, ‘Dūlin lagi' aku amole' sabab in kami magkaukampung maghinang pagkulban ma kauman kami. Bay aku niamay-amayan e' danakanku,’ yukna, ‘sinō' pahadil.’ Bang kono' makajari ma aku,” yuk si Jonatan, “tinugutan iya amole' bo' mag'nda' maka dauranakanna. Na, ya ilu sababan angkan halam makapi'itu si Da'ud ni pagjamuhan.”",
        30: "Angastol to'ongan si Sa'ul pagkalena ma bissala si Jonatan itu, angkan yukna, “Ē! Halambiyara' itu, mamarahi tuwas kōknu. Aheya to'ongan dapitnu ma si Da'ud. Kaiya'an aheya ko' ilu ma ka'a sampay ma ina'nu!",
        31: "Halam tasayunu sat'ggol masi allum anak si Jesse ilu ma babaw dunya itu, mbal ka makapagsultanan paglahat itu. Na, soho'un iya binowa pi'itu sabab patut iya subay pinapatay!”",
        32: "Anambung si Jonatan yukna, “Angay angkan subay pinapatay si Da'ud? Ai dusana?”",
        33: "Pagka buwattē' panambung si Jonatan, magtūy iya nihiyak e' si Sa'ul maka budjak. Minnē' kinata'uwan e' si Jonatan in mma'na magmohot to'ongan amapatay si Da'ud.",
        34: "Sakali akagit to'ongan atay si Jonatan ati an'ngge iya magtūy min pagkakanan. Manjari ma llaw pagjamu karuwana, halam iya amangan sabab ap'ddi' landu' atayna pasalan pangahina' mma'na ma si Da'ud.",
        35: "Na, pag'llaw dakayu', pehē' na si Jonatan ni huma bay kapagisunanna pagbākanna maka si Da'ud. Aniya' isab onde' l'lla ameya' ma si Jonatan,",
        36: "manjari ah'lling iya ni onde' inān, yukna, “Paragan ka pehē' bo' piha'un saga pana' ya pamana'ku itu.” Sakali, hinabu paragan onde' itu, pinaleyang e' si Jonatan dakayu' pana' pinaliyu min iya.",
        37: "Pagt'kka onde' ni lugal kahūgan pana' he', niolangan iya e' si Jonatan, yuk-i, “Ilu pana' ma dahuannu!",
        38: "Na, pal'kkasun dagannu ilu! Da'a ka maghogga'-hogga'!” Pinuwa' na pana' inān he' onde' bo' ni'nde'an ni nakura'na si Jonatan.",
        39: "Tu'ud halam panghati onde' inān ma saga palkala' he', luwal si Jonatan maka si Da'ud ya makata'u.",
        40: "Pagubus itu, sinōngan e' si Jonatan pana'na ni onde' l'lla inān bo' soho'na amole'. “Pehē' na ka,” yukna, “bowahun saga pana' itu amole' ni kauman.”",
        41: "Makala'an pa'in onde' he', paluwa' na si Da'ud min liyu batu bay patapukanna bo' pasujud mint'llu ma dahuwan si Jonatan. Manjari, maggapus sigām karuwangan maka he' sigām magtangis. Saguwā' palabi heya tangis si Da'ud min si Jonatan.",
        42: "Yuk si Jonatan ma iya, “Na, bagay, bang pa'in ka mura-murahan asalamat. Ma takdil kapagbagayta, PANGHŪ' ya saksi' ma saga paljanji'anta karuwangan sampay ma saga panubu'ta magsuring-magsaingsing.” Pagubus itu, ala'an na si Da'ud minnē', bo' si Jonatan pabalik na ni kauman.",
    },
    21: {
        1: "Pabutas pa'in si Da'ud min si Jonatan, pehē' na iya ni kauman Nōb bo' tibawna imam Ahimelek. Pagbāk si Ahimelek itu ma si Da'ud, amidpid iya kabowa tāwna. Atilaw iya, yuk-i, “Angay ka karangan-danganan ilu? Angay halam sehe'nu?”",
        2: "Yuk sambung si Da'ud, “Aniya' bay panoho'an aku e' sultan. Bay aku binanda'an e'na sinō' mbal amata'u minsan ma sai pasalan l'ngngan itu. Ma takdil saga a'aku, bay na sigām haka'anku bang maingga pagsabuhan kami.”",
        3: "Atilaw gi' si Da'ud, yukna, “Na, aniya' bahā' takakanta? Buwanin gi' aku limansolag tinapay, atawa ai-ai na aniya' mailu.”",
        4: "Anambung si Ahimelek, yukna, “Halam aniya' tinapay maitu luwal ya tinapay bay pamasuku' Tuhan, sagō' wajib sadja itu kinakan e' saga a'abi bang sigām halam bay makapaghulid maka d'nda sōngbi pi'itu.”",
        5: "Ah'lling si Da'ud yukna, “Ma addat kami, pangalāngan asal maghulid maka d'nda bang song ni pagbono'an. Asussi saga a'aku sampay pamaranan sigām minsan ma l'ngngan m'ssa' bidda'. Ya lagi'na bang ni l'ngngan aheya buwat na itu-i!”",
        6: "Sakali, pamuwan e' imam inān ma si Da'ud tinapay bay pamasuku' Tuhan, ya bay nila'anan min matahan Tuhan bo' ginanti'an magtūy maka tinapay baha'u. Halam aniya' takakan saddī tapamuwan e' imam liyu minnē'.",
        7: "Na, aniya' dakayu' sosoho'an si Sa'ul bay pasabu maina'an pagka aniya' hinangna tudju ni PANGHŪ'. Ōnna si Do'eg bangsa Edom, ya aesog to'ongan ma saga magi'ipat bili-bili si Sa'ul.",
        8: "Jari atilaw si Da'ud ma si Ahimelek, yukna, “Aniya' budjak atawa kalis maitu? Halam aku bay magbowa pakokos pagka asa'ut panoho'an sultan he'.”",
        9: "Yuk sambung imam, “Itiya' maitu kalis si Golayat a'a Pilistin ya bay tapataynu ma L'bbak Ela. Itiya' ma liyu epod, pinutus maka kakana'. Bang hati kabilahiannu, ngā'un na sabab halam aniya' saddī kalis minnilu.” Jari ah'lling si Da'ud, “Na, ndiya ma aku sabab halam na aniya' pahāp minnilu.”",
        10: "Jari itu palanjal na si Da'ud ma kalahina min si Sa'ul bo' pehē' ni si Akis, ya sultan ma da'ira Gāt.",
        11: "Mahē' pa'in, ah'lling ni si Akis saga tendogna pangandolan, yuk-i, “Ya na ko' ilu si Da'ud ya sultan ma paglahat Isra'il. Iya na a'a pinagkalangan e' saga kar'ndahan hinabu sigām magpangigal, yuk-i, ‘Ibuhan tapatay e' sultan Sa'ul, jari hatusan ibu ma si Da'ud’.”",
        12: "Tinali'-tali' pahāp e' si Da'ud pah'lling saga a'a itu, jari sinōd iya tāw landu' aheya ma sultan Akis.",
        13: "Angkan iya magbelaw-belaw di-na sakahaba' aniya' a'a ang'nda' iya. Hinabuna binalutan e' sigām, magbau'-bau' iya kinangog. Maggudlis iya indalupaginis ma saga tambol lawang ya ma ād da'ira inān, maka pinatū' isab bohelona ni p'ngngotna.",
        14: "Sakali ah'lling sultan Akis ni saga tendogna, yukna, “Nda'unbi ba a'a binelaw ilu! Angay iya bay bowabi pi'itu?",
        15: "Akulang bahā' a'a dupang ma aku, angkan bowabi a'a itu bo' magbelaw-belaw ma kamaituhanku? Pala'anunbi iya minnitu!”",
    },
    22: {
        1: "Manjari, ala'an si Da'ud min Gāt bo' alahi ni dakayu' songab batu ma lahat Adullam. Pagta'u pa'in itu e' saga matto'a-danakanna, pehē' sigām parakayu' ma iya.",
        2: "Parakayu' isab ma si Da'ud kamemon saga a'a sasuku kasigpitan maka ma deyom utang atawa taga-koto'-koto' ma deyom atay, ati tahinang iya pagnakura'an sigām. Saga mpat hatus puhu' ya heka sigām.",
        3: "Palanjal si Da'ud minnē' ni da'ira Mispa ma lahat bangsa Mowab bo' ah'lling ni sultan sigām, yukna, “Tuwan, angamu' aku junjung bang pa'in parūlnu ina'-mma'ku pahanti' ma deyomannu sampay kata'uwanku bang ai ya kahandak Tuhan ma aku.”",
        4: "Jari pang'bba e'na ina'-mma'na ma sultan Mowab he', ati mahē' sigām pahanti' sat'ggol si Da'ud pahanti' ma patapukan ahogot.",
        5: "Sagō' binanda'an si Da'ud e' nabi Gād, yukna, “Da'a ka pat'ggol ma tapukan ilu. Pehē' ka ni jadjahan Yuda.” Angkan ala'an si Da'ud minnē' bo' pehē' ni katalunan ma Heret.",
        6: "Mbal at'ggol, takale e' si Sa'ul pasal si Da'ud maka saga tendogna tabāk na. Pasalta', ina'an si Sa'ul ma Gibeya, aningkō' ma sindungan kayu tamaris ya ma būd e'. Aniya' asal budjak ma tanganna. Ina'an isab saga a'a kawakilanna an'ngge ma katilibutna.",
        7: "Jari ah'lling si Sa'ul ni sigām, yuk-i, “Akale kam pahāp, ka'am saga panubu' Benjamin! Ma pikilanbi bahā', kabuwanan kam kabbun anggul maka tana' paghuma'an e' anak si Jesse inān? Tahinang bahā' kam e'na nakura' alanga ma saga ibuhan atawa hatusan sundaluna?",
        8: "Ya bahā' ilu sababanna angkan kam magisunan aku? Angay halam aniya' minsan dangan min ka'am amata'uwan aku in anakku maka anak si Jesse bay makapagjanji'? Halam aniya' pagka'inagonbi ma aku atawa minsan hal la'a angahaka'an aku in anakku bay amidjakan iya amapatay aku ma labayan. Ina'an na iya anipihan aku buwattina'an!”",
        9: "Na ina'an isab si Do'eg, a'a bangsa Edom, samat'ngge maka saga pagnakura'an tendog si Sa'ul. Ah'lling si Do'eg itu, yukna, “Bay ta'nda'ku anak si Jesse pehē' ni kauman Nōb bo' patibaw ni si Ahimelek anak si Ahitub.",
        10: "Bay angaru si Ahimelek ni PANGHŪ' pasal si Da'ud bang ai subay hinangna, maka bay pamuwanna isab ma iya balanja' maka kalis ya bay pakokos si Golayat a'a Pilistin.”",
        11: "Manjari, magpanoho'an si Sa'ul pina'ā' si Ahimelek sampay kamemon saga kampungna ya magimam ma Nōb. Jari pina'an na sigām ni sultan.",
        12: "Maina'an pa'in, ah'lling si Sa'ul, yukna, “Akale ka Ahimelek!” “Aho', tuwan sultan,” yuk si Ahimelek.",
        13: "Atilaw si Sa'ul ma iya, yuk-i, “Angay ka bay magisun maka anak si Jesse inān bo' angatu ma aku? Bay iya buwanannu tinapay maka kalis, maka bay ka isab angaru ni Tuhan ma pasalanna, angkan iya anagga' pagsultanku maka angamohot amapatay aku ma labayan! Ina'an na iya anipihan aku buwattina'an!”",
        14: "Anambung si Ahimelek, yukna, “Tuwan, aniya' bahā' tendog kapangandolan labi min si Da'ud? Ayuwannu iya, maka pagnakura'an ma saga sundalu ya anganjagahan ka'a. Pinagaddatan isab iya e' a'a kamemon ma deyomannu.",
        15: "In pasal pangaruku ni Tuhan ma pasalanna, tuwan, ya na tu'ud kabiyaksahanku. Arapun in pasal kapagisun angatu ma ka'a, ndū' tuwan, da'a aku tuna'un atawa minsan sai-na ma kami maglaulahasiya', sabab halam aniya' pana'uku ma pasal palkala' inān.”",
        16: "Jari yuk si Sa'ul, “Ahimelek, ka'a maka saga kakampungannu ilu subay pinapatay!”",
        17: "Magtūy magpanoho'an sultan ma saga jaga ya ma bihingna, yuk-i, “Papatayun kamemon saga imam si Yawe itu sabab ya du sigām pagapi' na ma si Da'ud. Kinata'uwan e' sigām in iya alahi min aku sagō' halam bay anumbung ni aku.” Sagō' halam sai-na min saga jaga inān makatawakkal amapatay saga imam e' pagka imam si Yawe.",
        18: "Pagubus, si Do'eg ya sinoho' e' si Sa'ul. Yukna, “Na ka'a! Papatayun saga imam itu.” Jari pinapatay e' si Do'eg kamemon saga imam he'. Walumpū' maka lima ya heka sigām magpamakay epod.",
        19: "Min panoho'an si Sa'ul isab, talaglag kamemon d'nda-l'lla, kamemon saga kaonde'-onde'an, sampay isab kamemon saga hayop ya bay ma kauman Nōb.",
        20: "Luwal si Abiyatar anak si Ahimelek, mpu si Ahitub, ya bay makaliyus bo' alahi pehē' ni si Da'ud.",
        21: "Kahaka'an e'na si Da'ud in kamemon saga kaimaman si Yawe bay pinapatay e' si Sa'ul.",
        22: "Angkan ah'lling si Da'ud ma si Abiyatar, yukna, “Llaw he', pagta'uku in si Do'eg bangsa Edom bay mahē' ma Nōb, makatantu aku in iya anumbung du ni si Sa'ul. Aku palsababan ya angkan amatay saga lahasiya'nu kamemon.",
        23: "Na, maitu na ka ma aku sabab in a'a bilahi amapatay ka'a anganiyat isab amapatay aku. Da'a ka agawa sabab halam kamulahannu bang pa'in ka ma deyomanku.”",
    },
    23: {
        1: "Na, aniya' lapal pinasampay ni si Da'ud, yuk-i, “Wa'i parugpak saga bangsa Pilistin ni kauman Kela maka pinagtangkaw na pa'in he' sigām saga pai baha'u bay niani, ya ina'an ma pagt'ppahan.”",
        2: "Manjari angaru si Da'ud ni PANGHŪ' yukna, “Ya Tuhan, parugpak bahā' aku ni saga Pilistin inān?” Anambung Tuhan, “Aho'” yukna. “Dugpakun sigām bo' lappasun kauman Kela.”",
        3: "Saguwā' ah'lling ni si Da'ud saga a'ana, yuk-i, “Tuwan, minsan maitu kitam ma paglahat Yuda, landu' kitam tināw, ya lagi'na bang kitam pehē' ni Kela bahasa parugpak ni saga sundalu Pilistin.”",
        4: "Manjari angaru na isab pabalik si Da'ud ni PANGHŪ', jari buwattitu ya sambung PANGHŪ' ma iya, yuk-i, “Palūd ka pehē' ni Kela sabab pamarūlku ma ka'a in da'ugan min saga bangsa Pilistin.”",
        5: "Angkan palanjal na disi Da'ud maka saga a'ana ni Kela. Tarugpak e' sigām saga bangsa Pilistin maka ta'ā' e' sigām saga kahayopan sigām. Aheka bangsa Pilistin bay tapapatay e' sigām bo' arapun lappasan saga a'a ma Kela.",
        6: "(Ma waktu bay kalahi si Abiyatar anak si Abimelek pina'an ni si Da'ud, bay asal bowana epod.)",
        7: "Na, kahaka'an si Sa'ul pasal si Da'ud ina'an ma lahat Kela, angkan yukna, “Itiya' tinukbalan e' Tuhan si Da'ud ni komkomanku sabab wa'i iya bay angalikusan kauman kinuta', ya mbal agon kaluwasan.”",
        8: "Sakali, pinalinganan e' si Sa'ul kamemon sundaluna sinō' magsakap amono' bo' palūd ni Kela angahapa'an si Da'ud maka saga a'ana bo' mbal makaluwas min kauman e'.",
        9: "Pagta'u pa'in si Da'ud ma kagara'an si Sa'ul itu, magpanoho'an iya ma imam Abiyatar, yukna, “Bowahun pi'itu epod ilu.”",
        10: "Maina'an pa'in, angamu'-ngamu' si Da'ud ni Tuhan. Yukna, “O Yawe, Tuhan bangsa Isra'il, takaleku in si Sa'ul maggara' angalubu kauman Kela ma sababku.",
        11: "Tinukbalan bahā' aku e' saga a'a maitu-itu ni si Sa'ul? Pi'itu bahā' iya buwat bay pangalapal itu? Ya PANGHŪ' kami bangsa Isra'il, sambungin lagi' sosoho'annu itu.” Sakali anambung PANGHŪ' yukna, “Aho', tantu pi'ilu si Sa'ul.”",
        12: "Manjari, angamu'-ngamu' pabalik si Da'ud yukna, “Tinukbalan bahā' aku maka saga a'aku ni si Sa'ul e' saga a'a Kela?” Ya sambung PANGHŪ', “Aho'.”",
        13: "Pagka buwattē', si Da'ud maka saga a'ana kulang-labi nnom hatus hekana magla'anan na min Kela bo' maglatun-latun ma kalahatan. Tata'u pa'in e' si Sa'ul in si Da'ud wa'i na makalahi min Kela he', halam na iya pehē'.",
        14: "Manjari itu, pahanti' na pa'in disi Da'ud ma saga patapukan ahogot ma paslangan Sīp maka ma kabūd-būran. Piniha iya e' si Sa'ul sakahaba' llaw, sagō' mbal iya tinugutan e' Tuhan ni komkoman si Sa'ul.",
        15: "Dakayu' llaw, ma Hores pa'in si Da'ud, ma paslangan Sīp, tata'una in si Sa'ul song pina'an amapatay iya.",
        16: "Sakali pina'an si Jonatan ni si Da'ud hinabuna ma Hores, bo' pinahogot e'na iman si Da'ud.",
        17: "Yuk si Jonatan ma si Da'ud, “Da'a ka tināw sabab tantu mbal ka tainay e' mma'ku si Sa'ul. Kata'uwanna asal in ka'a magsultan ma Isra'il maka aku itu ma deyo'annu.”",
        18: "Jari magpaljanji'an sigā karuwangan ma matahan PANGHŪ'. Pagubus itu, amole' na pabalik si Jonatan, saguwā' magpa'bba si Da'ud ma Hores.",
        19: "Manjari aniya' saga a'a min Sīp patukad ni si Sa'ul ma Gibeya bo' anumbungan iya pasal si Da'ud. Yuk sigām, “Tuwan sultan, wa'i si Da'ud patapuk ma lūngan kami ma Hores, maina'an ma būd Hakila tampal ni satan min lahat Jesemon.",
        20: "Palūd pa'in ka sumiyan-sumiyan katanamannu sabab tantu kami ya atas-pikil anukbalan iya ni ka'a.”",
        21: "Anambung si Sa'ul yukna, “Mura-murahan kam binarakatan e' PANGHŪ' ma sabab pagka'inagonbi ma aku.",
        22: "Pehē' na kam bo' nda'unbi pahāp bang maingga si Da'ud maka bang sai ya bay maka'nda' iya. Kahaka'an aku in si Da'ud aillag makalandu'.",
        23: "Ta'uhunbi kamemon patapukanna bo' kam pabalik pi'itu amissalahan aku bang maingga iya. Jari bang iya masi mahē', ameya' aku ma ka'am. Pihaku iya minsan alatag e'ku kamemon jadjahan ma sakalibut lahat Yuda.”",
        24: "Na, palanjal na saga a'a Sīp inān bo' parahū min si Sa'ul. Pasalta', ina'an si Da'ud maka saga a'ana ma paslangan Ma'on, ma jadjahan Araba tampal ni satan min Jesemon.",
        25: "Si Sa'ul isab maka saga sundaluna anagna' na amiha si Da'ud. Jari tasumbung pa'in ni si Da'ud pasalan pagpiha inān, magtūy iya palanjal ni būd abatu ma paslangan Ma'on ati maina'an iya pahanti'. Pagta'u si Sa'ul isab ma pasalan itu-i, niurul e'na pehē' si Da'ud.",
        26: "Sakali, ina'an disi Sa'ul ma dambila' būd, ati ina'an isab si Da'ud maka saga a'ana ma dambila' magdai'-dai' bo' alahi. Na, baya-baya asekot pa'in si Sa'ul maka saga sundaluna anaggaw si Da'ud,",
        27: "aniya' at'kka pina'an ni si Sa'ul dakayu' sosoho'anna amowa habal, yuk-i, “Tuwan sultan, pakasay lagi' ka. Wa'i kalangpasan lahattam e' saga Pilistin!”",
        28: "Magtūy pahali si Sa'ul min pangapasna ma si Da'ud bo' pehē' angatuhan saga Pilistin. Ya itu sababan angkan kaōnan lugal inān Sela Hammalekot.",
        29: "Sakali in si Da'ud bay patukad minnē' bo' pat'nna' ma saga patapukan ahogot ya ma kabūran En Gedi.",
    },
    24: {
        1: "Na, makabalik pa'in si Sa'ul min kapanurulna ma saga Pilistin, kahaka'an iya in si Da'ud wa'i ma Paslangan En Gedi.",
        2: "Angkan amowa si Sa'ul t'llungibu a'a Isra'il magbobono', a'a bay pene'na, bo' magsakap amiha si Da'ud maka saga a'ana pehē' ni atag Pampang Kambing-talun.",
        3: "Sakali maka'abut disi Sa'ul ni pagkukuralan saga bili-bili ya ina'an ma bihing lān. Aniya' isab songab batu maina'an, ati pasōd si Sa'ul pehē' bo' ajamban. Ina'an asal si Da'ud maka saga a'ana ma deyomna to'ongan.",
        4: "Yuk a'a inān ni si Da'ud, “Tuwan, ya na itu waktu bay pagkallam si Yawe, ya yuk-i, ‘Tukbalanku bantanu ni komkomannu bo' supaya tahinangnu bang ai ya kabilahiannu.’” Jari itu, kamaya'-maya' si Da'ud palele ma halam aniya' makasayuhan iya ati kin'ttob e'na tōng juba si Sa'ul.",
        5: "Tatali'-tali' pa'in e' si Da'ud kapang'ttobna itu, magsusun iya.",
        6: "Yukna ni saga a'ana, “He! S'lle' bale puhu'! Bang pa'in aku sinagga' e' PANGHŪ' bo' mbal makamula a'a bay pene'na nihinang sultan. Halam aniya' kapatutku angahinang kamulahan ma sultanku sabab PANGHŪ' ya bay amat'nna' iya.”",
        7: "Minnē' pinabukagan e' si Da'ud saga a'ana maka sinō' sigām da'a angamula si Sa'ul. Jari ala'an na si Sa'ul min songab batu he'.",
        8: "Pagubus, paluwas si Da'ud bo' angalingan ni si Sa'ul, yukna, “Owa', tuwan Sultan!” Paglingi' si Sa'ul, magtūy pasujud si Da'ud tanda' sin pagaddatna ma iya.",
        9: "Ah'lling si Da'ud yuk-i, “Angay ka akale ma pamitna saga a'a ya ah'lling in aku itu magniyat angamula ka'a?",
        10: "Kasaksi'annu na in ka'a bay pamarūl ma aku e' PANGHŪ' hinabunu lagi' bay ma deyom songab batu. Aniya' sehe'ku bay anoho' aku amapatay ka'a, sagō' halam ka bay inayku. Ya yukku ma sigām, ‘Mbal aku anawakkal angamula nakura'ku sabab PANGHŪ' ya bay amene' iya.’",
        11: "Nda'un ba, bapa', itiya' ma tanganku ya pīs-pīs kakana' bay min jubanu! Bay k'ttobku sagō' halam ka bay papatayku. Na, dongdongin pahāp, in aku itu alipuwas na min dusa niyat amantahan ka'a. Halam aku bay angala'at ka'a sagō' ka'a na pa'in ya angapas aku supaya aku papataynu.",
        12: "Na baya'-baya' PANGHŪ' na angahukum kita karuwangan. PANGHŪ' na isab anungbasan saga kala'atan bay tahinangnu ma aku sagō' in aku baranku mbal anawakkal angamula ka'a.",
        13: "Buwat na yuk papata, ‘Min a'a ala'at paluwas kala'atan,’ angkan mbal ka inayku.",
        14: "In ka'a sultan bangsa Isra'il, ati turulnu a'a halam aniya' pūsna? Aku itu hal sadja ko' kahantang patay ero' atawa kammut.",
        15: "Na baya'-baya' PANGHŪ' angahukum bang sai ma kita taga-kasā'an. Bang pa'in aku binogbogan e'na maka pinuwasan min komkomannu.”",
        16: "Pagubus si Da'ud ah'lling itu, atilaw si Sa'ul. Yukna, “Oto'? Da'ud? Ka'a ka amissala ilu?” Jari anangis to'ongan si Sa'ul.",
        17: "“Abontol lagi' ka min aku,” yukna. “Ahāp ka ma aku saguwā' aku ya bay angala'at ka'a.",
        18: "Na, aheya landu' kahāpan ya tahinangnu ma aku sabab minsan aku bay tinukbalan e' PANGHŪ' ni komkomannu, halam ka anawakkal angamula aku.",
        19: "Aniya' bahā' amasagad bantana alahi ma halam bay minula e'na dahū? Tantu halam. Na, mura-murahan bang pa'in ka tinungbasan e' PANGHŪ' ni kahāpan ma sabab kapangahāpnu aku ma llaw itu.",
        20: "Manantuhi aku in ka'a ilu magsultan maka ahogot in kapagsultannu ma bangsa Isra'il.",
        21: "Buwattina'an, sapahin aku ma matahan PANGHŪ' in aku sampay saga panubu'ku mbal papataynu. Mbal isab lungaynu ōnku min salsila kapanubu'an kami.”",
        22: "Sakali anapa si Da'ud ma si Sa'ul buwat bay amu'na. Pagubus, amole' na si Sa'ul ni luma'na. Malaingkan si Da'ud maka saga a'ana bay patukad pabalik ni bay patapukan sigām e'.",
    },
    25: {
        1: "Manjari amatay na si Samwel ati magtipun kamemon saga a'a Isra'il magdukkahan iya bo' yampa iya kinubul ma atag luma'na ma Rama. Pagubus, in si Da'ud bay palūd ni paslangan Ma'on.",
        2: "Na, aniya' a'a Ma'on landu' dayahan, taga-tana' isab ma kauman Karmel. Aniya' kambingna dangibu hekana maka t'llungibu bili-bilina, jari ina'an iya ma Karmel sabab waktu na panganggunting bulbul saga hayop.",
        3: "Si Nabal ōn a'a itu, maka si Abigail ya ōn h'ndana. Ahāp d'nda si Abigail itu maka ataha' akkalna, saguwā' ab'ngngis sidda h'llana maka ala'at kaul-pi'ilna. Ya si Nabal itu dakayu' panubu' si Kaleb.",
        4: "Hinabu lagi' si Da'ud bay ma paslangan, aniya' makahaka'an iya in si Nabal kono' wa'i magguntingan bulbul saga bili-bilina.",
        5: "Sakali magpanoho'an si Da'ud ma saga onde' baha'u sangpū' hekana. Yukna ma sigām, “Pehē' kam ni si Nabal wa'i ma Karmel bo' iya saginahunbi ma ōnku.",
        6: "Buwattitu pamissalahunbi ma iya, ‘Tuwan, mura-murahan bang pa'in ataha' umulnu. Bang pa'in isab ahāp kuwat-anggawta'nu lapay sampay anak-h'ndanu maka kamemon sasuku ma okomannu.",
        7: "Kahaka'an nakura' kami si Da'ud waktu na kono' pagpagunting saga bili-bili. Ya pamissalana ma ka'a, tuwan, sat'ggol bay kamahē' saga magi'ipat bili-bilinu ma atag pahanti'an kami, halam sigām bay la'at kami. Maka ma waktu kamahē' sigām ma Karmel, halam sigām kalungayan minsan ai na.",
        8: "Tilawun pa'in saga tendognu ilu, tantu du ka nihaka'an e' sigām. Angkan amu'ku ma ka'a, tuwan, pa'nda'in kahāpan saga sosoho'anku itu, pagka kami pasabu ma waktu pagjamu itu. Ndū' tuwan, buwanin lagi' saga sosoho'annu itu maka lahasiya'nu si Da'ud ai-ai na tapamuwannu.’”",
        9: "Pagt'kka saga sosoho'an itu ni si Nabal, magtūy iya pinasampayan lapal bay min si Da'ud. Pagubus, angagad sadja sigām bang ai panambung.",
        10: "Jari anambung si Nabal buwattitu yukna, “Sai sa si Da'ud itu? Sai sa anak si Jesse itu? Ma waktu itu-i aheka na landu' saga banyaga' alahi min pagnakura'an sigām.",
        11: "Angay subay pamuwanku tinapayku maka bohe'ku ni saga a'a mbal minsan takilāku bang minningga? Maka isi susumbali'an bay tagamahanku saga a'a magguguntingan bulbul bili-biliku, pamuwanku bahā' ma daka sai?”",
        12: "Pagka buwattē' panambung si Nabal, amole' ni si Da'ud saga a'ana inān bo' angahaka'an iya kamemon ya bay binissala he' si Nabal.",
        13: "Pagkale si Da'ud magtūy iya magpanoho'an ma saga tendogna, “Takosunbi kalisbi!” Magtūy isab sigām magtinakos. Magtakos kalis isab si Da'ud bo' patukad minnē' maka saga magbobono' mpat hatus hekana. Malaingkan aniya' duwa hatus bay magpa'bba anganjagahan saga balanja' maka kapanyapan sigām.",
        14: "Na, aniya' sosoho'an disi Nabal bay amowa lapal ma si Abigail ya h'ndana, yuk-i, “Babu', si Da'ud bay magpanoho'an ma saga tendogna min paslangan deya lagi'. Sinō' sigām pehē' ni nakura' kami amowa pagaddat si Da'ud ma iya, sagō' bay tumpalakna si Da'ud.",
        15: "Parahāl ahāp sidda addat saga a'a inān ma kami. Halam sigām bay anganjahulaka' kami, maka t'ggol kami ma atag sigām, halam kalungayan minsan dansolag ai-ai kami.",
        16: "Sat'ggol kami magipat saga kahayopan kami ma atag sigām, sigām ya jaga kami llaw-sangom, kahantang ād apagon angalikusan kami.",
        17: "Angkan na, babu', subay ka amikil pahāp bang ai ya tahinangnu ma pasalan palkala' itu, sabab tantu aniya' bala' tum'kka ni nakura' kami sampay ni anak-kampungna. Abigsi' landu' iya angkan halam sai-na makabissalahan iya.”",
        18: "Pagkale si Abigail ma lapal itu, magtūy iya magdai'-dai' magsakap. Angā' iya duwa hatus solag tinapay, duwa kuwit kambing pangisihan binu-anggul, lima bili-bili bay niadjal, lima karut pai-tirigu bay sinanglag, dahatus tundun anggul bay pina'llawan, maka duwa hatus kompolan buwa' pigi, ati pinaruwa' kamemon ni saga kura'.",
        19: "Pagubus, ah'lling iya ni saga sosoho'anna, yukna, “Parahū na kam min aku ati paturul pa'in aku.” Saguwā' halam pinata'u e'na h'llana.",
        20: "Hinabu si Abigail pakura' labay min t'ngnga' kapampangan, ina'an isab si Da'ud maka saga a'ana tudju ni iya. Jari bināk sigām he'na.",
        21: "Baha'u du bay makapah'lling si Da'ud, yuk-i, “Kaliman hulas-sangsā'ku anganjagahan palsuku'an a'a inān mahē' ma paslangan. Halam aniya' bay alungay ma saga ai-aina, sagō' kala'atan ya panungbasna ma kahāpan bay tahinangku.",
        22: "Bang pa'in aku pinagmulka'an e' Tuhan bang aniya' dakayu' l'lla min okoman si Nabal kakapinanku allum pagabut subu!”",
        23: "Pag'nda' si Abigail ma si Da'ud, magtūy iya paruwa'i min kura'na bo' pasujud ma dahuwan si Da'ud.",
        24: "Pasekot-sekot gi' iya bo' magmalulus ma atag tape'na. Yukna ma si Da'ud, “Tuwan, amu'ku ma ka'a, aku ya bīngin. Parūlun lagi' sosoho'annu itu amissala ni ka'a. Kalehun bissalaku itu, tuwan.",
        25: "Ya pangamu'ku ma ka'a, da'a asipun a'a patila'atun inān, ya si Nabal. Magtaluwa' iya maka ōnna, hatina Dupang, pagka karupangan sadja ya kaluwasan saga hinangna. Bo' arapun, ma tongod sin sosoho'annu itu, tuwan, tu'ud halam ta'nda'ku saga a'a ya bay papehē'nu ni h'llaku.",
        26: "“Na, tuwanku, kahandak PANGHŪ' asal angkan halam kalanjalannu amalos magbaran maka amapatay. Angkan sapahanku min ōn si Yawe ya kakkal salama-lama, maka min ōnnu, bang pa'in pasali' ni si Nabal saga palbantahannu maka sasuku anganiyat angamula ka'a.",
        27: "Taima'un isab, tuwan, saga huhulmatan bay bowaku itu bo' pamuwanun ma saga bebeya'annu ilu.",
        28: "Amu'ku junjung isab ni ka'a bang pa'in ampunnu kasā'an ummatnu itu. Tantu pinatatas e' PANGHŪ' in kapagsultannu sampay ni saga panubu'nu magsuring-magsaingsing, sabab palbantahan PANGHŪ' asal saga a'a ya bowanu magbono'. Mura-murahan, tuwan, bang pa'in ka mbal makahinang dusa sat'ggolnu allum.",
        29: "Malaingkan minsan ka pinagturul bo' pinapatay, mbal ka magmula sabab asalamat nyawanu, tinau' pahogot e' PANGHŪ' ma deyom tatau'anna. Sagō' in kallum saga bantanu sapantun batu pinitikan, mbal na tapiha.",
        30: "Bistahun, tuwan, bang ta'abut waktu kapanuman e' PANGHŪ' kamemon saga kahāpan bay panganjanji'na ma ka'a, ati tahinang ka pagmakōkan ma bangsa Isra'il,",
        31: "wajib subay halam aniya' dusanu pagsusunannu. Angkan subay mbal nilanjalan niyatnu amalos atawa amapatay a'a ma halam aniya' po'on-sababna tantu. Jari bang ka nianughala'an na e' Tuhan, ndū', da'a aku kalipatun.”",
        32: "Jari ah'lling si Da'ud ni si Abigail yukna, “Pudji ni si Yawe, ya pagtuhanan bangsa Isra'il, sabab in iya bay anoho' ka'a amāk aku.",
        33: "Bang pa'in iya amuwanan ka'a kahāpan ma sabab kahāp akkalnu llaw itu. Ka'a ya sababan angkan halam kalanjalanku niyatku amapatay a'a llaw itu. Arak aku bay amalos magbaran.",
        34: "Malaingkan, sapahanku min ōn si Yawe, ya Tuhan bangsa Isra'il, in iya bay anagga' aku angamula ka'a. Sabab, bang ka bay halam makasa'ut pi'itu, arak mbal kakapinan minsan dakayu' l'lla min panubu' si Nabal pagk'llat llaw.”",
        35: "Sakali tinaima' na e' si Da'ud saga bobowahan si Abigail maka e'na ah'lling, yuk-i, “Amole' na ka ma halam aniya' kahanggawannu. Beya'ku kamemon ya bay junjungnu ilu ma aku.”",
        36: "Manjari amole' na si Abigail. Magsalta', si Nabal bay amaniya' paglami-lami ma luma'na, buwat sapantun kahinangan pagjamu sultan. Nilango to'ongan si Nabal maka magkakoyagan, angkan halam iya binissalahan ai-ai e' si Abigail sampay ni kasubuhan.",
        37: "Pagsubu pa'in bo' palabay na lango si Nabal, binissalahan iya e' h'ndana pasal kamemon bay paniya' ma pagsampangna maka si Da'ud. Pagkale si Nabal, magtūy ap'ddi' kōk atayna ati anuwas baranna.",
        38: "Palabay pa'in saga sangpū' llaw, amatay iya min kawasa PANGHŪ'.",
        39: "Pagta'u si Da'ud ma pasal kamatay si Nabal, ah'lling iya, yukna, “Pudji ni PANGHŪ' ya bay amalosan aku ma si Nabal ma sabab kapangahina'na ma aku. Tuhan ya bay angaliyusan aku min hinang kala'atan ati papelleng ni a'a inān saga kahinanganna ala'at.” Pagubus magpanoho'an si Da'ud amah'nda si Abigail ati",
        40: "pehē' saga sosoho'anna ni Karmel amowa lapal ni si Abigail, yuk-i, “Bay kami pinapi'itu e' nakura' kami si Da'ud supaya amah'nda ka'a.”",
        41: "Pasujud magtūy si Abigail maka he'na anambung, yukna, “Aku itu atabi, sakap aku amahilala' ka'am sampay angose'an tape'bi.”",
        42: "Ati magdai'-dai' ya pakura' ni kura'na bo' pabunyug ma saga sosoho'an si Da'ud. Sinehe'an isab iya e' lima ipatanna d'nda. Minnē' iya ta'ā' h'nda e' si Da'ud.",
        43: "Tah'nda isab e' si Da'ud si Ahinowam d'nda min Jesde'el, jari magkalu'a sigām karuwangan.",
        44: "Saguwā' si Mikal, ya bay h'nda si Da'ud po'on, wa'i pamah'nda e' si Sa'ul ma si Paltiyel ya anak si Lais, a'a min Galim.",
    },
    26: {
        1: "Na, aniya' saga a'a min lahat Sīp bay pehē' ni si Sa'ul hinabuna ma Gibeya supaya anumbung pasal si Da'ud. “Tuwan sultan,” yuk sigām, “ina'an si Da'ud patapuk ma būd Hakila ya ma anggopan Jesemon.”",
        2: "Manjari, pehē' ni paslangan Sīp si Sa'ul maka t'llungibu a'a Isra'il magbobono' ya bay pene'na, bo' amiha si Da'ud.",
        3: "Bay magpustu asal si Sa'ul ma bihing lān, ina'an ma būd Hakila ma anggopan Jesemon, malaingkan in si Da'ud wa'i ma paslangan. Pagta'u si Da'ud pasal si Sa'ul bay anurul iya pina'an,",
        4: "aniya' saga a'a soho'na pehē' ang'nda'. Jari tata'una min sigām, b'nnal, ina'an na si Sa'ul.",
        5: "Sakali, magsakap si Da'ud bo' pehē' ni atag pagpustuhan si Sa'ul. Ta'nda'na bang maingga patulihan si Sa'ul maka si Abner ya pagnakura'an kamemon saga sundaluna. Si Abner itu anak si Nēr. Na, ma waktu inān, in si Sa'ul atuli ma pustu, ma t'ngnga'-t'ngnga' ba'anan saga bobono'na.",
        6: "Na, atilaw si Da'ud ma si Ahimelek a'a bangsa Hīt maka si Abisai ya danakan si Jowab. (Si Seruya ya ina' sigām). Yuk panilaw si Da'ud, “Sai ameya' ma aku palūd ni si Sa'ul ma pustu inān?” Anambung si Abisai. “Aku,” yukna.",
        7: "Angkan sangom he'-i du, nil'ngngan pustu si Sa'ul e' si Da'ud maka si Abisai ati ta'nda' sigām si Sa'ul atuli maina'an. Ina'an paosol budjakna ma tana' min kōkanna, maka ina'an isab si Abner maka saga sundalu kasehe' atuli ma katilibutna.",
        8: "Maina'an pa'in, pahigung-higung si Abisai ni si Da'ud, yukna, “Tuwan, ya na itu waktu panukbal bantanu ni ka'a e' Tuhan. Dūlin aku amudjak iya ni tana'. Pamint'ddaku sadja.”",
        9: "Saguwā' yuk sambung si Da'ud, “Oy! Da'a iya bono'un! Sabab tantu tinungbasan e' Tuhan sasuku angamula sultan ya tapene'na.",
        10: "Sapahanku ma ōn si Yawe, ya Tuhan kakkal salama-lama,” yuk si Da'ud, “Tuhan sadja ya magkahandak ma ganta'an si Sa'ul. Bang ngga'i ka patay saki atawa patay to'a, amatay iya ma pagbono'an.",
        11: "Sagō' s'lle'-bale puhu' pinatā e' PANGHŪ' bang pa'in mbal tamulaku a'a bay tapene'na magsultan ilu. Na, ngā'un na budjak maka pangisihan bohe' ya ma atag kōkna ilu bo' kita sūng na!”",
        12: "Jari ningā' e' si Da'ud budjak maka pangisihan bohe' ya bay ma kōkan si Sa'ul ati ala'an na sigā. Halam aniya' minsan sai makata'u atawa maka'nda' sigām maka halam minsan sai bay makabati'. Ahaluk sidda tuli sigām kamemon sabab PANGHŪ' ya bay amahaluk sigām.",
        13: "Sakali itu, palintas na si Da'ud ni dambila' kapantayan bo' an'ngge maina'an ma būd, atā-tā min disi Sa'ul. Asal aluha pag'llotan sigām.",
        14: "Manjari, angolang si Da'ud ni saga sundalu si Sa'ul maka ni si Abner, yukna, “Owa' Abner! Mbal aku sambungannu?” Anambung si Abner yukna, “Sai sa ka angolangan sultan ilu?”",
        15: "Yuk si Da'ud, “L'lla ka bahā' Abner? Bang pina'amu, halam sali'nu ma Isra'il! Na, angay halam jagahannu pahāp sultan ya pagpanghū'annu ilu? Sabab aniya' a'a bay pasōd pi'ilu arak angamula iya.",
        16: "Mbal ahāp hinangnu ilu! Sapahanku ma ōn si Yawe ya kakkal salama-lama, in ka'a maka saga sehe'nu ilu patut subay pinapatay sabab halam bay jagahannu nakura'nu, ya bay tapene' e' PANGHŪ'. Ang'nda' ka ni katilibutnu. Maingga na budjak sultan maka pangisihanna bohe' ya bay ma kōkanna ilu?”",
        17: "Takilā magtūy e' si Sa'ul suwala si Da'ud angkan iya ah'lling, yukna, “Da'ud, oto'! Ka'a ka amissala ilu?” Anambung si Da'ud, yukna, “Aho' tuwan sultan, aku ko' itu.”",
        18: "Ah'lling lagi' si Da'ud, “Tuwan,” yukna, “kasā'an ai bay tahinang e' sosoho'annu itu angkan aku subay papataynu? Abontol sadja itikadku angkan mbal aku katōngan dusa.",
        19: "Da'a busung, tuwan sultan, kalehun lagi' pah'llingku itu. Bang hati PANGHŪ' ya bay anoho' ka'a amantahan aku, na, tukbalun lalabotan ni iya. Kalu tinaima' e'na. Saguwā' bang manusiya' ya amitnahan ka'a, bang pa'in sigām taluwa' sukna' PANGHŪ'. Sabab itiya' aku tin'ggal paluwas min lahat bay pamusaka' aku e' PANGHŪ', lāgi sinoho' isab aku magsumba ni saga katuhan-tuhanan bangsa liyu.",
        20: "Ndū' tuwan,” yuk si Da'ud, “da'a aku pasagarin amatay ma lahat bangsa liyu, alawak min matahan si Yawe. Angay aku subay piniha e' sultan bangsa Isra'il? Aku itu sapantun kutu ero' ya pihanu ma kabūd-būran, buwat a'a amiha manuk-manuk.”",
        21: "Jari anambung si Sa'ul, yukna, “Bay aku makarusa. Ndū' Da'ud, oto', bang pa'in ka pabalik ni aku. Pagka ahalga' ma ka'a kallumku itu, mbal na balikanku niyatku amapatay ka'a. Sali' aku dupang, aheya kasā'an bay tahinangku ma ka'a.”",
        22: "“Ā, itiya' budjaknu tuwan sultan,” yuk sambung si Da'ud ma si Sa'ul. “Soho'un pi'itu dakayu' tendognu ilu angā'.",
        23: "Baya'-baya' PANGHŪ' na anungbas ni kahāpan ma saga a'a sasuku abontol maka kapangandolan.” Ah'lling gi' si Da'ud yukna, “Ka'a tuwan, bay tinukbalan e' PANGHŪ' ni komkomanku insini', sagō' halam aku makatawakkal angamula ka'a sabab in ka'a sultan bay tapene' e' Tuhan.",
        24: "Mura-murahan bang pa'in aku pinagka'inagonan e' PANGHŪ' maka niliyusan e'na min kamemon katiksa'anku, buwat bay pagka'inagonku ma ka'a insini'.”",
        25: "Sakali ah'lling na si Sa'ul ni si Da'ud, yukna, “Oto', bang pa'in ka nilidjiki'an e' PANGHŪ'. Tantu ajatu ai-ai kamemon ya tagna'annu, maka anganda'ug sadja ka ma pagbono'an.” Pagubus, palanjal na si Da'ud ni pal'ngngananna, maka amole' na si Sa'ul ni lahatna.",
    },
    27: {
        1: "Saguwā' minsan buwattē' bissala si Sa'ul, maghona'-hona' na pa'in si Da'ud bo' yukna ma deyom atayna, “Tantu aku binono' e' si Sa'ul ma llaw sinosōng. Ahāp lagi' aku alahi pehē' ni lahat Pilistin. Pahali si Sa'ul amiha aku bang aubus e'na angalatag katilingkal lahat Isra'il, ati alipuwas aku min iya.”",
        2: "Jari si Da'ud maka saga a'ana nnom hatus hekana bay palanjal minna'an bo' palain ni da'ira Gāt, ni sultan Akis ya anak si Ma'ok.",
        3: "Sakali maina'an sigām pahanti' ma Gāt, ma okoman si Akis. Maina'an sigām pahanti' ma okoman sultan e', sigām kaniya-kaniya maka anak-h'nda sigām. Ina'an isab si Da'ud maka duwa h'ndana, ya na si Ahinowam min Jesde'el maka si Abigail min Karmel, ya bay balu si Nabal.",
        4: "Jari kahaka'an pa'in si Sa'ul in si Da'ud wa'i na makalahi ni Gāt, pahali na iya amiha.",
        5: "Palabay pa'in waktu, ah'lling si Da'ud ni si Akis, yukna, “Tuwan, bang ka kasulutan du ma aku, pamarūlun ma aku dakayu' kaumannu bo' supaya aku makapaglahat mahē'. Mbal patut sosoho'annu itu paokom ma ka'a ma da'ira bangsahan itu.”",
        6: "Angkan ma llaw ina'an du, pamuwan e' si Akis ma si Da'ud kauman Siklag. Jari in kauman inān tahinang palsuku'an saga sultan bangsa Yuda sampay ni kabuwattina'anan.",
        7: "Saga dantahun maka mpat bulan ya kapaglahat si Da'ud ma deyoman saga bangsa Pilistin.",
        8: "Na ma waktu inān, angalangpas na pa'in si Da'ud maka saga tendogna ni saga bangsa Gesur, bangsa Girsi maka bangsa Amalek. Saga bangsa itu bay asal maina'an min awal lagi'. Ya paglahat sigām pa'abut ni Sūr, sampay isab ni lahat Misil.",
        9: "Sakahaba' waktu kalangpas si Da'ud ni kaluma'an saga bangsa itu, halam aniya' kapinanna allum minsan dakayu' d'nda ka atawa l'lla. Ya nilangpas e'na saga bili-bili maka sapi' sampay saga kura' maka unta' maka pan'mmek. Jari pabalik na pa'in iya ni si Akis.",
        10: "Bang tinilaw si Da'ud e' si Akis bang pi'ingga bay parugpakanna, anambung iya buwattitu, yukna, “Bay kami parugpak ni lahat Yuda tampal ni satan.” Suma'an buwattitu panambungna, “Bay kami ni lahat Jerame'el tampal ni paslangan.” Atawa, “Bay kami pehē' ni kauman bangsa Kēn ya ma paslangan isab.”",
        11: "Mbal kinapinan allum e' si Da'ud minsan dakayu' d'nda atawa l'lla allum, sabab ma pikilanna, “Ya aniya', bang aniya' l'lla atawa d'nda binowa ni Gāt, makasumbung lagi' sigām bang ai bay tahinangku.” Buwattē' kahinangan si Da'ud t'ggolna pat'nna' ma lahat Pilistin.",
        12: "Manjari, pangandolan iya e' si Akis sabab yukna ni baranna, “Tantu kinab'nsihan na si Da'ud itu e' saga pagkahina bangsa Isra'il, angkan halam dapat bang iya mbal amogbogan aku sat'ggolna allum.”",
    },
    28: {
        1: "Manjari palabay pa'in waktu, pinapagtipun saga sundalu bangsa Pilistin supaya amowa magbono' ma bangsa Isra'il. Ah'lling si Akis ni si Da'ud, yukna, “Tahatinu du in ka'a maka saga tendognu ilu subay pagapi' ma aku ma pagbono'an.”",
        2: "Anguyun si Da'ud, yukna, “Na, tuwan, song ta'nda'nu bang ai tahinang e' sosoho'annu itu.” Anambung si Akis, “Ahāp ko' ilu. Angkan na ka hinangku jaga ma baranku sat'ggolku allum.”",
        3: "Malaingkan in si Samwel bay na asal amatay. Bay na iya pinagdukka'an e' kamemon saga jama'a Isra'il, ati wa'i bay kinubul e' sigām ma Rama, ya lahatna luggiya'. Ma waktu he'-i, bay na asal tin'ggal e' si Sa'ul kamemon saga a'a magpang'nda' umagad maka saga magjijīn min lahat Isra'il.",
        4: "Sakali itu, magtipun na saga sundalu Pilistin bo' pehē' magpustu ma Sunem. Pasalta' in si Sa'ul bay amatimuk saga sundaluna bangsa Isra'il bo' magpustu ma Gilbowa.",
        5: "Pag'nda' si Sa'ul ma ba'anan sundalu Pilistin, magtūy iya sinōd tāw mbal tapula'-pula'.",
        6: "Angkan iya angaru ni PANGHŪ' bang ai subay hinangna, sagō' halam aniya' lapal PANGHŪ' pinasampay ma iya, ai naka ma uppina, ai naka min Urim atawa min saga nabi.",
        7: "Pagka buwattē', ah'lling si Sa'ul ni saga tendog ya pangandolanna, yukna, “Piha'inbi aku d'nda maglilingan umagad bo' supaya aku makapangaru ma iya.” “Tuwan,” yuk sambung saga tendog inān, “aniya' kono' maina'an ma kauman Endor.”",
        8: "Sakali itu, magbinadju' saddī si Sa'ul supaya halam aniya' makakilā iya. Jari sangom inān pehē' na iya maka duwa tendogna ni luma' d'nda. Makat'kka pa'in, yuk si Sa'ul ni iya, “Bilahi aku angaru ni umagad a'a bay amatay. Tugila'ku pa'in ma ka'a bang sai subay linganannu.”",
        9: "Sagō' yuk sambung d'nda, “Tantu kasakupannu bang ai ya bay panoho'an si Sa'ul. Bay pala'anna min lahat Isra'il kamemon saga a'a maglilingan umagad maka saga magjijīn. Tu'ud ko' ka'a ilu pasulay anganjallat aku bo' supaya aku pinat'nna'an hukuman ni kamatay.”",
        10: "Pagga buwattē' anapa si Sa'ul, yukna, “Sapahanku ma ōn si Yawe, ya kakkal salama-lama, halam aniya' kamulahan tum'kka ni ka'a ma sabab palkala' itu.”",
        11: "Jari tinilaw na iya e' d'nda inān, yukna, “Umagad sai kabilahiannu lingananku?” “Umagad si Samwel,” yuk sambung si Sa'ul.",
        12: "Pag'nda' pa'in d'nda inān ma umagad si Samwel, magtūy iya angolang pakosog maka e'na atilaw ma si Sa'ul, yukna, “Angay aku bay akkalannu? Ka'a tuwi' sultan Sa'ul!”",
        13: "Sakali yuk sultan ma iya, “Da'a ka tināw. Ai ta'nda'nu ilu?” Ya sambung d'nda, “Tuwan,” yukna, “maka'nda' aku umagad pabungkal min tana'.”",
        14: "Atilaw si Sa'ul, yukna, “Buwattingga luwana?” “Matto'a l'lla magjinuba,” yuk sambung d'nda inān. Manjari kinata'uwan magtūy e' si Sa'ul si Samwel na ko' inān, angkan iya pasujud.",
        15: "Yuk si Samwel ni iya, “Angay lagi' aku sasatnu pagka aku bay soho'nu pinabangun?” Anambung si Sa'ul, yukna, “Landu' aheya kasukkalanku. Itiya' aku binono' e' saga a'a Pilistin, maka tinaikutan na aku e' PANGHŪ'. Mbal na sinambungan pangaruku, ai naka ma uppi atawa pinalabay min saga nabi. Angkan ka bay soho'ku pinalinganan bo' supaya aku pituwahannu bang ai subay hinangku.”",
        16: "Yuk si Samwel, “Angay lagi' aku subay pangaruhannu saukat ka bay tinaikutan maka binantahan e' PANGHŪ'?",
        17: "Tahinang na e'na ya bay pagkallamna labay min aku. Ilu na niragtu' e'na min ka'a kapagsultannu bo' pamuwanna na ma dakayu' pagkahinu, ya na si Da'ud.",
        18: "Angkan itu nihinang e' PANGHŪ' ma ka'a buwattina'an sabab halam bay beya'nu panoho'anna. Halam bay pasampaynu mulka'na ma saga bangsa Amalek.",
        19: "Jari in ka'a maka saga bangsa Isra'il marai' na tinukbalan e' PANGHŪ' ni komkoman bangsa Pilistin. Pagsalung,” yuk umagad si Samwel, “ka'a maka saga anaknu l'lla parakayu' du ma aku maitu ma ahirat. Damikiyanna isab saga sundalu bangsa Isra'il, tinukbalan e' PANGHŪ' ni komkoman bangsa Pilistin.”",
        20: "Saru'un-du'un du magtūy kum'ppang si Sa'ul ni tana', maka sinōd iya tāw landu' aheya ma pasalan pamissala si Samwel he'. Na, alamma si Sa'ul pagka halam bay amangan animpus dang'llaw maka dasangom.",
        21: "Manjari pasekot d'nda he', ati ta'nda'na ina'an si Sa'ul amidpid kabowa tāwna, angkan yukna, “Tuwan sultan, bay na beya'ku panoho'annu. Bay panūkku kallumku ni kamatay sabab pameya'ku ma panoho'annu.",
        22: "Ndū' Tuwan,” yukna, “da'a busung, kalehun lagi' pamissala sosoho'annu itu maka dūlin aku angadjalan ka'a takakan bo' supaya pabalik kosognu ati bo' ka makalanjal ni pal'ngnganannu.”",
        23: "“Ē! Mbal aku amangan!” yuk sambung si Sa'ul. Sagō' magbeya' saga tendog maka d'nda inān amogos na pa'in si Sa'ul, sampay iya tapogosna. Pagubus, pabangun iya min tana' bo' aningkō' ma pabahakanna.",
        24: "Na, aniya' anak sapi' al'mmok taipat e' d'nda inān, magtūy sinumbali' e'na. Angaddun isab iya tirigu bo' hinangna tinapay halam taga-pasulig.",
        25: "Atahak pa'in, pinat'nna' na e'na ni si Sa'ul maka saga tendogna ati amangan sigām. Pagubus, ma sangom he'i du, palanjal na sigām amole'.",
    },
    29: {
        1: "Na, magtipun na kamemon sundalu bangsa Pilistin ma Apek, ati in sundalu bangsa Isra'il ina'an magpustu ma atag tigbaw ma Jesde'el.",
        2: "Pal'ngngan na pa'in saga pagnakura'an bangsa Pilistin magbeya' maka saga tumpukan sundalu sigām ma hatusan maka ma ibuhan. Pasalta', ina'an isab si Da'ud maka saga a'ana pal'ngngan min buli'an magabay maka sultan Akis.",
        3: "Atilaw isab saga nakura' kasundaluhan Pilistin ma si Akis, yuk-i, “Magay saga Hibrani itu?” Anambung si Akis, yukna, “Si Da'ud ko' ilu, ya bay tendog si Sa'ul, ya sultan bangsa Isra'il e'. Aniya' na iya labi dantahun ma deyomanku. Min waktu lagi' kala'anna min okoman si Sa'ul sampay ni kabuwattina'anan, halam iya karapatanku.”",
        4: "Sagō' akagit atay saga nakura' sundalu inān ma si Akis angkan yuk sigām, “Papole'un a'a ilu ni kauman bay pamuwannu paglahatan ma sigām. Mbal iya wajib pabunyug ma kitam ni pagbono'an! Sabab ya aniya' papinda angatuhan kitam hinabu ma pagbono'an. Tantu iya amonggolan kōk saga sundalutam bo' supaya iya makapaghāp maka sultan ya bay nakura'na.",
        5: "Ya na ko' ilu si Da'ud, ya pinagkalang e' saga kar'ndahan, yuk-i, ‘Ibuhan tapapatay e' sultan Sa'ul, ati hatusan ibu isab ma si Da'ud’.”",
        6: "Manjari, pinalinganan si Da'ud e' si Akis bo' binowa magbissala. Yuk si Akis ma iya, “Sapahanku ma ōn si Yawe, ya kakkal salama-lama, in ka'a ilu kapangandolan angkan kasulutan sidda aku bang ka ganta' pabunyug ma aku maka saga sundaluku. Min waktu lagi' kat'kkanu sampay ni kabuwattina'anan, halam aniya' kasā'an tabākku ma ka'a. Sagō' mbal kasulutan saga pagkahiku nakura' Pilistin.",
        7: "Angkan amole' na ka ma halam aniya' lengog. Maka da'a ka angahinang ai-ai ya makala'at pangatayan sigām kasehe' itu.”",
        8: "“Angay tuwan? Ai dusaku?” yuk si Da'ud. “Ai kasā'an bay tahinang e' tendognu itu min waktu katagna'ku paokom ma ka'a sampay ni waktu itu? Ai sababanna ya angkan aku mbal makajari ameya' ma ka'a amono' saga a'a ya amantahan ka'a, tuwan sultan?”",
        9: "Anambung si Akis, yukna, “Kasulutan sidda aku ma ka'a, sapantun ka mala'ikat Tuhan ma pang'nda'ku. Malaingkan, bay makakabtang saga nakura' Pilistin in ka'a kono' mbal wajib ameya' ma kami ni pagbono'an.",
        10: "Angkan yukku ma ka'a, in ka'a maka saga tendog si Sa'ul ya sehe'nu ilu subay angawal salung bo' magla'anan minnilu ma halam gi' pak'llat llaw.”",
        11: "Sakali, pagdai' llaw pa'in, pabungkal na si Da'ud maka saga a'ana bo' amole' pabīng ni lahat Pilistin. Sagō' in saga sundalu Pilistin patukad na ni da'ira Jesde'el.",
    },
    30: {
        1: "Manjari itu, pagpuwas pa'in t'llung'llaw, at'kka na si Da'ud maka saga a'ana ni Siklag ya kauman sigām. Sagō' waktu sigām lagi' bay ma labayan, in kauman Siklag sampay lahat Yuda tampal ni s'ddopan inān bay nirugpak e' bangsa Amalek. Tatunu' isab e' sigām saga kaluma'an ma kauman Siklag,",
        2: "tasaggaw isab kamemon kar'ndahan sampay saga a'a kamemon onde'-matto'a ya bay maina'an. Malaingkan halam aniya' bay pinapatay minsan dakayu', hal bay sinaggaw e' saga a'a Amalek bo' binowa ala'an.",
        3: "Na, pagt'kka si Da'ud maka saga a'ana ni kauman Siklag inān, ta'nda' e' sigām atunu' kamemon, maka saga anak-h'nda sigām wa'i bay nilahiyan.",
        4: "Angkan maglemong disi Da'ud sampay sigām apaya na e' paglemong sigām.",
        5: "Ya karuwangan h'nda si Da'ud, ya si Abigail maka si Ahinowam, wa'i du talapay tasaggaw.",
        6: "Aheya isab kasusahan si Da'ud sabab pinagbambahan iya binantung e' saga a'ana kabowa astol sigām ma pasalan kasaggaw saga anak sigām d'nda-l'lla. Malaingkan pakosog iman si Da'ud ma sabab pangandolna ma si Yawe ya Tuhanna.",
        7: "Manjari ah'lling si Da'ud ni imam Abiyatar ya anak si Ahimelek. Yukna, “Tuwan, bowahin aku pi'itu epod e'.” Sakali binowa na ni iya e' si Abiyatar.",
        8: "Maina'an pa'in, angaru si Da'ud ni PANGHŪ', yukna, “Wajib bahā' aku paturul ni saga a'a bay parugpak ni kauman itu? Ta'abutku bahā' sigām?” Anambung PANGHŪ', yukna, “Aho', turulun sigām pehē'. Tantu sigām ta'abutnu maka talappasnu saga anak-h'ndabi.”",
        9: "Sakali, lum'ngngan na si Da'ud magbeya' maka saga a'ana nnom hatus puhu'. Makat'kka pa'in sigām ni L'bbak Besor, magpa'bba maina'an in kasehe'an sigām.",
        10: "Aniya' duwa hatus puhu' ma sigām magbale'an to'ongan angkan mbal makatukad ni pampang ya ma dambila' l'bbak inān. Malaingkan in si Da'ud maka mpat hatus a'ana bay palanjal angapas saga bangsa Amalek.",
        11: "Na, aniya' a'a Misil talanggal e' sigām ma huma, jari binowa iya e' sigām ni si Da'ud. Binuwanan iya takakan maka bohe' ni'inum.",
        12: "Ya pamakan sigām ma iya buwa' igira bay kinompol maka duwa tundun anggul bay pina'llawan. Bay pa'in iya makakakan, pahāp na palasahanna pabalik, sabab halam iya bay makakakan ai-ai atawa makainum bohe' ma deyom t'llung'llaw t'llumbahangi.",
        13: "Manjari, tinilaw iya e' si Da'ud, yukna, “Sai nakura'nu, maka m'nningga ka?” Anambung l'lla inān, yukna, “Tuwan, aku itu bangsa Misil. Banyaga' aku ma dakayu' a'a bangsa Amalek. Bay aku pinasagaran e'na t'llung'llaw na palabay pagka aku bay asaki.",
        14: "Bay kami parugpak ni lahat s'ddopan, ni tana' bangsa Keret maka ni kauman ya palsuku'an saga bangsa Yuda, maka ni tana' isab saga panubu' si Kaleb. Bay isab tunu' kami kauman Siklag.”",
        15: "Atilaw si Da'ud pabalik, yukna, “Katuli'annu aku pehē' ni saga bangsa Amalek he'?” “Aho' tuwan,” yuk sambung l'lla inān. “Kasehe'anta ka pehē' ni sigām bang pa'in sapahannu ma matahan Tuhan in aku mbal papataynu atawa tukbalannu pabalik ni bay nakura'ku.”",
        16: "Na, sinehe'an na si Da'ud e' l'lla bangsa Misil inān palūd pehē' ni saga bangsa Amalek. Ina'an sigām magkaukanat ma lugal pagpustuhan sigām, magkakanan maka maginuman. Aheya paglami-lami sigām ma sabab kaheka pangalta' bay tataban sigām min paglahat bangsa Pilistin maka min Yuda.",
        17: "Binono' magtūy sigām e' disi Da'ud min kohap inān sampay ni kasangoman ma llaw dakayu'. Halam aniya' minsan dangan min saga a'a Amalek bay makal'ppa, luwal mpat hatus onde' baha'u bay pakura' ma unta' alahi.",
        18: "Ta'ā' pabalik e' si Da'ud kamemon bay tataban e' bangsa Amalek, beya' na duwangan h'ndana.",
        19: "Ta'ā' e'na kamemon, halam kakulangan minsan dansolag, ai naka onde'-matto'a, d'nda ka atawa l'lla. Ta'ā' sampay saga pangalta' bay tataban aheya-ariki'.",
        20: "Ta'ā'na isab kamemon saga bili-bili maka saga kahayopan, bo' pinal'ngngan e' saga a'ana min dahuwan sigām. Ya pagpa'in sigām, “Palsuku'an si Da'ud tatabanan itu kamemon.”",
        21: "Na, pabīng na si Da'ud ni saga a'ana duwa hatus hekana ya ina'an bay magpa'bba ma L'bbak Besor pagka sigām bay landu' apaya. Jari pasōng saga a'a itu amāk si Da'ud maka ba'anan saga sehe'na. Asekot pa'in disi Da'ud, sinagina sigām pahāp.",
        22: "Malaingkan aniya' saga a'a asabul maka ala'at kasuddahanna pabeya' asal ma si Da'ud. Yuk saga a'a itu, “Mbal sigām patut pinahampit saga tatabanan ilu sabab halam sigām bay ameya' ma kitam. Sagō' makajari sigām angā' saga anak-h'nda sigām bo' magpole'an na.”",
        23: "“Mbal manjari, saga danakan,” yuk sambung si Da'ud. “Da'a kam maghinang buwattilu ma bay tahinang e' PANGHŪ' ma kitam. Bay kitam nihampanan e'na, maka bay tukbalanna ni deyom komkomantam saga a'a ya bay amono' kitam.",
        24: "Mbal tabeya' kabilahianbi ilu, kalna' in bahagi' a'a bay magpa'bba anunggu'an saga balanja' subay pinapagsali' maka bahagi' a'a bay ameya' ni pagbono'an. Pinapagtopod in bahagi' dangan maka dangan.”",
        25: "Ya sara' bay pinaniya' e' si Da'ud itu binogbogan na pa'in e' bangsa Isra'il sampay ni kabuwattina'anan.",
        26: "Na, makabalik pa'in si Da'ud ni Siklag, bay pinabeya' e'na kasehe' tatabanan ni saga bagayna ya pagmatto'ahan ma Yuda. Aniya' isab lapalna, yukna, “Itu saga tatabanan bahagi'bi min saga a'a banta PANGHŪ'.”",
        27: "Bay isab binahagi'an e'na saga a'a ma Betel, ma Ramot-ni-S'ddopan maka ma Jattir.",
        28: "Binahagi'an isab saga a'a ma Arower, ma Sepmot, ma Estemowa,",
        29: "maka ma Rakal. Ya du saga a'a ya magsakaum ma bangsa Jerame'el maka bangsa Kēn,",
        30: "saga a'a isab ma Horma, ma Bōr Asan, maka ma Atak,",
        31: "sigām isab ma Hebron sampay ma kasehe'an paglahat ya bay pahanti'an si Da'ud maka saga a'ana.",
    },
    31: {
        1: "Manjari itu, parugpak saga Pilistin ni saga sundalu bangsa Isra'il ati aheka bangsa Isra'il amatay ma Būd Gilbowa. Malaingkan in kasehe'an bay makalahi.",
        2: "In si Sa'ul magtai'anak bay niabut-abut e' saga sundalu Pilistin ati tapapatay e' sigām si Jonatan, si Abinadab maka si Malki-Suwa.",
        3: "Paruhun na pa'in pagbono' ma atag si Sa'ul, ati tasekot pa'in iya e' a'a magpapana', ahalol iya e' sigām.",
        4: "Angkan iya ah'lling ni a'a magbobowa pakokosna, yukna, “Hublutun na kalisnu ilu bo' aku papatayun, pād-pād saga kapil itu angandugsu'an aku maka anganjahulaka'an baranku.” Saguwā' landu' tināw magbobowa pakokos inān angkan mbal tahinangna panoho'an si Sa'ul e'. Pagka buwattē', ningā' e' si Sa'ul kalisna bo' iya amapatay di-na.",
        5: "Pag'nda' magbobowa pakokos in si Sa'ul amatay na, ya du iya bay angahublut kalisna bo' amapatay di-na.",
        6: "Angkan ma llaw inān, magbeya' amatay si Sa'ul maka t'llungan anakna l'lla, maka magbobowa pakokosna, sampay isab kamemon saga sundalu bay ma iya.",
        7: "Na, pasampay habal itu ni saga a'a Isra'il ya maglahat ma kapantayan Jesde'el maka ma dambila' sapa' Jordan, ati tata'u na e' sigām in saga sundalu Isra'il wa'i maglahian maka in si Sa'ul sampay saga anakna wa'i na amatay. Pagta'u itu, ni'bbahan e' sigām saga kaluma'an sigām bo' alahi. Jari pina'an na saga bangsa Pilistin maglahat ma bay kaluma'an bangsa Isra'il e'.",
        8: "Pag'llaw dakayu', makapina'an pa'in saga bangsa Pilistin ni būd Gilbowa angā' ai-ai kagunahan min bangkay saga bangsa Isra'il, tabāk e' sigām mayat si Sa'ul maka saga anakna.",
        9: "Pinonggolan e' sigām kōk si Sa'ul maka niurusan saga pakokosna, ati sinō' pinasaplag habal itu ma katilingkal paglahat Pilistin sampay ma langgal saga tuhan-tuhan sigām.",
        10: "Manjari pinat'nna' pakokos si Sa'ul ma langgal saga tuhan-tuhan sigām Astoret, ati in baranna bay nilansang ma ād ya ma likusan da'ira Bet-Sān.",
        11: "Pagta'u saga a'a Jabes Giliyad ma bay tahinang a'a Pilistin ma bangkay si Sa'ul,",
        12: "magtūy palanjal saga a'a sigām ya tamakaesog. Animpus sigām sangom bo' pehē' ni Bet-Sān. Ningā' e' sigām saga bangkay disi Sa'ul maka saga anakna min ād Bet-Sān inān bo' binowa ni Jabes, ati mahē' tinunu'.",
        13: "Tatunu' pa'in, ningā' saga to'olang inān ati kinubul ma deyo'an kayu tamaris ya maina'an ma lahat Jabes. Pagubus, magpuwasa saga a'a Jabes inān ma deyom pitung'llaw.",
    },
}
